  // ===== Doku-Datenquelle: Erklaerungen und Demo-Konfiguration je Widget ==============
  //
  // ERZEUGT, ABER GEPFLEGT: Diese Tabelle wird nicht automatisch aus dem Code abgeleitet.
  // Die Doku-Seite selbst entsteht aus der Widget-Registry - neue Widgets erscheinen also
  // von allein, aber OHNE Text und ohne Demo-Werte. Wer ein Widget anlegt, aendert oder
  // erweitert, traegt es hier nach. Ein Widget ohne Eintrag zeigt nur seinen Typnamen.
  //
  // demo: Eigenschaften fuer eine LIVE lauffaehige Vorschau. Die varId-Angaben sind ECHTE
  // Variablen dieser Anlage - die Vorschauen zeigen daher wirkliche Werte und sind bedienbar.
  var DOKU_INFO = {
    "alarm": {"titel":"Alarm","zweck":"Regelgesteuerte Alarm-Karte: eine abgerundete, getoente Karte aus Icon-Box, fettem Titel und gedaempfter Unterzeile - sichtbar nur, wenn eine Bedingung erfuellt ist; sonst blendet sie sich vollstaendig aus und nimmt keinen Platz. Nutzbar als Einzelmeldung oder als Kind im Alarm-Panel.","funktionen":[{"name":"Variable","beschreibung":"Quelle der Bedingung (das Feld „Variable\" oben): eine ID oder eine =Formel (#id + Literale). Ihr Wert wird gegen den Vergleich geprueft; ist er erfuellt, erscheint die Karte."},{"name":"Bedingung","beschreibung":"Drei Modi: „Variable vs. Konstante\" (Operator + Schwelle), „Variable vs. Variable\" (Operator + zweite Variable) oder „Vergleichsliste\". Operatoren <, <=, ==, !=, >=, >."},{"name":"Operator / Schwelle","beschreibung":"In den ersten beiden Modi: Vergleichsoperator und - bei „vs. Konstante\" - der numerische Schwellwert, gegen den die Variable geprueft wird."},{"name":"Vergleichs-Variable","beschreibung":"Im Modus „Variable vs. Variable\": zweite Quelle (ID oder =Formel), gegen die per Operator verglichen wird."},{"name":"Vergleichsliste","beschreibung":"Im Listen-Modus: je Zeile ein Wert-Muster (exakt, Operator wie >50/!=0, Bereich 25..60 oder Platzhalter */else) und eine Skin-Farbe. Trifft eine Zeile, ist der Alarm aktiv und die Karte wird in der Zeilenfarbe getoent."},{"name":"Farbe (Skin)","beschreibung":"Skin-Farbschluessel (crit/warn/info…), der Karte und Icon-Box toent (stateTint, passt sich Hell/Dunkel an). crit/fehler/error/alarm zaehlen als kritisch (Sortierung im Panel). Im Listen-Modus gewinnt die Farbe der getroffenen Zeile."},{"name":"Titel","beschreibung":"Fette Kopfzeile. Klartext oder =Formel mit #id + Text (z. B. =#33962.\" Sensor-Alarme\")."},{"name":"Unterzeile","beschreibung":"Gedaempfte Zeile darunter. Klartext oder =Formel; das Kuerzel {seit} wird durch „seit HH:MM\" (Zeitpunkt der letzten Aenderung der Bedingungs-Variable) ersetzt. Leer = ausgeblendet."},{"name":"Icon","beschreibung":"Icon in der getoenten Box (Vorgabe bell). Die Icon-Farbe folgt der Alarm-Farbe."},{"name":"Benachrichtigung","beschreibung":"Reines Textfeld (Klartext/=Formel), am Element als data-notify hinterlegt - KEIN Push aus dem Widget. Echter Push laeuft ueber einen separaten Symcon-Skript-Hook."}],"hinweis":"Standalone blendet sich die Karte bei nicht erfuellter Bedingung im Betrieb ganz aus (im Editor bleibt sie sichtbar). Als Kind eines Alarm-Panels wird sie zusaetzlich nur gezeigt, wenn sie aktiv und nicht quittiert ist. Das Widget hat keinen Hover.","groesse":[320,72],"demo":{"varId":900015,"condMode":"const","op":">","thr":0,"color":"crit","icon":"smoke","title":"=#900015.\" Sensor-Alarme\"","sub":"Rauchmelder Leonie, Z-Wave · {seit}"}},
    "alarmpanel": {"titel":"Alarm-Panel","zweck":"Container fuer Alarm-Karten: roter Eyebrow („BRAUCHT AUFMERKSAMKEIT\") plus „Alle quittieren\", darunter eine scrollbare Reihe der eingehaengten Alarm-Karten. Gezeigt werden nur AKTIVE, nicht quittierte Karten; ist keine aktiv, zeigt das Panel einen gruenen OK-Zustand (oder eine „Keine Alarme\"-Zeile) - es bleibt aber immer sichtbar.","funktionen":[{"name":"Alarm-Karten (Kinder)","beschreibung":"Ein Alarm-Widget in das Panel ziehen macht es zum Kind (w.kids). Jede Karte entscheidet selbst ueber ihre Bedingung; inaktive werden im Betrieb ausgeblendet. Das Panel legt sie als flex-wrap-Reihe (lokale x/y werden ignoriert), Kartenbreite = eigene Widget-Breite des Alarms."},{"name":"Eyebrow","beschreibung":"Kleiner Ueberschrifttext oben links (Vorgabe „BRAUCHT AUFMERKSAMKEIT\")."},{"name":"Eyebrow-Farbe","beschreibung":"Skin-Farbe des Eyebrow (Vorgabe crit = rot). Im OK-Zustand wird er automatisch gruen und zeigt den OK-Eyebrow."},{"name":"„Alle quittieren\"","beschreibung":"Schaltet den Knopf oben rechts ein/aus. Klick blendet alle aktuell aktiven Karten aus - client-seitig, an die Zustands-Signatur des Alarms gebunden; aendert sich der Zustand oder wird der Alarm zwischendurch inaktiv, taucht die Karte wieder auf. Nicht ueber einen Reload persistent (fail-safe)."},{"name":"Text","beschreibung":"Beschriftung des Quittier-Knopfs (Vorgabe „Alle quittieren\")."},{"name":"Quittier-Variable (optional)","beschreibung":"Beim Quittieren wird zusaetzlich diese Variable geschrieben."},{"name":"Quittier-Wert","beschreibung":"Wert, der beim Quittieren in die Quittier-Variable geschrieben wird (Vorgabe 0)."},{"name":"Kritische zuerst","beschreibung":"Sortiert die Reihe so, dass kritische (rote) Karten vor gelben/amber stehen."},{"name":"Abstand (px)","beschreibung":"Luecke zwischen den Karten in Pixel (Vorgabe 12)."},{"name":"Wenn leer","beschreibung":"„Grüner OK-Zustand\" (Vorgabe) faerbt das Panel gruen und zeigt OK-Text/OK-Eyebrow; „Keine Alarme-Zeile\" zeigt stattdessen eine dezente Hinweiszeile. Das Panel bleibt in beiden Faellen sichtbar."},{"name":"OK-Text / OK-Eyebrow","beschreibung":"Nur im OK-Modus: Text der gruenen Alles-in-Ordnung-Zeile und der zugehoerige Eyebrow („ALLES OK\")."},{"name":"Leer-Text","beschreibung":"Nur im „Keine Alarme\"-Modus: Text der dezenten Leerzeile."},{"name":"Scroll-Chevrons","beschreibung":"Passt die Karten-Reihe nicht in die Breite, erscheinen links/rechts Blaetter-Chevrons; Mausrad wird auf horizontales Scrollen umgelenkt."}],"hinweis":"Die Karten-Innenoptik (getoente Box, fetter Titel, crit=rot/warn=amber) liefert das Alarm-Widget; das Panel steuert Kopf, Reihe, Sortierung, Scroll und Quittung. Quittungen sind bewusst nicht ueber einen Reload persistent. Kein Hover.","groesse":[760,150],"demo":{"eyebrow":"BRAUCHT AUFMERKSAMKEIT","ackText":"Alle quittieren","kids":[{"type":"alarm","id":"adk1","x":0,"y":0,"w":320,"h":64,"varId":900015,"condMode":"const","op":">","thr":0,"color":"crit","icon":"smoke","title":"=#900015.\" Sensor-Alarme\"","sub":"Rauchmelder Leonie, Z-Wave · {seit}"},{"type":"alarm","id":"adk2","x":0,"y":0,"w":320,"h":64,"varId":900022,"condMode":"const","op":">","thr":0,"color":"warn","icon":"warning","title":"=#900022.\" % Luftfeuchte\"","sub":"Bad OG, Homematic · {seit}"}]}},
    "assoc": {"titel":"Zustand","zweck":"Zeigt den aktuellen Zustand einer Variablen als Kachel aus Icon-Chip, grossem Wert/Text, Statuspille und Label. Zustandstext, Icon und Farbe kommen aus einer eigenen Zuordnungsliste und/oder den Profil-Assoziationen der Variablen.","funktionen":[{"name":"Variable","beschreibung":"Quelle des Zustands. Beim Einbinden werden die Profil-Assoziationen geladen; die Kachel aktualisiert sich bei jedem neuen Wert."},{"name":"Darstellung","beschreibung":"Automatisch (crit fuellt) / Getoent / Vollflaeche. Legt fest, wie die Zustandsfarbe wirkt: getoenter Hintergrund mit farbiger linker Kante, komplette Farbflaeche mit weisser Schrift, oder automatisch (Farbwort crit fuellt, andere toenen, ohne Farbe neutrale Kachel)."},{"name":"Anzeige","beschreibung":"Icon + Wert + Label / Nur Icon / Wert + Label. „Nur Icon\" blendet das Label aus, „Wert + Label\" den Icon-Chip - die grosse Wertzeile bleibt in beiden Faellen."},{"name":"Zustand als","beschreibung":"Grosser Wert oder Pille. Bei „Pille\" wandert der Zustandstext in die kleine Pille oben rechts, die grosse Zeile bleibt leer - sinnvoll, wenn nur das Icon zaehlt."},{"name":"Einheit","beschreibung":"Wird nur bei numerisch formatierten Werten (z. B. Zaehlerstaenden) hinter die Zahl gehaengt; der Zustandstext rutscht dann in die Pille."},{"name":"Manuell: Wert · Icon · Text · Farbe","beschreibung":"Listeneditor mit beliebig vielen Zeilen. Wert erlaubt exakte Treffer (0, 1), Vergleiche (>0, >=1, <5, !=0), Bereiche (1..5) und Platzhalter (*/else). Exakte Treffer haben Vorrang. Icon = Icon-Kennung, Text ueberschreibt den Zustandstext (Pille), Farbe ist eine Skin-Farbe; crit = rote Vollflaeche, sonst getoent."},{"name":"Schrift Wert (Schrift / Gewicht / Groesse)","beschreibung":"Eigene Typografie nur fuer die grosse Wertzeile (Sans/Serif/Mono/…, Gewicht 300–800, Groesse in px), unabhaengig von der Widget-Schrift."},{"name":"Zahl-Format (Zaehler)","beschreibung":"Ist der Zustandswert numerisch, wirken die gemeinsamen Formatoptionen (Faktor/Skalierung, Tausendertrennung, grosse Zahlen kuerzen, Nachkommastellen) auf den grossen Wert; der Zustandstext wandert in die Pille."},{"name":"Assoziationen / Icon-Fallback","beschreibung":"Ohne passende manuelle Zeile greifen Name, Icon und Farbe des Variablenprofils; das Icon-Feld liefert den Fallback, wenn weder Liste noch Profil ein Icon bieten (adaptive Icons werden mit dem Wert gezeichnet)."},{"name":"Pille als Chevron","beschreibung":"Ist am Widget „Seite öffnen\"/„Popup öffnen\" gesetzt und keine Pille belegt, erscheint statt der Pille ein Pfeil (Chevron) als Navigationshinweis."}],"hinweis":"Zustandsfarbe und Hintergrund setzt das Widget selbst - eine getroffene Zuordnung ueberschreibt die gemeinsame Hintergrundfarbe. Farbe „crit\" erzeugt in der Vorgabe eine rote Vollflaeche; wer das nicht will, stellt Darstellung auf „Getönt\".","groesse":[180,150],"demo":{"label":"Alarmanlage","varId":22090,"assocShow":"both","stateAs":"value","amap":[{"v":"0","icon":"shieldcheck","text":"Unscharf","color":"ok"},{"v":"1","icon":"siren","text":"Scharf","color":"crit"}]}},
    "bar": {"titel":"Balken","zweck":"Horizontaler Fortschrittsbalken mit Beschriftung links und formatiertem Zahlenwert rechts. Die Fuellung errechnet sich aus dem Variablenwert im Bereich Min bis Max.","funktionen":[{"name":"Variable","beschreibung":"Messwert. Der formatierte Wert steht rechts oben, der Rohwert bestimmt die Balkenlaenge."},{"name":"Min / Max","beschreibung":"Bereichsgrenzen der Skala (Vorgabe 0 und 100). Werte ausserhalb werden auf 0 bzw. 100 Prozent begrenzt."},{"name":"Format / Nachkommastellen","beschreibung":"Gemeinsam: Anzeigeformat des Zahlenwerts (Original, kW, kWh, W, Prozent, Uhrzeit, Datum, Relativzeit) und Rundung; die Profileinheit wird angehaengt, sofern keine eigene Einheit gesetzt ist."},{"name":"Icon (Fallback) und Icon-Farbe","beschreibung":"Gemeinsam: Icon vor der Beschriftung; die Icon-Farbe wird als Skin-Farbe gewaehlt und ueber --wicon gesetzt."},{"name":"Assoziationen (Icons & Farben nutzen)","beschreibung":"Gemeinsam: mit gesetztem Haken faerben Profil-Assoziationen (oder je-Wert-Uebersteuerungen) Icon und Zahlenwert - die Balkenfuellung bleibt davon unberuehrt."},{"name":"Balkenfarbe","beschreibung":"Nicht einstellbar: fester Verlauf von --accent-2 nach --accent des aktiven Skins, beim Wertwechsel weich animiert; die Bahn folgt dem Skin (--surface-2 mit Rand)."},{"name":"Label","beschreibung":"Gemeinsam: Beschriftung links (Grossbuchstaben, gesperrt). \\n erzwingt Umbruch, „Beschriftung mehrzeilig\" verhindert das Abschneiden."}],"hinweis":"Ohne passende Min-/Max-Werte bleibt der Balken leer oder voll - bei Zaehlern oder Leistungswerten muss der Bereich von Hand gesetzt werden. Der Balken kennt keine Schwellenfarben; Assoziationen faerben nur Icon und Zahlenwert, nicht die Fuellung.","groesse":[260,90],"demo":{"label":"Zisterne","varId":41522,"min":0,"max":100,"dec":0,"icon":"cistern","iconColor":"info"}},
    "blank": {"titel":"Leer","zweck":"Platzhalter-Kachel ohne Funktion: markiert eine noch unbelegte Stelle im Layout und zeigt den Hinweis, dass Typ und Variable im Eigenschaften-Panel gewaehlt werden muessen.","funktionen":[{"name":"Typ","beschreibung":"Gemeinsam: ueber das Typ-Feld wird der Platzhalter in das gewuenschte Widget umgewandelt, ohne Position und Groesse zu verlieren."},{"name":"Label","beschreibung":"Gemeinsam: solange das Label leer oder „Label\" ist, zeigt die Kachel den Standardhinweis „Leer — Typ & Variable im Panel wählen\"; jeder andere Text ersetzt den Hinweis."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Karteneigenschaften; Icon und Text werden gedaempft gezeichnet (Text --faint, Icon --muted)."},{"name":"Interaktion","beschreibung":"Gemeinsam: auch ein leerer Platzhalter kann per Klick oder Lang-Druck eine Seite/ein Popup oeffnen oder ein Skript starten - brauchbar als unsichtbare Klickflaeche."},{"name":"Keine Live-Bindung","beschreibung":"Das Widget wertet keine Variable aus; ein eingetragenes Variablenfeld bleibt ohne Wirkung."}],"hinweis":"Reiner Platzhalter - vor der Inbetriebnahme einer Seite sollten keine „Leer\"-Kacheln uebrig bleiben, da sie im Run-Modus genauso sichtbar sind wie im Editor.","groesse":[200,130],"demo":{"label":"Label"}},
    "button": {"titel":"Button","zweck":"Quadratische Schaltflaeche mit Icon-Badge und Beschriftung. Ein Klick schaltet die gebundene Variable um, schreibt einen festen Wert oder loest die eingestellte Aktion aus (Seite, Popup, Skript, Region, Menue, Zurueck); Aussehen, Text und Icon lassen sich getrennt fuer Ein und Aus festlegen.","funktionen":[{"name":"Variable","beschreibung":"Schaltvariable. Ist keine andere Aktion und kein fester Klick-Wert gesetzt, schaltet ein Klick zwischen 1 und 0 um; der Zustand faerbt den Icon-Badge (Klasse 'on' = volle Akzentflaeche statt getoenter)."},{"name":"Bei Klick Wert","beschreibung":"Optionaler fester Wert, den ein Klick an die gebundene Variable schreibt (Kommando-/Aktions-Taster, z. B. Maeher Start=1, Park=2). Leer = Umschalten. Reine Zahlen werden numerisch geschrieben, sonst als Text."},{"name":"Seite oeffnen","beschreibung":"Statt zu schalten wird die gewaehlte Ansicht geoeffnet. Der Eintrag '- (Variable schalten)' laesst das Umschalten aktiv."},{"name":"Popup oeffnen","beschreibung":"Oeffnet die gewaehlte Ansicht als Popup-Overlay; hat Vorrang vor dem Schalten der Variablen."},{"name":"Lang-Druck -> Popup / Lang-Druck -> Seite","beschreibung":"Zweitfunktion bei etwa 550 ms Halten; ist beides gesetzt, gewinnt die Seite. Der anschliessende Klick wird unterdrueckt."},{"name":"Hover-Ansicht","beschreibung":"Zeigt beim Ueberfahren mit der Maus (Desktop) eine gewaehlte Ansicht als Flyout. Auf Touch oeffnet ein Tipp den Flyout nur, wenn keine andere Klick-Aktion gesetzt ist."},{"name":"Region setzen","beschreibung":"Tauscht den Inhalt eines benannten Regionsplatzes gegen die gewaehlte Ansicht - fuer Dashboards mit festem Rahmen und wechselndem Inhalt. Wirkt nur, wenn Regionsname und Ansicht gesetzt sind."},{"name":"Zurueck","beschreibung":"Klick blaettert in der Navigation eine Seite zurueck."},{"name":"Menue oeffnen","beschreibung":"Klick klappt die Seitenliste des Run-Modus auf oder zu."},{"name":"Popup schliessen","beschreibung":"Klick schliesst ein offenes Popup - der uebliche Schliessen-Knopf innerhalb einer Popup-Ansicht."},{"name":"Skript ID","beschreibung":"Startet bei Klick das angegebene IP-Symcon-Skript ueber die Modul-Schnittstelle."},{"name":"Alias: Vorlagen-ID -> echte Geraete-ID","beschreibung":"Nur bei gesetztem Popup sichtbar: Bildet die Platzhalter-IDs der Popup-Vorlage auf die echten Variablen des Geraets ab, sodass eine Vorlage fuer viele Geraete reicht."},{"name":"Zustand Ein/Aus: Text","beschreibung":"Ersetzt die Beschriftung je nach Zustand (z. B. 'Licht an' / 'Licht aus'); leer laesst das normale Label stehen."},{"name":"Zustand Ein/Aus: Hintergrund und Textfarbe","beschreibung":"Je Zustand eigene Kartenfarbe (wirkt auf die Button-Flaeche) und Farbe von Icon und Beschriftung."},{"name":"Zustand Ein/Aus: Icon (ID)","beschreibung":"Je Zustand ein eigenes Icon (z. B. lighton/lightoff); ohne Eintrag bleibt das Fallback-Icon."},{"name":"Zustands-Stil zuruecksetzen","beschreibung":"Loescht alle acht Zustandsfelder (Text, Hintergrund, Textfarbe, Icon je Ein/Aus) in einem Schritt."},{"name":"Icon (Fallback)","beschreibung":"Gemeinsam: Grundicon des Badges (Vorgabe 'power'), wird verwendet, solange kein Zustandsicon greift."},{"name":"Assoziationen (Icons & Farben nutzen)","beschreibung":"Gemeinsam: Mit gesetztem Haken koennen Icon und Farbe alternativ aus den Profil-Assoziationen der Variablen kommen."},{"name":"Reihenfolge der Klickaktionen","beschreibung":"Nicht sichtbar: Zuerst greift ein gesetzter fester Klick-Wert; sonst gilt Popup schliessen, Popup oeffnen, Skript, Menue, Region, Zurueck, Seite - erst wenn nichts davon gesetzt ist, wird die Variable umgeschaltet."},{"name":"Label / Farben / Rahmen / Typografie / Sichtbarkeit","beschreibung":"Gemeinsame Eigenschaften; der Button nutzt anstelle des allgemeinen Interaktionsblocks seine eigene, umfangreichere Aktionsliste."}],"hinweis":"Im Vorschau-/Run-Modus schaltet ein Klick wirklich das Geraet - die Demo veraendert die echte Variable. Ohne festen Klick-Wert schreibt das Umschalten fest 1/0; fuer einen anderen festen Wert dient 'Bei Klick Wert', fuer wechselnde Werte eignen sich Auswahl- oder Slider-Widgets.","groesse":[150,150],"demo":{"label":"Lesezimmer","varId":30519,"icon":"bulb","onIcon":"lighton","offIcon":"lightoff","onText":"Licht an","offText":"Licht aus"}},
    "calc": {"titel":"Berechnung","zweck":"Rechnet aus mehreren Variablen einen einzelnen Wert und zeigt ihn wie eine Wertkachel an. Moeglich sind Summe, Mittel, Minimum, Maximum, Differenz und das Zaehlen aktiver Quellen.","funktionen":[{"name":"Rechnung","beschreibung":"Summe, Mittel, Min, Max, 'Differenz (1 - Rest)' (erste Quelle minus Summe aller weiteren) oder 'Anzahl > 0' (zaehlt Quellen mit positivem Wert). Vorgabe ist Summe."},{"name":"Einheit","beschreibung":"Freitext, der hinter das Ergebnis gehaengt wird (z. B. kWh, W, Grad C)."},{"name":"Nachkommastellen","beschreibung":"Eigenes Feld des Widgets, 0 bis 4 Stellen, Vorgabe 1; bei 'Anzahl > 0' wird immer ganzzahlig ausgegeben. Der Punkt wird durch ein Komma ersetzt."},{"name":"Quellen: Variablen-ID","beschreibung":"Listeneditor mit beliebig vielen Variablen-IDs (Vorgabe: zwei leere Zeilen). Die Reihenfolge zaehlt bei 'Differenz'. Quellen ohne gueltigen Zahlenwert werden uebersprungen; ist keine gueltig, steht der Text bei leerem Wert (Vorgabe '-')."},{"name":"Wert & Format (gemeinsam)","beschreibung":"Zusaetzlich wirken Faktor/Skalierung (w.scale), Tausendertrennung, grosse Zahlen kuerzen (k/M/Mrd) und Text bei leerem Wert auf das Ergebnis."},{"name":"Live-Aktualisierung","beschreibung":"Nicht als Feld sichtbar: Jede Quell-ID wird in den Live-Index aufgenommen; sobald sich eine davon aendert, wird die Rechnung neu ausgefuehrt."},{"name":"Label","beschreibung":"Gemeinsam: Beschriftung ueber dem Wert (Vorgabe 'Summe'). \\n erzwingt einen Umbruch."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Karteneigenschaften fuer Text- und Hintergrundfarbe, Rahmen und Schrift."},{"name":"Interaktion / Sichtbarkeit / Animation","beschreibung":"Gemeinsam: Klick und Lang-Druck auf Seite oder Popup, Skript-ID, Sichtbarkeit ueber Steuervariable, Animation, Ebene, Geometrie."}],"hinweis":"Das allgemeine Feld 'Variable' wird von diesem Widget ignoriert - massgeblich ist ausschliesslich die Quellenliste. Gerechnet wird mit den momentanen Live-Werten, es gibt keinen Archiv-Zugriff und keine Historie.","groesse":[230,110],"demo":{"label":"Eigenverbrauch","mode":"diff","unit":"kWh","dec":0,"items":[{"vid":48275},{"vid":33962}]}},
    "calendar": {"titel":"Kalender","zweck":"Zeigt Termine aus einer oder mehreren iCal-Calendar-Reader-Instanzen - wahlweise als chronologische Agenda mit Tagesueberschriften oder als Monatsraster mit Punktmarkierung an Tagen mit Terminen.","funktionen":[{"name":"Kalender-IDs","beschreibung":"Kommagetrennte Liste von Instanz-IDs des iCal Calendar Readers (z. B. 33020,55959). Die Termine mehrerer Kalender werden zusammengefuehrt und nach Startzeit sortiert."},{"name":"Tage","beschreibung":"Vorschauzeitraum ab heute 0 Uhr, Vorgabe 14. Serverseitig auf 1 bis 60 Tage begrenzt, hoechstens 120 Termine."},{"name":"Ansicht","beschreibung":"Agenda: Zeilen mit Uhrzeit bzw. 'ganztaegig' und Titel, gruppiert unter 'Heute', 'Morgen' oder Wochentag mit Datum. Monat: Raster des laufenden Monats ab Montag, heutiger Tag hervorgehoben, Tage mit Terminen bekommen einen Punkt."},{"name":"Automatische Auffrischung","beschreibung":"Nicht einstellbar: Neben dem Aufbau der Seite werden die Termine alle 60 Sekunden neu vom Kalenderserver geholt."},{"name":"Leer- und Fehlertexte","beschreibung":"Nicht einstellbar: Ohne Kalender-IDs erscheint der Hinweis, die IDs im Panel einzutragen; scheitert der Abruf, steht 'Kalender nicht erreichbar'; liefert der Zeitraum nichts, steht 'Keine Termine im Zeitraum'."},{"name":"Keine Variablenbindung","beschreibung":"Das Widget hat kein Variablenfeld; die Daten kommen ueber die Modul-Schnittstelle direkt vom Kalender-Server."},{"name":"Label / Farben / Rahmen / Typografie","beschreibung":"Gemeinsame Karteneigenschaften. Das Label wird nicht in die Kachel gezeichnet, Schriftwahl und Farben wirken auf die Terminliste."},{"name":"Interaktion / Sichtbarkeit / Animation","beschreibung":"Gemeinsam: Klick und Lang-Druck oeffnen Seite oder Popup (z. B. eine grosse Kalenderansicht), Skript-ID, Sichtbarkeit ueber Steuervariable, Animation, Ebene, Geometrie."}],"hinweis":"Braucht mindestens eine Instanz des Moduls 'iCal Calendar Reader' mit hinterlegter Kalender-URL - andere Instanztypen werden ignoriert. Jeder Abruf holt die ICS-Datei neu vom Server, in der Monatsansicht wird nur der laufende Kalendermonat gezeigt, unabhaengig vom eingestellten Zeitraum.","groesse":[300,240],"demo":{"label":"Termine","calIds":"33020,55959","days":14,"calview":"agenda"}},
    "camera": {"titel":"Kamera","zweck":"Zeigt ein Kamerabild formatfuellend im Widget - wahlweise als zyklisch nachgeladenes Media-Objekt aus Symcon, als MJPEG-Endlosstream direkt von der Kamera oder als RTSP-Stream ueber ein go2rtc-Gateway. Der Label-Text wird unten links ins Bild eingeblendet.","funktionen":[{"name":"Quelle","beschreibung":"Media-Objekt (Einzelbild), MJPEG-Stream (URL) oder RTSP ueber go2rtc. Die Auswahl blendet die jeweils passenden Felder ein."},{"name":"Aktualisierung (s)","beschreibung":"Nur bei Media-Objekt: Intervall, in dem das Bild neu geladen wird (Vorgabe 15 s). Ein zentraler Sekundentakt prueft den Ablauf und haengt einen Zeitstempel an die URL gegen Browser-Cache."},{"name":"MJPEG-URL","beschreibung":"Nur bei MJPEG: vollstaendige Stream-Adresse der Kamera. Der Browser holt den Stream direkt, die Symcon-VM ist nicht beteiligt. Fuer mehrere Kacheln den kleinen Substream (640) verwenden."},{"name":"go2rtc-Adresse","beschreibung":"Nur bei go2rtc: Basis-URL des Gateways, z. B. http://10.10.20.250:1984. Endende Schraegstriche werden entfernt."},{"name":"Stream-Name","beschreibung":"Nur bei go2rtc: Name des Streams genau so, wie er in go2rtc.yaml steht."},{"name":"Verfahren","beschreibung":"Nur bei go2rtc: WebRTC (geringste Verzoegerung), MSE (kompatibler) oder MJPEG (am genuegsamsten im Browser). Bestimmt den mode-Parameter der eingebetteten go2rtc-Player-Seite (stream.html)."},{"name":"Bild","beschreibung":"Ganzes Bild (contain), Fuellen/beschnitten (cover) oder An Bild anpassen: dabei setzt der Editor die Widget-Hoehe automatisch aus dem Seitenverhaeltnis des geladenen Bilds. Die Auswahl wirkt nur auf das <img>, im go2rtc-Modus (iframe) hat sie keine Wirkung."},{"name":"Media-ID","beschreibung":"Zentrales Feld: bei diesem Widget steht anstelle des Variablenfelds die ID des Symcon-Media-Objekts. Es wird ueber ?api=media&id=... geladen."},{"name":"Label","beschreibung":"Wird als weisse Beschriftung mit Schatten unten links ueber dem Bild angezeigt. Ein \\n im Text erzwingt einen Zeilenumbruch."},{"name":"Farben / Rahmen / Hintergrund","beschreibung":"Text- und Hintergrundfarbe, Rahmen (Ansicht-Standard/An/Aus) und deckender oder transparenter Hintergrund."},{"name":"Typografie","beschreibung":"Schriftart, Gewicht, Stil und Schriftgroesse fuer die eingeblendete Beschriftung."},{"name":"Interaktion","beschreibung":"Seite oeffnen, Lang-Druck -> Seite, Popup oeffnen, Lang-Druck -> Popup, Popup schliessen sowie Skript-ID bei Klick. Lang-Druck loest nach etwa 550 ms aus und unterdrueckt den folgenden Klick."},{"name":"Sichtbarkeit","beschreibung":"Zur Laufzeit ein-/ausblenden sowie Steuer-Variable mit Bedingung (wahr/ungleich 0, =, ungleich, groesser-gleich, kleiner-gleich Wert)."},{"name":"Animation / Ebene / Geometrie","beschreibung":"Einblend-Animation (Fade, Scale, SlideUp), Z-Reihenfolge (nach vorn/hinten) und X/Y/Breite/Hoehe."},{"name":"Live-Verhalten","beschreibung":"Beim Media-Modus laedt zusaetzlich jeder Medien-Push aus Symcon (WebSocket, MM_UPDATE) das Bild sofort neu. MJPEG und go2rtc versorgen sich selbst und werden bewusst nicht neu angestossen, weil ein erneutes Setzen der Quelle den laufenden Stream abreissen wuerde."}],"hinweis":"Der Media-Modus braucht ein Media-Objekt in Symcon (ID unter 'Media-ID'), nicht eine Variable. go2rtc wird als iframe eingebettet und setzt ein erreichbares Gateway voraus; ohne Adresse und Stream-Name zeigt das Widget nur einen Hinweistext. Der Modus 'An Bild anpassen' veraendert die Widget-Hoehe nur im Editor - zur Laufzeit bestimmt SmartFit die Groesse.","groesse":[340,220],"demo":{"label":"Hofkamera","camSrc":"media","mediaId":53669,"refresh":15,"camFit":"cover","frame":false}},
    "camarray": {"titel":"Kamera-Array","zweck":"Fasst mehrere Kameras in einer Kachel zusammen und schaltet per Pill-Leiste zwischen ihnen um. Die aktive Kamera sitzt als gefuellte Pill (Kamera-Icon + Name + Statuspunkt) links, die uebrigen ringfoermig ab der rechten oberen Ecke. Es wird immer nur die aktive Quelle geladen - das schont VM und Browser.","funktionen":[{"name":"Kameras (Liste)","beschreibung":"Je Eintrag: Bezeichnung (Pill-Text), Typ (Media / MJPEG / RTSP) und Quelle. Reihenfolge per Pfeil, Hinzufuegen/Loeschen wie ueblich. Die Quelle bedeutet je nach Typ: Media-ID, MJPEG-URL oder go2rtc-Stream-Name."},{"name":"Aktualisierung (s)","beschreibung":"Nur fuer Media-Elemente: Nachlade-Intervall der aktiven Kamera (Vorgabe 15 s), zentral im Sekundentakt mit Cache-Buster."},{"name":"go2rtc-Adresse","beschreibung":"Global fuer alle RTSP-Elemente: Basis-URL des go2rtc-Gateways (z. B. http://10.10.20.250:1984). Endende Schraegstriche werden entfernt."},{"name":"go2rtc-Verfahren","beschreibung":"Global: Wiedergabeverfahren fuer alle RTSP-Elemente - WebRTC (geringste Verzoegerung), MSE (kompatibler) oder MJPEG (genuegsam). Der Stream-Name steht je Kamera in der Quelle."},{"name":"Bild (Fit)","beschreibung":"Ganzes Bild / Fuellen (beschnitten) / An Bild anpassen - gilt global fuer alle Kameras des Arrays."},{"name":"Pills: Aktiv-Hintergrund","beschreibung":"Skin-Farbe der gefuellten aktiven Pill (leer = Akzent). Aktive Pill traegt Kamera-Icon und weisse Schrift."},{"name":"Pills: Inaktiv-Hintergrund","beschreibung":"Skin-Farbe der uebrigen Auswahl-Pills."},{"name":"Pills: Textfarbe inaktiv","beschreibung":"Skin-Textfarbe der inaktiven Pills."},{"name":"Pills: Statuspunkt","beschreibung":"Skin-Farbe des Punktes an der aktiven Pill (leer = gruen)."},{"name":"Pills: Schriftgroesse / Fett","beschreibung":"Schriftgroesse der Pill-Beschriftung (8-24 px, Vorgabe 12) und Fett-Schalter (Vorgabe an)."},{"name":"Pill-Anordnung","beschreibung":"Nicht einstellbar: Auswahl-Pills werden ab der rechten oberen Ecke im Uhrzeigersinn ringfoermig verteilt (obere Reihe rechtsbuendig, dann rechte Kante runter, unten rechts->links, links hoch). Ein ResizeObserver ordnet bei Groessenaenderung neu."},{"name":"Umschalten","beschreibung":"Klick auf eine Pill macht diese Kamera aktiv (rueckt nach links); die zuvor aktive wandert in den Ring. Nur die angezeigte Kamera wird geladen."}],"hinweis":"Media-Elemente brauchen ein Media-Objekt (ID), keine Variable. MJPEG und go2rtc versorgen sich selbst und werden beim Umschalten neu aufgebaut. Fuer viele Kacheln pro Seite den kleinen Substream verwenden.","groesse":[360,220],"demo":{"cams":[{"label":"Terrasse","type":"media","src":"53669"},{"label":"Eingang","type":"media","src":"53669"},{"label":"Garten","type":"media","src":"53669"}],"camFit":"cover","frame":false}},
    "campro": {"titel":"Kamera+","zweck":"Kamerabild aus einem Media-Objekt mit zusaetzlicher Bewegungsanzeige: eine bool-Variable schaltet oben links ein rotes 'Bewegung'-Abzeichen ein. Klick im Betrieb oeffnet das Vollbild in einem neuen Browser-Tab.","funktionen":[{"name":"Bild","beschreibung":"Ganzes Bild (contain), Fuellen/beschnitten (cover) oder An Bild anpassen (Hoehe folgt dem Seitenverhaeltnis des Bilds, im Editor)."},{"name":"Media-ID","beschreibung":"ID des Symcon-Media-Objekts, aus dem das Standbild geladen wird. Steht im Widget-Eigenschaftenblock, nicht im zentralen Feld."},{"name":"Aktualisierung (s)","beschreibung":"Intervall fuer das Nachladen des Bilds, Vorgabe 15 s. Ein zentraler Sekundentakt stoesst das Neuladen mit Cache-Buster an."},{"name":"Variable","beschreibung":"Zentrales Feld: bool-Variable des Bewegungsmelders. Ist sie wahr, erscheint oben links das rote Abzeichen 'Bewegung'; sonst bleibt es ausgeblendet."},{"name":"Label","beschreibung":"Kameraname, wird unten links ins Bild eingeblendet. \\n erzwingt einen Zeilenumbruch."},{"name":"Klick (Vorschau/Betrieb)","beschreibung":"Oeffnet ?api=media&id=... in einem neuen Tab - also das Bild in voller Aufloesung. Sind Popup schliessen, Popup oeffnen, Skript-ID, Menue, Region oder Seitenwechsel gesetzt, werden diese zuerst ausgewertet und haben Vorrang."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Wie bei allen Widgets: Text- und Hintergrundfarbe, Rahmen, transparenter Hintergrund, Schriftart/Gewicht/Stil/Groesse der Beschriftung."},{"name":"Interaktion","beschreibung":"Seite oeffnen, Lang-Druck -> Seite, Popup oeffnen, Lang-Druck -> Popup, Popup schliessen, Skript-ID."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Anzeige zur Laufzeit, Steuer-Variable mit Vergleichsbedingung, Einblend-Animation, Z-Reihenfolge, Geometrie."}],"hinweis":"Kann im Gegensatz zu 'Kamera' nur Media-Objekte anzeigen - kein MJPEG und kein go2rtc. Die Media-ID steht hier im Widget-Eigenschaftenblock, das zentrale Variablenfeld ist fuer den Bewegungsmelder reserviert. Das Vollbild im neuen Tab funktioniert nur im Vorschau-/Run-Modus, nicht im Editor. Das Bewegungs-Abzeichen wird nur auf der Seite aktualisiert, nicht in einem Popup.","groesse":[340,230],"demo":{"label":"Einfahrt","mediaId":53669,"refresh":10,"camFit":"cover","varId":22090,"frame":false}},
    "chart": {"titel":"Chart","zweck":"Sammel-Widget fuer alle Diagramme (ECharts). Ueber den Chart-Typ werden Zeitreihen aus dem Archiv (Flaeche, Linie, Spline, Stufen, Balken, gestapelte Balken, Punkte), die kompakte Sparkline, ein animierter Bar Race (Balken-Wettlauf), Anteilsdiagramme aus Live-Werten (Kreis, Donut, Rose), ein Wasserfall, eine Heatmap (Wochentag x Zeit) sowie die Tageslaengenkurve eines ganzen Jahres gezeichnet. Beliebig viele Serien, zwei Achsenseiten, Marken, Vergleich mit Zeitversatz und Perioden-Navigation.","funktionen":[{"name":"Chart-Typ","beschreibung":"18 Varianten in Gruppen: Zeitreihe (Flaeche, Flaeche glatt, Linie, Linie glatt, Stufen, Stufenflaeche, Balken, Balken gestapelt, Punkte), Animiert (Bar Race), Kompakt (Sparkline), Anteile ohne Zeit (Kreis, Donut, Rose), Ohne Zeit (Wasserfall), Matrix (Heatmap Wochentag x Zeit), Astronomie (Tageslaenge). Der Typ entscheidet ueber _chartVis(), welche Optionen unten erscheinen. Beim Umschalten wird die typische Groesse des neuen Typs uebernommen (Sparkline 150x50, Wasserfall 360x220, Heatmap 380x240, Bar Race 380x280, Tageslaenge 420x190, Anteile 260x220, sonst 340x190), solange die Kachelgroesse noch der Standardgroesse des alten Typs entsprach."},{"name":"Bar Race (Balken-Wettlauf)","beschreibung":"Animierter Wettlauf, jede Serie ist ein Laeufer. Datenquelle waehlbar: 'Verlauf' spielt Frames aus dem Zeitraum ab (Bucket = Einheit) und laeuft automatisch; 'Live-Werte' zeigt die aktuellen Werte und sortiert bei jedem Update in Echtzeit um. Optionen: Sichtbare Raenge Top N (3-30, Vorgabe 10), Tempo je Frame bzw. Uebergang in ms; nur im Verlaufs-Modus zusaetzlich 'Kumuliert' (Running Total) und 'Endlos-Schleife'. Feste Kategorie-/Wert-Achsen, sortiert selbst (keine Legende, eigene Wertlabels)."},{"name":"Heatmap (Wochentag x Zeit)","beschreibung":"Aggregiert die Archiv-Historie der ERSTEN Serie zu einem Raster Wochentag (Zeilen, Mo oben) x Tageszeit (Spalten); die Zellfarbe zeigt den Wert. Optionen: Zeitraum in Tagen (1-120, Vorgabe 14), Aufloesung je Spalte (Stunde=24 / 30 min=48 / 15 min=96 / 5 min=288; fein nutzt das 5-Minuten-Archiv), Aggregation Mittelwert oder Summe, Farbschema (Heat blau->rot, Kuehl->Warm, Akzent) und optional Zahlenwerte in den Zellen. Braucht geloggte Werte."},{"name":"Serien (Variable . Name . Farbe . Typ . Achse)","beschreibung":"Liste beliebig vieler Datenreihen (w.series): Variablen-ID (Knopf 'Var' bindet per Klick im Baum), Anzeigename fuer Legende/Tooltip, Skin-Farbe (Auto, Neutral, Gedaempft, Blass, Akzent, Akzent 2, OK, Warnung, Kritisch, Info, Warm; eigene Farbe bleibt als 'Eigene'), eigener Darstellungstyp (ueberschreibt den Chart-Typ -> Mischdiagramme Balken + Linie) und die Y-Achse. Sparkline und Heatmap nutzen nur die erste Zeile (ohne Typ/Achse); Torte/Donut/Rose blenden Typ und Achse aus - dort wird der Editor nicht ausgewertet (siehe Hinweis). Wasserfall und Tageslaenge haben keinen Serien-Editor."},{"name":"Y-Achsen (Seite . Name . Min/Max . Format)","beschreibung":"Eigener Editor fuer mehrere Y-Achsen (w.yAxes): Seite links/rechts, Name/Einheit als Ueberschrift, feste Min-/Max-Grenzen (leer = automatisch) sowie Zahlenformat und Nachkommastellen je Achse. Achseneinstellung schlaegt die Widget-Einstellung. Mehrere Achsen derselben Seite werden je 48 px versetzt; Y-Hilfslinien zeichnet nur die erste Achse. Die letzte Achse ist nicht loeschbar. Nicht bei Anteilen, Sparkline, Wasserfall, Tageslaenge, Heatmap und Bar Race."},{"name":"Zeitraum (Anzahl + Einheit)","beschreibung":"Zentrale Zeitsteuerung fuer Zeitreihen, Sparkline und (im Verlaufs-Modus) Bar Race und Heatmap: Anzahl mal Einheit (Roh, Minuten, Stunden, Tage, Wochen, Monate, Jahre). Die Einheit ist zugleich die Archiv-Aggregationsstufe; 'Roh' liest unaggregierte Werte. Bei Anteilen, Wasserfall und Tageslaenge erscheint die Zeile nicht."},{"name":"Fenster-Einheit","beschreibung":"Nur bei 'Roh': legt fest, ob die Anzahl Stunden oder Tage bedeutet (range.rawUnit)."},{"name":"Wert (Mittel/Summe)","beschreibung":"Welcher Kennwert je Aggregationsbucket gezeichnet wird (range.aggF). Bei Zaehlervariablen entspricht 'Mittel' dem Verbrauch je Bucket. Erscheint bei jeder Einheit ausser 'Roh'."},{"name":"Zeitmodus (Rollierend / Kalenderjahr)","beschreibung":"Nur bei Einheit 'Monate': statt eines rollierenden Fensters die Monate Jaen-Dez des laufenden Jahres als Balken; mit aktivem Vergleich kommt das Vorjahr abgeschattet dazu. Der Schalter setzt range.cal - der Zeichner schaltet aber noch ueber die Altfelder calYear/agg um (siehe Hinweis)."},{"name":"Nachkommastellen","beschreibung":"Gemeinsame Nachkommastellen (w.dec) fuer Datenlabels und Tooltips (leer = automatisch nach Groessenordnung). Dezimaltrennzeichen ist immer das Komma."},{"name":"Einheit (Werte)","beschreibung":"Einheitentext (w.chUnit), der an Datenlabels und Tooltip-Werte gehaengt wird (z. B. kWh). Beim Wasserfall faellt er auf dessen eigene Y-Einheit zurueck."},{"name":"Glaetten (Spline)","beschreibung":"Nur bei Linien-/Flaechentypen: rundet den Kurvenverlauf (Standard an). Ein Serientyp 'glatt'/'Stufen' ueberschreibt die Einstellung fuer diese Serie."},{"name":"Punkte / Punkte-Groesse","beschreibung":"Blendet Datenpunkte auf der Linie ein und legt ihre Groesse fest (Standard 5); beim Typ 'Punkte' (Scatter) gibt es nur die Groesse (Standard 7)."},{"name":"Linienbreite","beschreibung":"Strichstaerke der Linien in px (Standard 2), nur bei Linien-/Flaechentypen. Die Tageslaengenkurve verwendet denselben Wert ohne eigenes Feld. Fuer die Sparkline gilt er nicht (fest 1,8)."},{"name":"Flaechen-Verlauf","beschreibung":"Fuellt Flaechendiagramme mit einem Farbverlauf statt einer flachen Transparenz."},{"name":"Balken-Rundung","beschreibung":"Eckenradius der Balken (Balken, gestapelte Balken, Wasserfall, Bar Race), Standard 3. Bei Stapelung wird der Radius auf 0 gezwungen."},{"name":"Balken horizontal","beschreibung":"Umschalter fuer alle Balken-Typen (ausser Bar Race): liegende Balken statt senkrechter Saeulen. Achsen werden getauscht (Wert nach rechts, Zeit/Kategorie nach unten); Zeitreihen laufen dann von oben nach unten."},{"name":"Stapeln","beschreibung":"Addiert die Serien aufeinander (bei 'Balken gestapelt' immer aktiv). In gemischten Diagrammen werden bewusst nur die Balken gestapelt, Linien und Punkte bleiben unberuehrt. Der Schalter erscheint nur bei Balken- und Linien-/Flaechentypen."},{"name":"Legende / Legende-Pos","beschreibung":"Legende ein-/ausblenden, Position oben/unten/links/rechts. Der Platz am jeweiligen Rand wird reserviert. Nicht bei Wasserfall, Sparkline, Heatmap und Bar Race. Bei der Tageslaenge listet die Legende auch die beiden Hilfsserien mit auf."},{"name":"Datenlabels","beschreibung":"Schreibt den Wert an jeden Datenpunkt bzw. Balken (mit Einheit und Nachkommastellen). Der Wasserfall bringt eine eigene Datenlabel-Option mit (standardmaessig an); bei Sparkline, Tageslaenge, Heatmap und Bar Race gibt es sie nicht bzw. eigene Wertlabels."},{"name":"Titel anzeigen / Titel-Position","beschreibung":"Zeigt das Label als Diagrammtitel, Position links/zentriert/rechts. Ohne ausdrueckliche Einstellung erscheint der Titel automatisch, wenn ein Label gesetzt und die Legende aus ist. Leeres Label = kein Titel. Bei allen Typen ausser der Sparkline verfuegbar."},{"name":"Schriftgroessen (px)","beschreibung":"Getrennt einstellbar fuer Titel (fsTitle), Legende (fsLegend), Achsen-Skalenwerte (axFs), Achsentitel (fsAxName) und Datenlabels (fsLabel). Leer = automatisch: die Schrift waechst mit der Kachelgroesse und folgt der zentralen Schriftgroesse aus 'Typografie'."},{"name":"Achsen & Raster","beschreibung":"Einzelne Schalter fuer Y-Beschriftung (Standard an), X-Beschriftung (Standard an), Y-Hilfslinien (Standard an), X-Hilfslinien, Achslinien und Tickmarks. Nicht bei Anteilsdiagrammen, Sparkline, Heatmap; bei Bar Race feste Achsen."},{"name":"Raster-Teilung","beschreibung":"Zielanzahl der Y- bzw. Werte-Rasterlinien (leer = automatisch)."},{"name":"X: Dichte","beschreibung":"Wie viele Zeitbeschriftungen erscheinen: automatisch, feste Anzahl oder jede N-te. Auf der Zeitachse wirkt nur 'Anzahl'; 'jede N-te' greift nur auf einer Kategorieachse (Kalenderjahr-Balken). Ueberlappende Beschriftungen laesst ECharts in jedem Fall weg."},{"name":"X: Zeitformat","beschreibung":"Zeitmuster in PHP-Schreibweise fuer die X-Achse, z. B. H:i, d.m., D H:i; ein Backslash schuetzt ein Zeichen. Sinnvoll nur auf der Zeitachse."},{"name":"Y: Zahlenformat + Dezimalstellen","beschreibung":"Skalenwerte automatisch, mit Tausenderpunkt (1.234,5) oder kompakt (1,2k / 3,4M); daneben die Nachkommastellen der Achse."},{"name":"Y: Einheit anzeigen","beschreibung":"Haengt die Einheit an die Skalenwerte; im Kompaktformat verschmilzt der Vorsatz mit der Einheit. Bezieht sich auf die alte Widget-Einheit w.yunit, die kein Feld mehr setzt."},{"name":"Zoom/Scroll","beschreibung":"Aktiviert Mausrad-/Touch-Zoom im Diagramm plus einen Scroll-Balken unter der X-Achse (nur bei Zeitreihen)."},{"name":"Marken (Art . Reihe . Text . Stil . Farbe . Einheit . Schwelle)","beschreibung":"Beliebig viele Annotationen (w.anns): Maximum, Minimum, Aktuell, Erster, Mittel oder feste Schwelle. Je Marke Reihen-Nummer (1-basiert), Text mit Platzhaltern {v}/{u}/{n}, Darstellung (Marke, Linie, beides), Farbe, Einheit und bei 'Schwelle' der Y-Wert. Mittel und Schwelle sind waagrechte gestrichelte Linien. Wirken auf Zeitreihen und Kalenderjahr-Balken."},{"name":"Marken-Textfarbe","beschreibung":"Schriftfarbe im Markenschild (leer = weiss); der Hintergrund des Schilds ist die Farbe der Marke."},{"name":"Perioden-Navigation","beschreibung":"Blendet unten links die Knoepfe (Pfeile) mit Label ein: Sprung um je ein ganzes Fenster zurueck und wieder auf 'jetzt'; die Historie wird fuer den verschobenen Zeitraum neu geladen. Nur bei Zeitreihen-Typen (nicht bei Anteilen, Sparkline, Wasserfall, Tageslaenge, Bar Race); Klicks werden bei Sparkline, Wasserfall und Bar Race hart abgewiesen."},{"name":"Vergleich (Zeitversatz)","beschreibung":"Zeichnet dieselben Serien zusaetzlich um einen waehlbaren Versatz (letzte Stunde, gestern, letzte Woche, letzter Monat, letztes Jahr) verschoben darueber. Standard: abgedunkelt und gestrichelt, 'Schatten %' steuert die Abdunklung (Vorgabe 55). Nur bei Zeitreihen; im Kalenderjahr-Modus bringt derselbe Schalter das Vorjahr als zweite Balkenreihe."},{"name":"Vergleich: Vorperiode als Strich","beschreibung":"Nur bei Balken-Typen mit aktivem Vergleich: zeigt die Vorperiode als duenne Marke/Strich statt als abgeschatteten Balken (w.cmpMark). Dann kein Schatten-Prozent, sondern eine waehlbare Strichfarbe (leer = grau)."},{"name":"Sparkline: Linienfarbe / Fuellung","beschreibung":"Nur beim Typ Sparkline: Skin-Farbe der Linie aus fester Liste (accent, ok, warn, crit, info) und Flaeche unter der Linie an/aus (Standard an). Achsen, Titel und Legende entfallen; gezeichnet wird nur die erste Serie mit fest verdrahtetem Stil (Breite 1,8, glatt, ohne Punkte, Kreis am letzten Wert)."},{"name":"Wasserfall: Schritte (Titel . Variable . Typ . Farbe)","beschreibung":"Liste der Balken (w.steps) mit Typ Start, Auf (+), Ab (-), Zwischensumme oder Summe. Auf/Ab nehmen den Betrag des Live-Werts und verschieben den laufenden Saldo, Zwischensumme und Summe zeichnen den bisherigen Saldo von 0 aus und brauchen keine Variable. Beim ersten Umschalten werden vier Musterschritte angelegt; eine geleerte Liste bleibt leer."},{"name":"Wasserfall: Y-Einheit, Verbindungslinien, Fallback Auf/Ab","beschreibung":"Eigene Einheit an der Y-Achse (w.wfUnit, unabhaengig vom Achsensystem; Altwidgets fallen einmalig auf yunit zurueck), gestrichelte Verbindungslinien auf Saldohoehe (Standard an) und die Skin-Farben ohne eigene Farbe (Standard OK bzw. Kritisch, Start = Info, Summen = Akzent)."},{"name":"Tageslaenge: Jahr, Standort-Instanz, Heute markieren, Ohne Sommerzeit","beschreibung":"Zeichnet Auf- und Untergang fuer jeden Tag des Jahres (Serverabruf ?api=daylight ueber date_sun_info), die Flaeche dazwischen ist die Tageslaenge. Standort automatisch aus der Location-Instanz, per ID erzwingbar. 'Heute markieren' (Standard an) setzt eine senkrechte Linie mit Datumsschild, 'Ohne Sommerzeit' rechnet in fester Normalzeit ohne die Spruenge im Maerz/Oktober."},{"name":"Tageslaenge: Untergang-Linie, Aufgang-Linie, Fuellung, Deckkraft","beschreibung":"Skin-Farben der beiden Kurven (Standard Warnung bzw. Gedaempft), Farbe der Flaeche dazwischen (leer = wie Untergang) und deren Deckkraft in Prozent (Standard 22). Die Y-Achse ist fest 0 bis 24 Uhr im 6-Stunden-Raster."},{"name":"Tooltip und Hover","beschreibung":"Zeigt beim Ueberfahren die Werte aller Serien am Zeitpunkt. Das Widget selbst bekommt bewusst keinen Hover-Effekt (noHover), damit die Perioden-Knoepfe nicht wie eine Verknuepfung wirken; ein Hover erscheint nur bei verknuepfter Seite/Popup."},{"name":"Live-Aktualisierung","beschreibung":"Ein neuer Wert per WebSocket laedt die Historie entprellt nach etwa 0,9 s nach. Torte/Donut/Rose und Wasserfall rechnen direkt aus den Live-Werten; Bar Race im Live-Modus sortiert die Balken in Echtzeit um. Diagramm-Animationen sind global abschaltbar (Einstellungen -> 'Chart-Animationen')."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Label (als Titel verwendbar, \\n erzwingt Umbruch), interner Name, Textfarbe/Hintergrund, Rahmen, transparenter Hintergrund, Typografie (skaliert alle Diagrammschriften mit; lokal ausgelieferte OFL-Fonts, kein CDN), Responsiv/SmartFit, Interaktion (Seite/Popup oeffnen, Lang-Druck, Hover-Ansicht, Popup schliessen, Skript-ID, bei gesetztem Popup die Alias-Liste), Sichtbarkeit mit Steuervariable, Einblend-Animation, Ebene, Position/Groesse. Ein Feld 'Variable' gibt es beim Chart nicht - Datenquellen sind Serien-, Schritt- bzw. Standortangabe."}],"hinweis":"Zeitreihen, Sparkline, Heatmap, Bar-Race-Verlauf und Kalenderjahr-Balken lesen ausschliesslich das Archiv - nicht geloggte Variablen bleiben leer. Torte, Donut und Rose werten den Serien-Editor beim Zeichnen NICHT aus: setPie liest fest die Live-Werte von varId/varId2/varId3 (plus Namen/Farben aus dem Altfeld sopt), und ein Feld dafuer gibt es beim Chart nicht mehr - neu angelegte Anteilsdiagramme bleiben deshalb leer. Der Kalenderjahr-Modus zeichnet nur die primaere Variable (varId) und greift im Renderer noch ueber die Altfelder calYear/agg. Der Wasserfall braucht keine Historie, aber laufend gepollte Live-Werte; die Tageslaengenkurve braucht eine Location-Instanz.","groesse":[470,270],"demo":{"ctype":"area","label":"Außentemperatur & Netzbezug (24 h)","varId":26109,"varId2":33962,"series":[{"vid":26109,"name":"Außentemperatur","color":"accent","type":"areaspline","axis":0},{"vid":33962,"name":"Netzbezug","color":"warm","type":"bar","axis":1}],"yAxes":[{"side":"L","name":"°C","min":"","max":""},{"side":"R","name":"kWh","min":"","max":""}],"range":{"n":24,"unit":"hour","aggF":"avg","rawUnit":"hour"},"legend":true,"legPos":"top","showTitle":false,"smooth":true,"lw":2,"grad":true,"symbols":false,"barRadius":3,"ygrid":true,"xgrid":false,"yLabels":true,"xLabels":true,"labels":false,"dec":1,"chUnit":"","xFmt":"H:i","anns":[{"kind":"max","ser":1,"style":"both","color":"crit","unit":"°C","text":"Max {v} {u}"}],"pnav":true,"zoom":false}},
    "checkbox": {"titel":"Checkbox","zweck":"Zeigt eine bool-Variable als angekreuztes Kaestchen mit Beschriftung und schaltet sie bei Klick um. Auf Wunsch reine Anzeige ohne Schaltfunktion.","funktionen":[{"name":"Nur Anzeige","beschreibung":"Schaltet das Widget schreibgeschuetzt (Eigenschaft readonly): Klicks werden ignoriert, der Zustand wird nur dargestellt."},{"name":"Variable","beschreibung":"Zentrales Feld: die bool-Variable (oder 0/1-Variable), deren Zustand angezeigt und geschaltet wird."},{"name":"Label","beschreibung":"Text rechts neben dem Kaestchen; er wird bei zu geringer Breite immer mit Auslassungspunkten abgeschnitten. Ein \\n erzwingt einen Zeilenumbruch."},{"name":"Klick","beschreibung":"Im Vorschau-/Run-Modus wird der zuletzt empfangene Wert invertiert und per setVar zurueckgeschrieben (0 <-> 1). Ohne Variable oder bei 'Nur Anzeige' passiert nichts."},{"name":"Zustandsfaerbung","beschreibung":"Bei wahr wird das Kaestchen mit der Akzentfarbe gefuellt und zeigt ein Haekchen; bei falsch bleibt es leer mit Linienrahmen. Die Aktualisierung erfolgt live ueber den Wert-Push."},{"name":"Farben / Rahmen / Hintergrund","beschreibung":"Text- und Hintergrundfarbe, Rahmen (Standard/An/Aus), deckender oder transparenter Hintergrund."},{"name":"Typografie","beschreibung":"Schriftart, Gewicht, Stil und Schriftgroesse der Beschriftung."},{"name":"Interaktion","beschreibung":"Zusaetzlich moeglich: Seite oeffnen, Popup oeffnen, Lang-Druck auf Seite oder Popup, Popup schliessen, Skript-ID. Der Widget-Klick wird zuerst ausgewertet und hat Vorrang, sobald eine Variable gesetzt und 'Nur Anzeige' aus ist - dann kommen Popup/Seitenwechsel/Skript nicht mehr zum Zug. Der Lang-Druck bleibt davon unberuehrt."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Anzeige zur Laufzeit, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge, Geometrie."}],"hinweis":"Kein Icon- und kein Formatfeld: das Widget wertet nur wahr/falsch aus (true, 1 oder '1'). Die allgemeine Einstellung 'Beschriftung mehrzeilig' greift hier NICHT - die Beschriftung bleibt immer einzeilig. Zum Schalten braucht die Variable eine beschreibbare Aktion in Symcon; Klicks wirken erst im Vorschau-/Run-Modus, im Editor ist das Widget nur Layout.","groesse":[220,60],"demo":{"label":"Licht Lesezimmer","varId":30519}},
    "chip": {"titel":"Chip","zweck":"Kompakte Zeile aus Icon und Messwert - gedacht fuer Statusleisten und enge Zeilen, in denen nur der nackte Wert Platz hat.","funktionen":[{"name":"Variable","beschreibung":"Zentrales Feld: die Variable, deren formatierter Wert rechts neben dem Icon erscheint. Ohne Wert steht dort ein Gedankenstrich."},{"name":"Format","beschreibung":"Original, kW, kWh, W, 0 Dez., 1 Dez., Prozent, Uhrzeit, Datum oder Relativzeit ('vor 5 min'). Rechnet den Rohwert entsprechend um."},{"name":"Nachkommastellen","beschreibung":"0 bis 6 Stellen, aus dem Rohwert gerundet und mit Komma dargestellt; die Profil-Einheit wird angehaengt. Ist zusaetzlich ein Format ausser 'Original' gesetzt, gewinnt das Format - die Nachkommastellen bleiben dann wirkungslos."},{"name":"Icon (Fallback)","beschreibung":"Symbol links. Ohne Auswahl wird das Standard-Sensor-Icon gezeichnet. Ein ausdruecklich gewaehltes adaptives Icon (z. B. battery, bulb) folgt dem Wert."},{"name":"Icon-Farbe","beschreibung":"Skin-Farbe des Icons (Standard, Akzent, OK, Warnung, Kritisch, Info, Neutral) - gesetzt ueber die CSS-Variable --wicon. Die Zeile erscheint erst, wenn ein Icon gewaehlt ist."},{"name":"Assoziation","beschreibung":"Ist eine Variable gebunden und hat ihr Profil Assoziationen, erscheint der Block 'Icons & Farben nutzen': Icon und Farbe kommen dann aus den Profil-Zuordnungen; je Zustand lassen sich Icon und Skin-Farbe eigens uebersteuern."},{"name":"Farben / Rahmen / Hintergrund","beschreibung":"Text- und Hintergrundfarbe, Rahmen, transparenter Hintergrund - wie bei jeder Kachel."},{"name":"Typografie","beschreibung":"Schriftart, Gewicht, Stil, Schriftgroesse; der Wert selbst wird unabhaengig davon in der Monospace-Schrift des Skins gesetzt."},{"name":"Interaktion","beschreibung":"Seite oeffnen, Popup oeffnen, jeweils auch per Lang-Druck, Popup schliessen, Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Anzeige zur Laufzeit, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge, Geometrie."}],"hinweis":"Der Label-Text wird NICHT dargestellt - der Chip zeigt ausschliesslich Icon und Wert. Die runde Pillenform gilt nur fuer den inneren Inhalt und ist ohne eigenen Hintergrund nicht sichtbar; nach aussen bleibt die normale Kachelform. Praefix/Suffix gibt es hier nicht; die Einheit muss aus dem Variablenprofil oder aus dem Format kommen.","groesse":[190,50],"demo":{"varId":26109,"icon":"temperature","iconColor":"warn","dec":1}},
    "chromebar": {"titel":"Bar (Leiste)","zweck":"Globale waagerechte Leiste am oberen oder unteren Rand, die auf allen Seiten der Ansicht erscheint (nicht in Popups). Sie ist ein reiner Container – sichtbar wird, was man an Widgets hineinlegt.","funktionen":[{"name":"Name","beschreibung":"Bezeichnung der Leiste; erscheint in der Leisten-Übersicht und in Hinweisen im Eigenschaften-Panel der enthaltenen Widgets."},{"name":"Seite","beschreibung":"Andockkante: oben oder unten."},{"name":"Höhe (px)","beschreibung":"Bauhöhe der Leiste, mindestens 8, Vorgabe 56; sie verringert die nutzbare Seitenfläche entsprechend."},{"name":"Hintergrund","beschreibung":"Eigene Hintergrundfarbe oder Schaltfläche „Standard\", die auf die Skin-Farbe zurückstellt."},{"name":"Auswahl","beschreibung":"Verschiebt die aktuell auf der Seite markierten Widgets in diese Leiste; die Zahl im Knopf nennt die Anzahl. Ist nichts markiert, ist der Knopf gesperrt. Gruppen werden dabei aufgelöst, die IDs auf den eigenen Leisten-Namensraum umgestellt."},{"name":"Statuszeile","beschreibung":"Zeigt die berechnete Fläche in Pixeln, die Anzahl enthaltener Widgets und den Hinweis, dass die Leiste auf allen Seiten erscheint."},{"name":"Leiste entfernen","beschreibung":"Löscht die Leiste samt der darin liegenden Widgets."},{"name":"Widgets einfügen","beschreibung":"Aus der Palette direkt in die Leiste ziehen; die Koordinaten sind relativ zur Leiste. Kinder rasten beim Verschieben an ihren Geschwistern sowie an Kanten und Mitte der Leiste ein – die Leisten-Einrastung entfällt in einer Achse, wenn dort zu wenig Luft bleibt."},{"name":"Zurück auf die Seite","beschreibung":"Im Eigenschaften-Panel eines Leisten-Kindes: holt das Widget aus der Leiste zurück auf die normale Seite."},{"name":"Verwaltung","beschreibung":"Unter Einstellungen → Leisten & Zonen lassen sich Leisten anlegen, umbenennen, in der Reihenfolge verschieben und entfernen."}],"hinweis":"Sonderfall in der Datenhaltung: Leisten liegen nicht in den Seiten-Widgets, sondern global im Speicher der Ansicht (store.chrome). Die render()-Funktion liefert bewusst nichts, und die Doku-Seite überspringt Leisten grundsätzlich (DOKU_SKIP) – statt einer Vorschau steht dort ein Hinweistext. Eine Demo-Konfiguration mit Kind-Widgets ist deshalb wirkungslos. Kollidieren Bar und Sidebar, gewinnt die Bar; die Sidebar reicht nur bis an sie heran.","groesse":[640,90],"demo":{}},
    "chromesidebar": {"titel":"Sidebar","zweck":"Globale senkrechte Leiste am linken oder rechten Rand, wie die Bar auf allen Seiten sichtbar (nicht in Popups) und ebenfalls ein reiner Container für Kind-Widgets.","funktionen":[{"name":"Name","beschreibung":"Bezeichnung der Seitenleiste, sichtbar in der Leisten-Übersicht und im Hinweis der enthaltenen Widgets."},{"name":"Seite","beschreibung":"Andockkante: links oder rechts."},{"name":"Breite (px)","beschreibung":"Baubreite der Seitenleiste, mindestens 8, Vorgabe 120; sie verringert die nutzbare Seitenfläche entsprechend."},{"name":"Hintergrund","beschreibung":"Eigene Hintergrundfarbe oder Rückstellung auf den Skin-Standard."},{"name":"Auswahl","beschreibung":"Verschiebt die auf der Seite markierten Widgets in diese Seitenleiste."},{"name":"Statuszeile","beschreibung":"Fläche in Pixeln, Anzahl der enthaltenen Widgets, Hinweis auf die seitenübergreifende Anzeige."},{"name":"Leiste entfernen","beschreibung":"Löscht die Seitenleiste mitsamt Inhalt."},{"name":"Widgets einfügen","beschreibung":"Per Drag & Drop aus der Palette; Positionen sind relativ zur Seitenleiste, mit Einrastung an Geschwistern sowie an Kanten und Mitte der Leiste."},{"name":"Zurück auf die Seite","beschreibung":"Im Eigenschaften-Panel eines Kind-Widgets: holt es aus der Seitenleiste zurück auf die normale Seite."}],"hinweis":"Wie die Bar global in store.chrome gespeichert und ohne eigene Darstellung – sichtbar ist nur der Inhalt. Auch die Sidebar wird auf der Doku-Seite übersprungen und dort nur als Hinweistext gezeigt; eine Demo-Konfiguration läuft daher nicht. Die Bar hat Vorrang: liegt eine Bar oben oder unten, endet die Sidebar an deren Kante. In Popups werden Leisten nicht eingeblendet.","groesse":[180,340],"demo":{}},
    "clock": {"titel":"Uhr","zweck":"Digitale Uhr mit Wochentag und Datum, wahlweise nur Uhrzeit oder nur Datum. Braucht keine Variable - die Zeit kommt vom anzeigenden Gerät.","funktionen":[{"name":"Anzeige","beschreibung":"Eigenschaft clkShow: Uhrzeit + Datum (Vorgabe), nur Uhrzeit oder nur Datum. Das Datum wird als „Mo, 22.7.“ gesetzt."},{"name":"Format","beschreibung":"Eigenschaft h12: 24 Stunden (mit führender Null) oder 12 Stunden mit AM/PM-Zusatz."},{"name":"Sekunden","beschreibung":"Eigenschaft showSec: blendet die Sekunden ein; die Anzeige läuft dann sekundengenau mit."},{"name":"Aktualisierung (kein Feld)","beschreibung":"Die Standard-Uhr (24 h, ohne Sekunden) hängt am zentralen Sekundentakt und zeigt Stunde/Minute. Sobald Sekunden oder 12-Stunden-Format aktiv sind, übernimmt für die Uhrzeit ein eigener Ein-Sekunden-Timer, der beim Einblenden sofort den ersten Wert setzt statt auf den nächsten Tick zu warten. Das Datum kommt in beiden Fällen vom zentralen Takt."},{"name":"Farben / Rahmen / Hintergrund","beschreibung":"Gemeinsam: Text- und Hintergrundfarbe, Rahmen (Standard/An/Aus), deckender oder transparenter Hintergrund."},{"name":"Typografie","beschreibung":"Gemeinsam: Schriftart, Gewicht, Stil und Schriftgröße. Die Zeit wird ansonsten in Monospace mit gleichbreiten Ziffern gesetzt, damit sie beim Zählen nicht springt; das Datum erscheint kleiner und gedämpft."},{"name":"Interaktion","beschreibung":"Gemeinsam: Seite öffnen, Popup öffnen (jeweils auch per Lang-Druck, etwa 550 ms), Popup schließen, Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Gemeinsam: Anzeige zur Laufzeit, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge, Geometrie."}],"hinweis":"Kein Variablen-, Format- oder Icon-Feld - und der Label-Text wird nicht dargestellt. Die angezeigte Zeit ist die Uhr des Browsers/Panels, nicht die des Symcon-Servers; bei falsch gestellten Panels weicht sie ab. Der zentrale Takt versorgt Uhren auf Seite, in Leisten, in Komponenten und in der Laufzeile. Der Zusatz-Timer für Sekunden/12-Stunden-Format erreicht dagegen nur Seite und Leisten: in Komponenten, Laufzeile und Popups bleibt eine so eingestellte Uhrzeit stehen - dort ohne Sekunden und im 24-Stunden-Format arbeiten.","groesse":[220,110],"demo":{"clkShow":"both","showSec":true,"h12":false}},
    "colorpick": {"titel":"Farbwähler","zweck":"Fasst fünf Farb-Bedienelemente in einem Widget zusammen: Farbkreis (HSV), CIE-xy-Picker, RGB-Kanalschieber, Preset-Taste und reine Farbfläche. Je nach Darstellung wird ein 24-Bit-RGB-Integer bzw. ein CIE-x/y-Paar gelesen und geschrieben.","funktionen":[{"name":"Darstellung","beschreibung":"Eigenschaft cmode: wheel = Farbkreis (HSV), cie = CIE-Picker (xy), slider = RGB-Slider (R/G/B), button = RGB-Preset-Taste, box = Farbfläche (Anzeige). Beim Wechsel wird die Widget-Größe auf die Standardgröße der neuen Variante gesetzt (wheel 176x224, cie 150x150, slider 220x120, button 80x80, box 120x120), solange die alte Größe unverändert war."},{"name":"Variable","beschreibung":"Zentrale Variablenzeile (alle Varianten außer CIE). Erwartet einen 24-Bit-RGB-Integer (R*65536 + G*256 + B). Sie wird gelesen (Anzeige) und beim Bedienen geschrieben."},{"name":"x (Var) / y (Var)","beschreibung":"Nur bei CIE-Picker: eigene Zeilen für die CIE-x- und CIE-y-Variable (varId und varId2), jeweils mit „wählen“-Knopf. Geschrieben wird auf drei Nachkommastellen gerundet, x im Bereich 0..0,75 und y im Bereich 0..0,85. Die zentrale Variablenzeile ist in diesem Modus ausgeblendet."},{"name":"Farbe","beschreibung":"Nur bei RGB-Preset-Taste: die Farbe (Eigenschaft color), die die Taste anzeigt und bei Klick als Integer schreibt. Der zugehörige RGB-Wert wird im Editor als Zahl mitangezeigt."},{"name":"Label","beschreibung":"Beschriftung. Farbkreis zeigt sie als kleine Kopfzeile, der RGB-Slider in der Kopfzeile neben Farbfleck und Hex-Wert, die Farbfläche als Zeile unter dem Feld, die Preset-Taste unten in der Farbfläche. Beim Umschalten auf die Tastenvariante wird ein noch unveränderter Standardtext („Farbe“ / „Label“) automatisch geleert."},{"name":"Farben / Rahmen / Hintergrund / Beschriftung / Typografie","beschreibung":"Gemeinsame Gestaltungsfelder: Vorder- und Hintergrundfarbe, Rahmen an/aus/Ansicht-Standard, transparenter Hintergrund, mehrzeilige Beschriftung, Schriftart, Gewicht, Stil und Schriftgröße."},{"name":"Interaktion (Seite öffnen, Popup, Skript-ID, Lang-Druck, Popup schließen)","beschreibung":"Gemeinsame Aktionen. Achtung: Farbkreis und CIE-Picker fangen den Klick immer selbst ab, dort greifen Popup, Navigation und Skript nicht. Die Preset-Taste fängt den Klick nur ab, wenn eine Variable gebunden ist - ohne Variable läuft die allgemeine Aktion. Bei RGB-Slider und Farbfläche bleibt der Klick immer frei für diese Aktionen."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Gemeinsam: Anzeige zur Laufzeit, Steuer-Variable mit Bedingung (wahr, =, ≠, ≥, ≤), Einblend-Animation und Z-Reihenfolge."},{"name":"Ziehen auf Kreis und Helligkeitsbalken (kein Feld)","beschreibung":"Farbkreis: Winkel = Farbton, Radius = Sättigung; der Balken darunter regelt die Helligkeit. Während des Ziehens wird gedrosselt (max. alle 70 ms) geschrieben, beim Loslassen einmal endgültig."},{"name":"Live-Rückmeldung (kein Feld)","beschreibung":"Ändert sich die Variable von außen, ziehen Marker, Vorschau-Fleck, Kanalschieber, Hex-Anzeige oder Farbfläche nach; bei Schwarz oder Weiß behält der Kreis den zuletzt gezeigten Farbton, statt auf Rot zu springen. Unterdrückt wird das Nachziehen beim Farbkreis während des Ziehens und beim RGB-Slider rund 0,9 Sekunden nach der letzten Eingabe bzw. solange ein Kanalregler den Fokus hat; CIE-Picker und Farbfläche haben keine solche Sperre. Die Preset-Taste zeigt Häkchen und Akzentrahmen, wenn ihr Wert aktuell gesetzt ist."},{"name":"Nur im Betrieb schreiben (kein Feld)","beschreibung":"Die RGB-Kanalregler schreiben ausschließlich im Bedienmodus; im Editor bewegen sie nur die Anzeige."}],"hinweis":"Die Variante bestimmt das Datenformat: Farbkreis, Slider, Taste und Fläche brauchen einen RGB-Integer, CIE braucht zwei Fließkommavariablen. Beim Umschalten zwischen CIE und den übrigen Varianten wird die Variablenbindung bewusst gelöst (Meldung im Editor), beim Wechsel weg von CIE zusätzlich varId2.","groesse":[200,250],"demo":{"cmode":"wheel","label":"Farbe","color":"#ff8800"}},
    "container": {"titel":"Container","zweck":"Nimmt beliebig viele andere Widgets auf und behandelt sie als Einheit. Die Kinder werden RELATIV im Container gespeichert: verschiebt man den Container, wandern alle Kinder mit; ändert man seine Größe, skaliert der Inhalt proportional (transform:scale). Optik umschaltbar zwischen Panel (Hintergrund/Rahmen/Titel) und unsichtbar (reiner Gruppierungs-Container).","funktionen":[{"name":"Widgets hineinlegen (kein Feld)","beschreibung":"Ein vorhandenes Widget über den Container ziehen und loslassen - es wird zum Kind (w.kids) und relativ gespeichert. Ein Kind wieder herausziehen (außerhalb der Container-Fläche loslassen) löst es zurück auf die Seite."},{"name":"Kind bearbeiten (kein Feld)","beschreibung":"Kinder direkt anklicken, verschieben und in der Größe ändern - die Bearbeitung rechnet die Container-Skalierung automatisch mit. Entf entfernt ausgewählte Kinder aus dem Container. Container-Kinder sind position:relative, damit sie sich nicht deckungsgleich stapeln."},{"name":"Optik","beschreibung":"Eigenschaft panel: Panel mit Hintergrund/Rahmen (und optionalem Titel) oder Unsichtbar (im Editor gestrichelt angedeutet, im Betrieb ohne eigene Fläche)."},{"name":"Titel","beschreibung":"Eigenschaft title: Beschriftung in der Kopfzeile (nur im Panel-Modus sichtbar)."},{"name":"Kind-Zähler (kein Feld)","beschreibung":"Der Eigenschaften-Bereich zeigt die aktuelle Anzahl der Kind-Widgets an."},{"name":"Live / Position / Sichtbarkeit","beschreibung":"Kinder werden wie normale Widgets live versorgt (ihre Variablen werden mitgepollt). Der Container selbst hat Position, Größe, Ebene und variablengesteuerte Sichtbarkeit - womit sich die ganze Gruppe auf einmal ein-/ausblenden lässt."},{"name":"Proportionale Einpassung (kein Feld)","beschreibung":"Im Editor liegt der Inhalt 1:1 (Design-Fläche baseW x baseH). Im Betrieb, Mobil und Webview passt sich der Inhalt proportional in die Container-Größe ein, so dass alle Kinder sichtbar bleiben."}],"hinweis":"Kinder liegen physisch im Container (w.kids), nicht mehr in der Seitenliste - Kopieren des Containers dupliziert die Kinder mit neuen IDs. Ein Container kann (in dieser Version) keinen weiteren Container enthalten. Für eine wiederverwendbare, mehrfach mit anderen Geräten bestückte Vorlage ist die Komponente gedacht, nicht der Container. noHover ist gesetzt (kein Hover-Flyout).","groesse":[320,200],"demo":{"type":"container","panel":true,"title":"Wohnzimmer","kids":[{"id":"cd1","type":"valuecard","x":12,"y":12,"w":150,"h":84,"icon":"temperature","label":"Temperatur","unit":"C","vcMode":"value","varId":900004},{"id":"cd2","type":"switch","x":176,"y":12,"w":150,"h":50,"label":"Licht","varId":900050,"swOn":"ok"}]}},
    "component": {"titel":"Komponente","zweck":"Bettet eine andere Ansicht als wiederverwendbare Vorlage ein und skaliert sie in den Rahmen des Widgets. Über eine Alias-Tabelle lassen sich die Variablen-IDs der Vorlage auf echte Geräte umbiegen, so dass dieselbe Vorlage mehrfach mit unterschiedlichen Geräten genutzt werden kann.","funktionen":[{"name":"Komponente","beschreibung":"Auswahl der Ansicht (Eigenschaft comp), die als Master eingebettet wird. Änderungen am Master wirken sofort auf alle Instanzen - es wird nicht kopiert, sondern zur Laufzeit expandiert."},{"name":"Region-Name","beschreibung":"Optionaler Slot-Name (Eigenschaft slot). Ist er gesetzt und wurde für diesen Slot zur Laufzeit eine Ansicht gewählt (durch ein Widget mit „Region setzen“), gilt diese; solange keine Region gesetzt ist, greift weiterhin die unter Komponente gewählte Ansicht als Rückfall. Ist gar nichts vorhanden, erscheint der Platzhalter „Region …“."},{"name":"Parameter: Vorlagen-ID → echte ID","beschreibung":"Listen-Editor (Eigenschaft alias) mit beliebig vielen Zeilen aus from und to. Jede Zeile ersetzt in der eingebetteten Ansicht eine Variablen-ID durch eine andere; das Remapping greift für Variable, zweite und dritte Variable sowie die Sichtbarkeits-Steuervariable."},{"name":"Label / Name","beschreibung":"Gemeinsam: Beschriftung (wird selbst nicht gezeichnet) und interne eindeutige Kennung des Elements. Eine zentrale Variablenzeile hat dieses Widget nicht."},{"name":"Farben / Rahmen / Hintergrund / Beschriftung / Typografie","beschreibung":"Gemeinsame Gestaltungsfelder des Rahmens, in dem die Komponente sitzt. Der Inhalt wird beschnitten (overflow hidden, abgerundete Ecken)."},{"name":"Interaktion (Seite öffnen, Popup, Skript-ID, Lang-Druck, Popup schließen)","beschreibung":"Gemeinsame Aktionen auf dem Container. Bei gesetztem Popup erscheint zusätzlich eine Alias-Tabelle für das Popup - sie schreibt jedoch in dieselbe Eigenschaft alias wie die Parametertabelle der Komponente."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Gemeinsam: Anzeige zur Laufzeit, bedingte Sichtbarkeit über eine Steuer-Variable, Einblend-Animation, Z-Reihenfolge."},{"name":"Automatische Skalierung (kein Feld)","beschreibung":"Die Vorlage wird anhand ihrer Seitengröße gleichmäßig auf die Widget-Größe skaliert (kleinerer Faktor aus Breite und Höhe; ohne Seitenangabe wird mit 400x300 gerechnet). Im Editor ist der Inhalt klickfest und mit gestricheltem Rand markiert, im Betrieb bedienbar."},{"name":"Live-Werte der Kinder (kein Feld)","beschreibung":"Alle eingebetteten Elemente kommen in den Variablen-Index und bekommen ihre mount-Hooks, verhalten sich also wie normale Widgets - mit den per Alias umgebogenen IDs. Der Renderpfad (expandComponent) baut die Kinder über denselben Weg wie der Container auf, so dass Rahmen, Deckung, Offsets und Typografie auch in Komponenten gelten."}],"hinweis":"Stolperfalle: Popup-Alias und Parametertabelle teilen sich die Eigenschaft alias - wer bei einer Komponente zusätzlich ein Popup einstellt, bearbeitet mit beiden Editoren dieselbe Liste. Braucht eine zweite, bereits angelegte Ansicht als Master; ohne Auswahl zeigt das Widget nur „Komponente wählen …“. Die eigene Ansicht darf nicht gewählt werden (Selbstbezug wird erkannt und gemeldet). Expandiert wird nur auf der Seitenfläche - eine Komponente innerhalb eines Popups bleibt leer.","groesse":[280,200],"demo":{"label":"Komponente","comp":"","slot":"","alias":[{"from":"26109","to":"26109"},{"from":"55099","to":"55099"}]}},
    "cover": {"titel":"Rollo","zweck":"Bedient ein Rollo oder eine Jalousie: links ein Fenster, das zugleich als vertikaler Positionsschieber dient und die Sonne aus der Sonnenstandsberechnung zeigt, rechts Name, Status, Modus-Icon, Zu/Halb/Auf-Presets und Auf/Stop/Zu-Tasten. Für Anlagen mit eigener Befehlsvariable (z. B. IPSShadowing) lassen sich echte Fahrbefehle statt Positionssprüngen hinterlegen.","funktionen":[{"name":"Variable (Position)","beschreibung":"Positionsvariable in Prozent (varId). Sie speist Fenster, Prozentanzeige und beide Schieber; die Schieber schreiben sie zurück. Die Kachel zeigt immer den Öffnungsgrad (100 = ganz offen)."},{"name":"Befehls-Variable","beschreibung":"Zweite Variable (varId2, optional): Kommandovariable der Anlage. Ist sie gesetzt und sind Befehlswerte hinterlegt, fahren Tasten und Presets über dieses Kommando statt über die Position."},{"name":"Modus/Status-Variable","beschreibung":"Dritte Variable (varId3, optional): Auto/Sonne/Manuell. Ist sie gebunden, wird das Modus-Icon oben rechts zur Umschalttaste (Klick wechselt Manuell↔Auto). Das Icon folgt dem Modus - Uhr = Auto (Zeitplan), Sonne = Sonnenautomatik (hervorgehoben), Hand = Manuell, Mond = nachts. Liefert die Variable einen nicht-numerischen Statustext, erscheint dieser bevorzugt in der Statuszeile."},{"name":"Helligkeit (Lux, optional)","beschreibung":"Eigenschaft covBrightVid: Lux-Variable. Die Sonne wird nur eingeblendet, wenn die Helligkeit über der Schwelle liegt (covBrightMin)."},{"name":"Fenster-Visualisierung","beschreibung":"Eigenschaft covViz (Vorgabe an): zeigt Rollo/Glas links; das Fenster ist zugleich der vertikale Positions-Slider. Aus = nur die rechte Steuerung."},{"name":"Sonne anzeigen","beschreibung":"Eigenschaft covSun (Vorgabe an): Sonnenpunkt im Glas, nur bei Tag (Höhe über covElMin) und ausreichend offenem Rollo. Position aus Azimut/Höhe des berechneten Sonnenstands, alle 60 s nachgeführt."},{"name":"Slider unter Tasten","beschreibung":"Eigenschaft covSlider (Vorgabe aus): zusätzlicher horizontaler Positionsschieber mit 0/50/100-Skala unter den Tasten."},{"name":"Anzeige gespiegelt","beschreibung":"Eigenschaft cvInv: Gerät zählt den Schließgrad (0 = offen, 100 = zu). Die Kachel zeigt weiterhin den Öffnungsgrad; geschrieben wird der korrekte Rohwert - auch Auf/Zu setzen den richtigen Wert des Geräts statt hart 100/0."},{"name":"Befehl Auf","beschreibung":"Eigenschaft cvUp: Wert, den die Auf-Taste auf die Befehlsvariable schreibt (IPSShadowing 14). Leer = Position 100 fahren."},{"name":"Befehl Halb","beschreibung":"Eigenschaft cvHalf: Wert für die Halb-Preset-Taste auf der Befehlsvariable (IPSShadowing 13). Leer = Position 50 fahren."},{"name":"Befehl Stop","beschreibung":"Eigenschaft cvStop: Wert für die Stop-Taste (IPSShadowing 13-analog). Leer = 1 auf die Befehlsvariable; ohne Befehlsvariable tut Stop nichts."},{"name":"Befehl Zu","beschreibung":"Eigenschaft cvDn: Wert für die Zu-Taste (IPSShadowing 11). Leer = Position 0 fahren."},{"name":"Fensterrichtung (Azimut)","beschreibung":"Eigenschaft covFace (0-360, 180 = Süd): steuert die horizontale Lage der Sonne im Fenster relativ zum Sonnenazimut."},{"name":"Breitengrad / Längengrad","beschreibung":"Eigenschaften covLat/covLon: Standort für die Sonnenstandsberechnung. Leer = Haus-Vorgabe (48.0657 / 14.1241)."},{"name":"Schriftgrößen (px, leer = auto)","beschreibung":"Getrennte Größen für Name (covNameFs), Status (covStatusFs), Prozent-Wert (covValFs), Presets (covPreFs), Tasten (covBtnFs) und Skala/Tick (covScFs). Leer = automatische Größe aus dem em-System."},{"name":"Stil-Farben","beschreibung":"Skin-Farben für Akzent (covAccent), Name (covName), Wert (covVal) und Status (covState)."},{"name":"Tasten-Icons (kein Feld)","beschreibung":"Auf/Stop/Zu nutzen die Icons icUp/icStop/icDn (Vorgabe chevup/stop/chevdn)."},{"name":"Tastenlogik und Vorrang (kein Feld)","beschreibung":"Ist ein Seiten- oder Popup-Ziel (oder „Seite zurück“) gesetzt, gewinnt dieses und die Tasten schalten nicht. Ein Klick neben die Tasten wird nicht abgefangen und löst die allgemeine Aktion aus. Presets schreiben Kommando ODER Position (inversionssicher)."},{"name":"Live-Aktualisierung (kein Feld)","beschreibung":"Nur die Positionsvariable setzt Wertfeld, Fenster und Schieber; Befehls- und Modusvariable schreiben nie in die Positionsanzeige. Ein Schieber wird nicht überschrieben, solange er den Fokus hat. Die Statuszeile leitet sich aus der Position ab (geschlossen / offen / X % offen), sofern kein echter Statustext gesetzt ist."}],"hinweis":"Für IPSShadowing „Anzeige gespiegelt“ anhaken und die Befehle 14/13/11 als Auf/Halb-Stop/Zu hinterlegen - sonst würde die Kachel bei Auf/Zu direkt 100 bzw. 0 Prozent auf die Positionsvariable schreiben, statt zu fahren. Das Modus-Icon wird nur zur Umschalttaste, wenn die dritte Variable gebunden ist. noHover ist gesetzt.","groesse":[240,140],"demo":{"label":"Rollo Büro","varId":21613,"varId2":44398,"varId3":33327,"cvInv":true,"cvUp":"14","cvStop":"13","cvDn":"11"}},
    "cval": {"titel":"Zählerwert","zweck":"Zeigt den Verbrauch (die Differenz) einer Zählervariablen über eine wählbare Periode als einzelne große Zahl, z. B. „heute“ oder „dieser Monat“. Der Wert kommt aus der Aggregation des Archivs, nicht aus dem Rohwert der Variablen.","funktionen":[{"name":"Aggregationsstufe","beschreibung":"Eigenschaft cmpStage: Periode, über die die Differenz gebildet wird - Minute, Stunde, Tag, Woche, Monat, Jahr. Die laufende Periode erscheint zusätzlich als Zusatz im Label („heute“, „dieser Monat“ usw.)."},{"name":"Variable","beschreibung":"Die Zählervariable. Sie muss geloggt sein, damit die Differenz der Periode berechnet werden kann."},{"name":"Einheit","beschreibung":"Freitext-Einheit (Eigenschaft unit), die hinter der Zahl steht (z. B. kWh). Ersetzt die Profileinheit, da der Wert berechnet ist."},{"name":"Wert-Größe","beschreibung":"Schriftgröße der Zahl in Pixel (Eigenschaft valfs, Standard 26)."},{"name":"Ausrichtung","beschreibung":"Eigenschaft align: leer = links, center = zentriert, right = rechts."},{"name":"Präfix / Suffix","beschreibung":"Gemeinsame Eigenschaften pre und suf: Text unmittelbar vor bzw. hinter der Zahl. Wird bei fehlendem Wert (–) nicht angehängt."},{"name":"Farbe nach Schwelle: Aktiv","beschreibung":"Eigenschaft colThr: schaltet die Zustandsfärbung der Zahl ein."},{"name":"Grün bis / Gelb bis","beschreibung":"Die beiden Schwellen t1 und t2: bis zur ersten grün (OK), bis zur zweiten warm/gelb, darüber rot (kritisch)."},{"name":"Invertieren","beschreibung":"Eigenschaft thrInvert: dreht die Färbung um - kleine Werte werden kritisch, große gut."},{"name":"Nachkommastellen","beschreibung":"Gemeinsam (dec). Leer heißt automatisch: je nach Betrag 0 bis 3 Stellen."},{"name":"Einzeilig bei geringer Höhe","beschreibung":"Gemeinsam (lineMode): bei flach gezogenem Widget rutschen Label und Wert in eine Zeile."},{"name":"Label / Farben / Rahmen / Beschriftung / Typografie / Interaktion / Sichtbarkeit / Animation / Ebene","beschreibung":"Gemeinsame Felder wie bei allen Widgets, inklusive Popup, Skript-ID und bedingter Sichtbarkeit."},{"name":"Aktualisierung (kein Feld)","beschreibung":"Der Wert wird direkt nach dem Zeichnen berechnet und bei jeder Wertänderung der Variablen neu geholt; das Ergebnis wird kurz zwischengespeichert. Ein Wechsel der Aggregationsstufe verwirft den Zwischenspeicher sofort."}],"hinweis":"Braucht eine archivierte Zählervariable; ohne Logging oder ohne Archiv-Aggregation bleibt die Anzeige auf „–“. Der berechnete Wert ist eine Differenz - die Einheit kommt aus dem Feld Einheit, nicht aus dem Variablenprofil.","groesse":[220,120],"demo":{"label":"Verbrauch","varId":48275,"cmpStage":"day","unit":"kWh","dec":1,"valfs":28,"align":""}},
    "delta": {"titel":"Delta","zweck":"Kleiner Trend-Chip aus Pfeil, Wert und Kennung. Entweder mit fest eingetragenem Text und Richtung als reine Anzeige, oder mit eingeschaltetem Zeitversatz-Vergleich, der die Veränderung gegenüber der Vorperiode selbst berechnet und einfärbt.","funktionen":[{"name":"Text","beschreibung":"Eigenschaft text: der angezeigte Wert im statischen Betrieb, z. B. „+6 %“. Ist der Vergleich aktiv, ist das Feld gesperrt, weil der Wert berechnet wird (er steht dann nur noch bis zur ersten Antwort des Servers)."},{"name":"Richtung","beschreibung":"Eigenschaft dir: Pfeil ▲ up, ▼ dn oder → flat (Feld nur ohne Vergleich sichtbar)."},{"name":"Farbe","beschreibung":"Eigenschaft tone: OK (grün), Fehler (crit/rot), Warnung (warn), Neutral (muted) - Feld nur ohne Vergleich sichtbar."},{"name":"Vergleich (Zeitversatz): Aktiv","beschreibung":"Eigenschaft cmpOn (zentraler Editor). Eingeschaltet holt das Widget aktuellen Wert und Wert der Vorperiode und zeigt die Veränderung; Text/Richtung/Farbe werden dann automatisch bestimmt."},{"name":"Aggregationsstufe","beschreibung":"Eigenschaft cmpStage: Bezugsperiode des Vergleichs (Minute bis Jahr). Die Kennung nennt die Gegenperiode, z. B. „ggü. gestern“."},{"name":"Zählervariable","beschreibung":"Eigenschaft cmpCounter: behandelt die Variable als Zähler und vergleicht den Verbrauch je Periode statt des Punktwerts."},{"name":"Periodenmittel","beschreibung":"Eigenschaft cmpAvg, nur bei Nicht-Zählern sichtbar: vergleicht den Mittelwert über die Periode statt eines Punktwerts."},{"name":"Anzeige","beschreibung":"Eigenschaft cmpMode: pct = prozentuale, abs = absolute Veränderung. Bei abs wird die Eigenschaft unit angehängt."},{"name":"Veränderung invertieren","beschreibung":"Eigenschaft cmpInvert: Rückgang gilt als gut (z. B. bei Verbrauch). Es dreht nur die Farbe, der Pfeil bleibt richtungstreu."},{"name":"Variable","beschreibung":"Die Bezugsvariable für den Vergleich (varId)."},{"name":"Einzeilig bei geringer Höhe","beschreibung":"Gemeinsam (lineMode): zieht Wert und Kennung nebeneinander, Kennung rechtsbündig."},{"name":"Label / Farben / Rahmen / Beschriftung / Typografie / Interaktion / Sichtbarkeit / Animation / Ebene","beschreibung":"Gemeinsame Felder. Das Label steht als Kennung unter dem Wert, bei aktivem Vergleich ergänzt um den Bezug („Label · ggü. gestern“)."},{"name":"Zustandsfärbung (kein Feld)","beschreibung":"Bei aktivem Vergleich färbt sich der Chip automatisch: Anstieg grün, Rückgang rot (bzw. umgekehrt bei Invertieren), keine Änderung neutral grau."}],"hinweis":"Der Vergleich braucht eine archivierte Variable; liefert die Auswertung keine Werte, steht dort „–“ und der Chip wird neutral. Das gemeinsame Feld Nachkommastellen wird beim Delta nicht ausgewertet - der berechnete Wert wird fest gerundet (ab 100 ganzzahlig, darunter eine Stelle). Ohne aktivierten Vergleich ist das Widget reine Dekoration mit fest eingetragenem Text.","groesse":[200,110],"demo":{"label":"Stromverbrauch","varId":33962,"cmpOn":true,"cmpCounter":true,"cmpStage":"day","cmpMode":"pct","cmpInvert":true,"tone":"ok","dir":"up","text":"+6 %","unit":"kWh"}},
    "devlist": {"titel":"Geräte-Liste","zweck":"Kompakte Liste von Zeilen aus Icon, Name und Wert. Jede Zeile kann an eine eigene Variable gebunden werden und zeigt deren formatierten Wert - gedacht als Übersicht mehrerer Geräte in einer Kachel.","funktionen":[{"name":"Geräte: Name · Icon · ID","beschreibung":"Listen-Editor (Eigenschaft items) mit beliebig vielen Zeilen. Je Zeile: label (Text links), icon (Name aus der Icon-Bibliothek, Rückfall battery), dec (Nachkommastellen), unit (Einheit) und vid (Variablen-ID, deren Wert rechts erscheint). Der Live-Wert wird pro Zeile über dec/unit formatiert (ohne Angabe gilt die Profil-Formatierung der Variable). Zeilen lassen sich einzeln löschen und neue anhängen; die Vorgabe sind zwei Zeilen „Gerät 1/2“."},{"name":"Label / Name","beschreibung":"Gemeinsam: Beschriftung des Elements (wird in der Liste selbst nicht gezeichnet) und interne Kennung. Eine zentrale Variablenzeile hat dieses Widget nicht."},{"name":"Farben / Rahmen / Hintergrund / Beschriftung / Typografie","beschreibung":"Gemeinsame Gestaltung. Die Icons erscheinen in der Akzentfarbe, die Werte in Monospace."},{"name":"Interaktion (Seite öffnen, Popup, Skript-ID, Lang-Druck, Popup schließen)","beschreibung":"Gemeinsame Aktionen auf der ganzen Kachel - die Liste hat keine eigene Klicklogik, ein Klick löst also das eingestellte Ziel aus."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Gemeinsam: Anzeige zur Laufzeit, bedingte Sichtbarkeit, Einblend-Animation, Z-Reihenfolge."},{"name":"Live-Werte je Zeile (kein Feld)","beschreibung":"Die Wertfelder werden über generische Slots der Zeilen-ID gefüllt; angezeigt wird der über dec/unit der Zeile formatierte Wert bzw. der formatierte Profil-Text. Ohne ID bleibt „–“ stehen. Format, Präfix und Suffix des Widgets wirken auf diese Zeilen nicht."},{"name":"Scrollen und Hover (kein Feld)","beschreibung":"Passt die Liste nicht in die Kachel, wird sie scrollbar. Die Zeile unter dem Zeiger wird leicht hinterlegt."}],"hinweis":"Die Zeilen zeigen nur an, sie schalten nicht - für schaltbare Zeilen sind Schalter- oder Statuslisten-Widgets gedacht. Der Icon-Name muss exakt einem Eintrag der Icon-Bibliothek entsprechen, sonst bleibt das Feld leer; temperature, bolt, droplet, bulb und battery gibt es. Die Zeilenwerte werden nur auf der Seitenfläche aktualisiert - in einem Popup bleibt die Liste auf „–“.","groesse":[260,190],"demo":{"label":"Geräte","items":[{"label":"Außentemperatur","icon":"temperature","vid":26109},{"label":"Verbraucher","icon":"bolt","vid":55099},{"label":"Zisterne","icon":"droplet","vid":41522},{"label":"Licht Lesezimmer","icon":"bulb","vid":30519}]}},
    "eventctl": {"titel":"Ereignis","zweck":"Zeigt ein IP-Symcon-Ereignis (Wochenplan oder Timer) mit Name, Zustand und naechster Ausfuehrung und schaltet es ueber einen Schieber aktiv oder inaktiv.","funktionen":[{"name":"Ereignis-ID","beschreibung":"Eigenschaft eventId: Objekt-ID des Ereignisses (Wochenplan oder zyklischer Timer). Nach dem Eintragen werden Name, Aktivzustand und naechster Termin abgerufen. Eine Variablenzeile hat dieses Widget nicht."},{"name":"Label","beschreibung":"Gemeinsam: eigener Anzeigename. Bleibt er leer, zeigt das Widget den vom Server gemeldeten Namen des Ereignisses an - gespeichert wird dieser Name nicht."},{"name":"Farben / Rahmen / Hintergrund / Beschriftung / Typografie","beschreibung":"Gemeinsame Gestaltung von Text, Hintergrund und Schrift."},{"name":"Interaktion (Seite oeffnen, Popup, Skript-ID, Lang-Druck, Popup schliessen)","beschreibung":"Gemeinsame Aktionen. Der Klick auf den Schieber wird vom Widget abgefangen, sofern eine Ereignis-ID gesetzt ist; ein Klick auf den uebrigen Bereich loest das eingestellte Ziel aus. Ohne ID greift auch auf dem Schieber die allgemeine Aktion."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Gemeinsam: Anzeige zur Laufzeit, bedingte Sichtbarkeit ueber eine Steuer-Variable, Einblend-Animation, Z-Reihenfolge."},{"name":"Statuszeile (kein Feld)","beschreibung":"Unter dem Namen steht 'aktiv' bzw. 'inaktiv' und, sofern bekannt, der naechste Termin im deutschen Format."},{"name":"Schalten (kein Feld)","beschreibung":"Ein Klick auf den Schieber setzt das Ereignis ueber ?api=setevent aktiv oder inaktiv; der Schieber springt sofort um und wird nach rund 0,3 Sekunden mit dem tatsaechlichen Zustand abgeglichen."},{"name":"Aktualisierung (kein Feld)","beschreibung":"Der Zustand wird nach dem Zeichnen und danach im Minutentakt neu geholt - unabhaengig von Variablenaenderungen, denn Ereignisse liefern keine Werte."}],"hinweis":"Braucht die ID eines Ereignisses, keine Variablen-ID; Abfrage und Schalten laufen ueber die Schnittstelle der Ansicht und funktionieren daher nur im Betrieb, nicht in einer rein statischen Vorschau.","groesse":[270,96],"demo":{"label":"Wochenplan Beschattung","eventId":0}},
    "flow": {"titel":"Fluss","zweck":"Stellt einen Stofffluss als Schema dar: als Reihe von Stationen mit animierten Verbindungen (Pipeline), als Energiefluss-Bild mit Haus-Knoten und ringsum angeordneten Erzeugern/Verbrauchern (Energie) oder als Quellen-Zentrum-Senken-Schema (Hub). Tempo und Richtung der Animation ergeben sich aus gemessenen Werten.","funktionen":[{"name":"Modus","beschreibung":"Pipeline (Reihe), Energie (Power-Flow) oder Hub (Quellen zu Zentrum zu Senken). Die Auswahl tauscht die kompletten Eigenschaften darunter aus."},{"name":"Variable","beschreibung":"Nur im Pipeline-Modus wirksam: Fluss-Wert, der die Konnektoren steuert. Betrag ueber der Schwelle = Fluss laeuft, negativer Wert = Laufrichtung dreht sich um."},{"name":"Farbe (Fluss, Pipeline)","beschreibung":"Zwei Skin-Farben: 'An' fuer laufende Konnektoren (Vorgabe #00cdab), 'Aus' fuer gestoppte (Vorgabe muted)."},{"name":"Schwelle / Referenz (Pipeline)","beschreibung":"Unter der Schwelle steht der Fluss still und wird grau gezeichnet; die Referenz ist der Wert, bei dem das Tempo maximal ist (Umlaufdauer 1,9 s bis 0,5 s). Vorgabe Schwelle 0, Referenz 20."},{"name":"Ausrichtung (Pipeline)","beschreibung":"Horizontal oder vertikal; dreht Knotenreihe und Laufrichtung der Animation."},{"name":"Eingangs-Pfeil","beschreibung":"Schaltet einen Pfeil vor der ersten Station ein, mit optionaler Beschriftung daneben (startLabel)."},{"name":"Becken-Knoten","beschreibung":"Haengt am Ende ein Becken mit animierter Wellenlinie an; Label (tankLabel) und Wert-ID (tankVid) frei waehlbar."},{"name":"Stationen (Liste, Block-Editor)","beschreibung":"Je Station als beschrifteter Block: Icon (Picker), Icon-Farbe (Skin), Label, Wert-ID, Zusatztext (sub), Zusatz-ID (subvid), 0/1-Status-Var (sv), Aktiv-Farbe (svColor, ueberschreibt die Icon-Farbe wenn Status an) und Aus-Farbe (svColorOff). Die Status-Var stoppt zusaetzlich den Fluss der Verbindung ZUR NAECHSTEN Station, wenn sie aus ist (z. B. Solarventil zu -> keine Stroemung Ventil->Pumpe)."},{"name":"Home-Knoten (Energie)","beschreibung":"Name, Icon, Farbe (echter Farbwaehler) und optionale Wert-ID (homeVid) des mittleren Knotens. Bleibt die Wert-ID leer, zeigt er die Summe aller zum Haus fliessenden Betraege."},{"name":"Dauer bei 100 % (s) (Energie)","beschreibung":"Umlaufdauer eines Laufpunkts bei vollem Anteil (efDur100, Vorgabe 0,6 s). Halber Anteil = doppelte Dauer, gedeckelt beim Zwanzigfachen."},{"name":"Tempo automatisch (Energie)","beschreibung":"efSpeedAuto: Referenz fuer das Tempo ist die Summe aller aktuellen Einspeisungen; jeder Knoten laeuft anteilig. Ausgeschaltet gilt die feste Referenz-Leistung."},{"name":"Referenz-Leistung (Tempo) (Energie)","beschreibung":"Fester Bezugswert in W (efRef, Vorgabe 3000), greift bei ausgeschalteter Automatik oder wenn gerade nichts einspeist."},{"name":"Rand (px) / Knotenabstand (px) (Energie)","beschreibung":"Rand ringsum (efPad, 18) und Mindestabstand zwischen den Knoten (efGap, 16); die Zeichenflaeche waechst rechnerisch mit der Zahl der Knoten (mindestens 400x300)."},{"name":"Verbraucher je Spalte (Energie)","beschreibung":"efMaxCol: ab wie vielen Verbrauchern die ueberzaehligen in die untere Reihe wandern (Vorgabe 3, 0 = alle in die rechte Spalte)."},{"name":"Elemente (Liste, Energie)","beschreibung":"Je Zeile Typ (PV/Erzeuger, Netz, Batterie, Verbraucher, Sonstiges), Name, Icon, Skin-Farbe, Leistungs-ID (vid), optionale Speed-ID (speedVid) mit eigener Speed-Referenz (speedRef) und SoC-ID (socVid). Der Typ bestimmt Position (PV oben, Netz links, Verbraucher rechts, Batterie und Sonstiges unten) und Standard-Icon (solarpanel, pylon, battery, plug, gauge)."},{"name":"Richtung / Faerbung (Energie, kein Feld)","beschreibung":"PV fliesst immer zum Haus, Verbraucher und Sonstiges immer weg; nur bei Netz und Batterie entscheidet das Vorzeichen. Netz und Batterie zeigen zwei Wertzeilen (Bezug/Einspeisung bzw. Laden/Entladen), Batterie zusaetzlich den Ladestand im Kreis. Werte ab 1000 W automatisch in kW; unter 1 W blenden Laufband und Laufpunkt aus, die duenne Verbindungslinie bleibt sichtbar."},{"name":"Quellen / Senken (Hub)","beschreibung":"Zwei Listen mit Name und Variablen-ID; links Quellen, rechts Senken, in der Mitte ein Haus-Rechteck mit dem Widget-Label (ohne Label steht dort 'Haus')."},{"name":"Label","beschreibung":"Im Hub-Modus Beschriftung des Zentrums; \\n erzwingt einen Zeilenumbruch (auch in Element-Namen des Energie-Modus)."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Kachel-Eigenschaften."},{"name":"Interaktion","beschreibung":"Klick oder Lang-Druck oeffnet Seite oder Popup, dazu 'Popup schliessen' und Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge."},{"name":"Live-Aktualisierung","beschreibung":"Im Energie-Modus wird bei jeder Aenderung einer Element-ID das ganze Bild neu berechnet, im Pipeline-Modus nur der Fluss-Zustand; Stations- und Beckenwerte laufen ueber die generischen Wert-Slots."}],"hinweis":"Drei Modi mit voellig unterschiedlichen Feldern - nach dem Umschalten ist die alte Konfiguration nicht mehr sichtbar (bleibt aber gespeichert). Die Farbe eines Energie-Elements ist ein Skin-Schluessel; unbekannte Werte fallen auf den Akzent zurueck. Bei reduzierter Bewegung im Betriebssystem stehen die Animationen still. Alte Instanzen vom Typ powerflow werden ueber einen Alias weiter gerendert.","groesse":[620,200],"demo":{"label":"Wasseraufbereitung","mode":"pipeline","varId":38704,"flPos":"#00cdab","flThr":5,"flRef":2000,"flDir":"h","startArrow":1,"startLabel":"Zulauf","endTank":1,"tankLabel":"Zisterne","tankVid":41522,"stages":[{"icon":"valve","label":"Ventil","vid":30519},{"icon":"pump","label":"Pumpe","vid":38704,"sub":"Leistung"},{"icon":"filter","label":"Filter","vid":13239},{"icon":"gauge","label":"Durchfluss","vid":38704}]}},
    "flowline": {"titel":"Energiefluss","zweck":"Zeichnet eine einzelne animierte Fluss-Linie, deren Farbe, Staerke und Laufrichtung sich aus einer Variablen ergeben. Gedacht als verbindendes Element zwischen anderen Kacheln, ohne eigene Beschriftung oder Wertanzeige.","funktionen":[{"name":"Variable","beschreibung":"Der Wert steuert alles: Vorzeichen bestimmt die Laufrichtung, Betrag die Linienstaerke, Nulldurchgang die Farbe."},{"name":"Ausrichtung","beschreibung":"Horizontal oder vertikal; legt Lage der Spur und Achse der Animation fest."},{"name":"Positiv","beschreibung":"Skin-Farbe fuer Werte ueber der Schwelle (Auswahl accent, ok, info, warn, crit, muted, warm; Vorgabe ok)."},{"name":"Negativ","beschreibung":"Skin-Farbe fuer Werte unter der negativen Schwelle (Vorgabe crit); die Animation laeuft dann rueckwaerts."},{"name":"Schwelle","beschreibung":"Totband um Null. Innerhalb bleibt die Linie grau (--muted) und die Animation steht still."},{"name":"Referenz","beschreibung":"Wert, bei dem die maximale Linienstaerke erreicht ist; die Staerke waechst linear von 2 px auf 12 px (Vorgabe 1000)."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Kachel-Eigenschaften; fuer eine reine Verbindungslinie ueblicherweise Rahmen aus und Hintergrund transparent. Die Typografie bleibt hier ohne sichtbare Wirkung, weil das Widget keinen Text zeichnet."},{"name":"Interaktion","beschreibung":"Klick oder Lang-Druck kann Seite oder Popup oeffnen, dazu 'Popup schliessen' und Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge."},{"name":"Live-Aktualisierung","beschreibung":"Bei jedem neuen Wert werden Farbverlauf, Staerke, Laufrichtung und Play/Pause direkt am Element gesetzt - ohne Neuaufbau des Widgets."}],"hinweis":"Zeigt keinen Zahlenwert und kein Label - dafuer daneben ein Wert-Widget setzen. Eine Richtungsumkehr ist nur bei Variablen mit Vorzeichen sichtbar; ein reiner Betragswert laeuft immer in dieselbe Richtung. Die Animation steckt im Inline-Stil und laeuft auch bei reduzierter Bewegung im Betriebssystem weiter (anders als beim Fluss-Widget).","groesse":[280,60],"demo":{"label":"Netzfluss","varId":38704,"flDir":"h","flPos":"ok","flNeg":"crit","flThr":5,"flRef":2000,"bgT":1,"frame":false}},
    "doubledonut": {"titel":"Doppel-Donut","zweck":"Zwei Halb-Donuts in einem Kreis: die obere Hälfte zeigt einen Wert, die untere Hälfte einen zweiten - gespiegelt, jede zwischen eigenem Min und Max. In der Mitte optional ein dritter Wert mit Untertitel. Der Kreis bleibt in jeder Kachelform rund.","funktionen":[{"name":"Variable / Unterer Wert / Mittelwert","beschreibung":"Drei Bindungen: obere Hälfte (varId), untere Hälfte (varId2) und der reine Anzeigewert in der Mitte (varId3)."},{"name":"Min / Max oben bzw. unten","beschreibung":"Eigenschaften topMin/topMax und botMin/botMax: Bereich, zwischen dem sich die jeweilige Hälfte füllt (Vorgabe 0..100). Werte außerhalb rasten am Rand ein."},{"name":"Farbe oben / unten","beschreibung":"Skin-Farben ddTop/ddBot je Hälfte (Vorgabe oben OK-Grün, unten Info-Blau)."},{"name":"Untertitel (Mitte)","beschreibung":"Eigenschaft sub: kleiner Text unter dem Mittelwert."},{"name":"Ringdicke (px)","beschreibung":"Eigenschaft ddW: Stärke der beiden Bögen, 4 bis 48 (Vorgabe 22)."},{"name":"Rundung","beschreibung":"Eigenschaft ddCap: runde Max-Spitze (Basis berührt sich bei Min) oder gerade Enden (bündig). Bei geraden Enden und beiden Hälften auf Max entsteht bei 3 Uhr ein durchgehender, zweifarbiger Vollkreis."},{"name":"Glow","beschreibung":"Eigenschaft ddGlow (Vorgabe an): dezenter, farbgleicher Leuchteffekt (weicher Blur-Halo) hinter Füllung und Spitze; Track und Text bleiben scharf."},{"name":"Schriftart / Gewicht","beschreibung":"Eigenschaften ddFont/ddWeight: Schriftfamilie und Strichstärke (normal/halbfett/fett) für alle Beschriftungen; leer lässt die Standardschrift."},{"name":"Größe Mitte / Untertitel","beschreibung":"Eigenschaften fsCenter/fsSub: Schriftgröße des Mittelwerts und des Untertitels darunter (in viewBox-Einheiten, skaliert mit der Kachel)."},{"name":"Größe Werte","beschreibung":"Eigenschaft fsVal: Schriftgröße der beiden Halbwert-Beschriftungen oben und unten."},{"name":"Position oben / unten","beschreibung":"Eigenschaften lblTopY/lblBotY: Y-Position der oberen bzw. unteren Wertbeschriftung (0 bis 240), damit sie nicht an den Bögen kleben."},{"name":"Position Mitte (Y)","beschreibung":"Eigenschaft valCY: Feinjustierung der senkrechten Lage von Mittelwert und Untertitel; leer = automatisch."},{"name":"Live (kein Feld)","beschreibung":"Beide Hälften und der Mittelwert aktualisieren sich bei jeder Wertänderung; die Füllung läuft über die Bogenlänge weich nach, die runde Max-Spitze wird als aufgesetzter Punkt an der wachsenden Kante gezeichnet."}],"hinweis":"Der Kreis bleibt durch quadratischen viewBox und xMidYMid meet in jeder Kachelform rund statt zu einer Ellipse gezogen. Beide Hälften starten bei 9 Uhr an ihrer Min-Basis; ist ddCap auf gerade gestellt und stehen beide auf Max, schließen sie zum sauberen Vollkreis.","groesse":[220,200],"demo":{"varId":900004,"varId2":900022,"varId3":900019,"topMin":0,"topMax":100,"botMin":0,"botMax":100,"ddTop":"ok","ddBot":"info","sub":"Durchsatz"}},
    "gauge": {"titel":"Gauge","zweck":"Rundinstrument auf ECharts-Basis fuer einen numerischen Wert zwischen Min und Max. Vier Bauformen vom klassischen Bogen bis zum Donut-Ring, Farbe wahlweise fest, nach Schwellen abgestuft oder aus den Profil-Assoziationen.","funktionen":[{"name":"Wert & Format (gemeinsam)","beschreibung":"Faktor/Skalierung (z. B. 0.001 = W nach kW, skaliert Wert UND Skala), Tausendertrennung, grosse Zahlen kuerzen (k/M/Mrd) und Nachkommastellen wirken auf die Wertanzeige. Die Einheit stellt das eigene Feld 'Einheit' (gvUnit) ein."},{"name":"Variable","beschreibung":"Angezeigter Wert; nicht numerische Werte werden als 0 behandelt."},{"name":"Min / Max","beschreibung":"Skalenanfang und -ende (Vorgabe 0 und 100); daraus ergeben sich Zeigerstellung und die Lage der Farbzonen."},{"name":"Stil","beschreibung":"Klassisch (225 bis -45 Grad), Halb-Gauge (180 bis 0), Donut-Ring (Vollkreis 90 bis -270) oder Halb-Donut. Ein Zeiger erscheint NUR bei Farbe = Abstufung mit Klassisch oder Halb-Gauge; sonst zeichnet das Widget einen gefuellten Fortschrittsbogen ohne Zeiger."},{"name":"Farbe","beschreibung":"Skin-Farbe (Akzent, OK, Warnung, Kritisch, Info, Warm, Neutral ...), Abstufung (Zonen gruen/warm/rot entlang des Bogens) oder Assoziation (Farbe aus der Variablen-Assoziation des Profils)."},{"name":"Gruen bis / Gelb bis","beschreibung":"Nur bei Farbe = Abstufung sichtbar: die beiden Zonenschwellen (t1, t2; mittlere Zone in der Skin-Farbe Warm). Ohne Angabe 60 % und 85 % des Wertebereichs."},{"name":"Teilstriche","beschreibung":"Blendet Skalenstriche, Unterteilung (4 Abschnitte) und Achsenbeschriftung gemeinsam ein (gticks)."},{"name":"Mittelknopf","beschreibung":"Zeichnet den Ankerpunkt in der Mitte (gknob)."},{"name":"Winkel Grad (Start/Ende)","beschreibung":"gstart/gend ueberschreiben die zum Stil gehoerenden Bogenwinkel; beide Felder muessen gefuellt sein."},{"name":"Wertanzeige - Anzeigen","beschreibung":"gvShow: blendet den Zahlenwert in der Mitte aus, wenn nur der Bogen gewuenscht ist."},{"name":"Wertanzeige - Schrift / Gewicht / Stil / Groesse","beschreibung":"Schriftfamilie (gvff, Vorgabe Mono), Gewicht 300 bis 800 (gvfwt), kursiv (gvsty) und feste Pixelgroesse (gvsz) fuer die Zahl."},{"name":"Wertanzeige - Einheit","beschreibung":"gvUnit: Freitext, der hinter die Zahl gehaengt wird und die Profil-Einheit ersetzt (z. B. ' %')."},{"name":"Label","beschreibung":"Wird als Titel im Instrument unterhalb des Werts gezeichnet, nicht als Kachelueberschrift; ohne Label entfaellt der Titel."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Kachel-Eigenschaften; die Schriftgroesse der Kachel wirkt als Basis fuer Titel und Achsenbeschriftung."},{"name":"Interaktion","beschreibung":"Klick oder Lang-Druck oeffnet Seite oder Popup, dazu 'Popup schliessen' und Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge."},{"name":"Live-Aktualisierung","beschreibung":"Jeder neue Wert setzt die ECharts-Serie neu; der Zeiger bzw. der gefuellte Bogen wandert animiert."}],"hinweis":"Braucht die ECharts-Bibliothek der Ansicht; ohne sie bleibt die Kachel leer. Die Kachel hat kein Format-Feld - die Zahl wird ueber Nachkommastellen und das Einheit-Feld gesteuert. Farbe = Assoziation setzt ein Profil mit Assoziationen voraus, sonst faellt die Farbe auf den Akzent zurueck. Kleiner als etwa 120x110 px wird die Beschriftung unleserlich.","groesse":[210,190],"demo":{"label":"Zisterne","varId":41522,"min":0,"max":100,"gstyle":"ring","gcolor":"accent","gvUnit":" %","dec":0}},
    "gaugepro": {"titel":"Gauge+","zweck":"Dasselbe Rundinstrument wie Gauge, nur mit Grenzwert-Abstufung (gruen/warm/rot) als Voreinstellung. Gedacht fuer Messwerte, bei denen die Zone wichtiger ist als der Zahlenwert.","funktionen":[{"name":"Wert & Format (gemeinsam)","beschreibung":"Wie bei Gauge: Faktor/Skalierung, Tausendertrennung, grosse Zahlen kuerzen und Nachkommastellen wirken auf die Wertanzeige; Einheit ueber 'Einheit' (gvUnit)."},{"name":"Variable","beschreibung":"Angezeigter Messwert."},{"name":"Min / Max","beschreibung":"Skalenanfang und -ende; bestimmen zugleich die Lage der Farbzonen."},{"name":"Stil","beschreibung":"Klassisch, Halb-Gauge, Donut-Ring oder Halb-Donut - identisch zu Gauge."},{"name":"Farbe","beschreibung":"Vorgabe Abstufung; alternativ eine feste Skin-Farbe oder Assoziation. Bei Abstufung und Zeigerstil (Klassisch/Halb-Gauge) werden die Zonen entlang des Bogens eingefaerbt, der Zeiger zeigt den Wert."},{"name":"Gruen bis / Gelb bis","beschreibung":"Die beiden Zonenschwellen (t1, t2); ohne Angabe 60 % und 85 % des Bereichs. Die mittlere Zone nutzt die Skin-Farbe Warm."},{"name":"Teilstriche / Mittelknopf","beschreibung":"Skalenstriche mit Beschriftung (gticks) bzw. Ankerpunkt in der Mitte (gknob) ein- und ausblenden."},{"name":"Winkel Grad (Start/Ende)","beschreibung":"Eigene Bogenwinkel (gstart/gend) statt der Stilvorgabe; beide Felder muessen gefuellt sein."},{"name":"Wertanzeige","beschreibung":"Anzeigen ja/nein (gvShow) sowie Schrift (gvff), Gewicht (gvfwt), Stil (gvsty), Groesse (gvsz) und Einheit (gvUnit) der Zahl in der Mitte."},{"name":"Label","beschreibung":"Titel innerhalb des Instruments unter dem Wert."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Kachel-Eigenschaften."},{"name":"Interaktion","beschreibung":"Klick oder Lang-Druck oeffnet Seite oder Popup, dazu 'Popup schliessen' und Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge."},{"name":"Live-Aktualisierung","beschreibung":"Wertwechsel aktualisiert die Serie direkt; die Zone unter dem Zeiger ergibt sich aus den Schwellen."}],"hinweis":"Technisch identisch mit Gauge (dieselbe Zeichenroutine setGauge, dieselben Eigenschaftsnamen) - der einzige Unterschied ist der vorbelegte Farbmodus Abstufung. Wer eine feste Farbe waehlt, bekommt exakt ein Gauge. Bei Abstufung mit Ring- oder Halb-Donut-Stil entfaellt der Zeiger, der gefuellte Bogen zeigt dann die Zonenfarbe des aktuellen Werts. Braucht wie Gauge die ECharts-Bibliothek.","groesse":[220,200],"demo":{"label":"Aussentemperatur","varId":26109,"min":-10,"max":40,"gstyle":"classic","gcolor":"graded","t1":24,"t2":30,"gticks":true,"gknob":true,"gvUnit":" °C","dec":1}},
    "html": {"titel":"HTML","zweck":"Bindet fertiges HTML ein - entweder den Inhalt einer IPS-HTMLBox-Variablen oder selbst geschriebenen Code. Der Inhalt wird bevorzugt in ein Shadow DOM gelegt, bleibt dadurch transparent und kann die uebrige Seite nicht mit eigenen Styles stoeren.","funktionen":[{"name":"Quelle","beschreibung":"Variable (IPS-HTML) laedt den Inhalt ueber die API aus einer String-/HTMLBox-Variablen; Eigener Code blendet stattdessen ein Textfeld ein und die Variablen-Zeile verschwindet."},{"name":"Variable","beschreibung":"Nur bei Quelle = Variable: die HTMLBox-Variable, deren Inhalt gezeigt wird. Ohne Variable bleibt die Kachel leer."},{"name":"HTML","beschreibung":"Nur bei Quelle = Eigener Code: mehrzeiliges Eingabefeld fuer das Markup, wird bei jeder Eingabe sofort uebernommen."},{"name":"Rendering","beschreibung":"Auto (enthaelt der Code ein script-Tag, wird ein iframe genommen, sonst Shadow DOM), Transparent (Shadow, kein JavaScript) oder iframe (JavaScript laeuft, Hintergrund kann weiss wirken)."},{"name":"Skin anwenden","beschreibung":"Setzt die Schriftfamilie des Skins durch und ersetzt Textfarben, die zum Theme nicht passen (dunkel auf dunkel bzw. hell auf hell), durch die Standard-Textfarbe. Wirkt in beiden Modi (im iframe ueber ein eingefuegtes style-Element)."},{"name":"Basis-URL","beschreibung":"Aufloesungspunkt fuer relative Pfade im HTML (z. B. ./preview/...). Leer bedeutet Server-Wurzel. Im iframe-Modus wird sie als base-Tag gesetzt; im Shadow-Modus werden src, href, poster, data-src, srcset und url() in Styles auf absolute Adressen umgeschrieben (Shadow DOM ignoriert base)."},{"name":"Skalierung","beschreibung":"Original/Zoom, Breite einpassen oder Ganz einpassen. Beim Einpassen wird der Inhalt so verkleinert, dass er in die Kachel passt; die Skalierung wird auch beim Groessenaendern der Kachel nachgezogen."},{"name":"Zoom %","beschreibung":"Nur bei Skalierung = Original: feste Vergroesserung zwischen 10 und 400 Prozent."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Kachel-Eigenschaften; der HTML-Container selbst ist transparent und scrollt bei Ueberlaenge."},{"name":"Interaktion","beschreibung":"Klick oder Lang-Druck oeffnet Seite oder Popup, dazu 'Popup schliessen' und Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge."},{"name":"Live-Aktualisierung","beschreibung":"Der Inhalt wird beim Aufbau der Seite geladen, bei jeder Aenderung der gebundenen Variablen neu geholt und zusaetzlich alle 60 Sekunden aufgefrischt. Bei Quelle = Eigener Code entfaellt beides."}],"hinweis":"Enthaelt das HTML JavaScript, wird zwingend ein iframe verwendet - dort greifen Transparenz und Skin-Anpassung nur eingeschraenkt, und der Inhalt kann mit weissem Hintergrund erscheinen. Relative Bildpfade aus IPS-Modulen brauchen meist keine Basis-URL. Sehr grosse HTMLBoxen kosten Rechenzeit, weil beim Skin-Abgleich viele Elemente geprueft werden.","groesse":[400,250],"demo":{"label":"Vorhersage","htmlSrc":"var","varId":16520,"htmlMode":"auto","htmlSkin":true,"htmlFit":"width"}},
    "icon": {"titel":"Icon","zweck":"Zeigt ein einzelnes Symbol formatfuellend an. Ohne Variable ein reines Gestaltungselement, mit Variable ein Zustandsanzeiger, dessen Symbol und Farbe sich mitaendern.","funktionen":[{"name":"Variable","beschreibung":"Optional (gemeinsames Feld). Nur mit gebundener Variable koennen adaptives Icon und Assoziationsfarben wirken; ein Wert wird nicht als Text ausgegeben."},{"name":"Icon (Fallback)","beschreibung":"Auswahl des Symbols ueber die Icon-Palette (gemeinsames Feld). Ohne Auswahl wird eine Gluehbirne (bulb) gezeichnet."},{"name":"Icon-Farbe","beschreibung":"Skin-Farbfelder; setzt --wicon fuer die Kachel und folgt damit dem Theme. Die Zeile erscheint erst, wenn ein Icon gewaehlt ist."},{"name":"Assoziationen","beschreibung":"Erscheint bei gebundener Variable mit Profil-Assoziationen: Schalter 'Icons & Farben nutzen' plus je Zustand ein eigenes Icon und eine Skin-Farbe; im Betrieb wird das passende Symbol eingesetzt und eingefaerbt."},{"name":"Adaptives Icon","beschreibung":"Nicht als Feld sichtbar: Symbole aus der Gruppe 'adaptiv' zeichnen sich abhaengig vom Variablenwert - Fuellstand/Prozent (z. B. bulb, cistern, blinds, battery, valve, tank, radiator) oder Zustand (z. B. pump, window, door, lock, motion)."},{"name":"Label","beschreibung":"Wird beim Icon-Widget nicht gezeichnet; es dient nur als Bezeichnung im Editor und als Grundlage fuer den automatischen Namen beim Verschieben in eine Laufzeile."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Kachel-Eigenschaften; fuer ein freistehendes Symbol ueblicherweise Rahmen aus und Hintergrund transparent."},{"name":"Interaktion","beschreibung":"Klick oder Lang-Druck oeffnet Seite oder Popup, dazu 'Popup schliessen' und Skript-ID bei Klick - damit wird aus dem Icon eine Schaltflaeche ohne Rahmen."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge - haeufig genutzt, um ein Warnsymbol nur im Fehlerfall zu zeigen."},{"name":"Live-Aktualisierung","beschreibung":"Bei Wertwechsel wird ein adaptives Symbol neu gezeichnet und die Assoziationsfarbe neu gesetzt; ohne diese beiden Faelle bleibt die Darstellung statisch."}],"hinweis":"Das Widget hat keine eigenen Eigenschaften - alles kommt aus den gemeinsamen Feldern. Das Symbol fuellt die Kachel mit 10 Prozent Innenabstand; die Proportion folgt der Kachel, ein sehr breites Rechteck laesst viel Leerraum. Ein statisches Symbol reagiert auch bei gebundener Variable nicht - dafuer ein adaptives Icon waehlen oder Assoziationen einschalten.","groesse":[130,130],"demo":{"label":"Lesezimmer","icon":"bulb","varId":13239,"iconColor":"warn","bgT":1,"frame":false}},
    "image": {"titel":"Bild","zweck":"Zeigt ein Bild aus einem IP-Symcon-Media-Objekt, von einer festen URL oder von einer URL, die in einer String-Variablen steht.","funktionen":[{"name":"Quelle","beschreibung":"Media-Objekt (ueber die interne Media-API der Ansicht), Feste URL oder URL aus Variable. Vorgabe ist Media-Objekt."},{"name":"Media-ID","beschreibung":"Steht im oberen, gemeinsamen Teil der Einstellungen (beim Bild-Widget anstelle der Variablen-Zeile). Bei Quelle = Media-Objekt wird daraus ?api=media&id=... geladen."},{"name":"URL","beschreibung":"Bei Quelle = Feste URL: vollstaendige Adresse des Bildes."},{"name":"Variable","beschreibung":"Bei Quelle = URL aus Variable: eigenes Feld mit Auswahlknopf ('waehlen') fuer die String-Variable, deren Inhalt als Bildadresse verwendet wird."},{"name":"Anpassung","beschreibung":"objFit: Einpassen (contain, ganzes Bild sichtbar), Fuellen (cover, Kachel voll, Raender beschnitten) oder Strecken (fill, Seitenverhaeltnis wird verzerrt). Vorgabe ist Einpassen."},{"name":"Label","beschreibung":"Wird nicht gezeichnet, aber als alt-Text des Bildes gesetzt."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Kachel-Eigenschaften; fuer randlose Bilder Rahmen aus und Hintergrund transparent waehlen. Die Typografie bleibt ohne sichtbare Wirkung."},{"name":"Interaktion","beschreibung":"Klick oder Lang-Druck oeffnet Seite oder Popup (z. B. dasselbe Bild gross), dazu 'Popup schliessen' und Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Einblend-Animation, Z-Reihenfolge."},{"name":"Live-Aktualisierung","beschreibung":"Nur bei Quelle = URL aus Variable: aendert sich der Variablenwert, wird die Bildadresse sofort ausgetauscht. Media-Objekt und feste URL werden nicht selbsttaetig neu geladen."}],"hinweis":"Ein Media-Objekt wird ohne Cache-Umgehung geladen - ein regelmaessig ueberschriebenes Kamerabild bleibt im Browser-Cache stehen. Fuer Livebilder und Streams das Kamera-Widget verwenden. Bei fester URL muss die Quelle vom Browser des Panels aus erreichbar sein; ueber HTTPS ausgelieferte Ansichten laden keine http-Bilder.","groesse":[240,240],"demo":{"label":"Mond","imgSrc":"media","mediaId":49869,"objFit":"contain","bgT":1}},
    "infolist": {"titel":"Info-Liste","zweck":"Zeigt mehrere Geraete oder Zustaende untereinander als Zeilenliste, jede Zeile mit Icon (optional eingefaerbt), Name, Zusatztext und rechts entweder einem Wert oder einer farbigen Status-Pille. Gedacht als kompakte Sammelanzeige, damit nicht fuer jede Kleinigkeit eine eigene Kachel noetig ist.","funktionen":[{"name":"Zeile: Icon (Listen-Editor, Spalte \"Icon\")","beschreibung":"Icon fuer das Kaestchen links, ueber die Icon-Auswahl gesetzt, z. B. washer, dryer, car, bulb, temperature, bolt. Leer bedeutet 'sensor'."},{"name":"Zeile: Farbe (Icon)","beschreibung":"Skin-/Farbwahl fuer das Icon-Kaestchen der Zeile. Faerbt Icon und Kaestchenhintergrund; leer = neutrale Flaechenfarbe."},{"name":"Zeile: Name (Spalte \"Name\")","beschreibung":"Erste Textzeile, der Bezeichner des Eintrags."},{"name":"Zeile: Zusatz (Spalte \"Zusatz\")","beschreibung":"Kleine zweite Zeile unter dem Namen, gedaempft dargestellt. Leer lassen blendet sie aus."},{"name":"Zeile: Wert (Spalte \"Wert\")","beschreibung":"Rechts stehender Wert in Zifferschrift. Wird nur gezeigt, wenn KEINE Pille gesetzt ist."},{"name":"Zeile: Dez / Einh (Spalten \"Dez\"/\"Einh\")","beschreibung":"Formatieren den Live-Wert (VarID) je Zeile: feste Nachkommastellen und eine angehaengte Einheit. Leer = Profil-Formatierung der Variable."},{"name":"Zeile: Pill (Spalte \"Pill\")","beschreibung":"Text einer Status-Pille rechts (mit Punkt davor). Sobald gefuellt, ersetzt die Pille den Wert der Zeile."},{"name":"Zeile: Status (Pill) (Spalte \"Status\")","beschreibung":"Farbe der Pille: ok (gruen), on (Akzent), off (grau/blass), warn (gelb), crit (rot), warm (orange). Ohne Pill-Text wirkungslos, Vorgabe ok."},{"name":"Zeile: ID (Spalte \"ID\")","beschreibung":"Variablen-ID fuer den Wert der Zeile. Der Wert wird live nachgetragen und laufend aktualisiert (formatierter Profilwert), Nachkommastellen/Einheit aus den Zeilenspalten wirken darauf."},{"name":"Zeile hinzufuegen / entfernen","beschreibung":"Plus-Knopf haengt eine neue Zeile an, Minus-Knopf je Zeile loescht sie. Die Reihenfolge im Editor ist die Reihenfolge in der Anzeige."},{"name":"Label","beschreibung":"Gemeinsame Eigenschaft. Wird von diesem Widget nicht gezeichnet, dient nur der Identifikation im Editor."},{"name":"Farben / Rahmen / Hintergrund","beschreibung":"Gemeinsame Eigenschaften: Text- und Hintergrundfarbe, Rahmen an/aus/Ansicht-Standard, Hintergrund deckend oder transparent."},{"name":"Beschriftung (mehrzeilig)","beschreibung":"Gemeinsame Eigenschaft. Wird angeboten, wirkt hier aber nicht - die Zeilentexte brechen ohnehin um."},{"name":"Typografie","beschreibung":"Gemeinsame Eigenschaften: Schriftart, Gewicht, Stil und Schriftgroesse."},{"name":"Interaktion (Seite/Popup/Skript)","beschreibung":"Gemeinsame Eigenschaften: Klick auf die Liste kann eine Seite oeffnen, ein Popup zeigen/schliessen oder ein IPS-Skript starten. Es wirkt das ganze Widget, nicht die einzelne Zeile."},{"name":"Lang-Druck -> Seite / Popup","beschreibung":"Gemeinsame Eigenschaft: Halten fuer die zweite Aktion; der normale Klick wird dann unterdrueckt."},{"name":"Sichtbarkeit, Animation, Ebene, X/Y/B/H","beschreibung":"Gemeinsame Eigenschaften: variablengesteuertes Ein-/Ausblenden, Einblend-Animation, Stapelreihenfolge, Position und Groesse."}],"hinweis":"Wert und Pille schliessen sich aus: sobald das Feld \"Pill\" gefuellt ist, wird die Spalte \"Wert\" (und damit die VarID der Zeile) nicht mehr angezeigt. Pillen sind statisch, sie folgen keiner Variablen. Es gibt keine Haupt-Variable fuer das Widget - alles haengt an den VarIDs der Zeilen.","groesse":[340,230],"demo":{"label":"Haus","items":[{"icon":"temperature","label":"Aussentemperatur","sub":"Nordseite","vid":26109},{"icon":"bolt","label":"Hausverbrauch","sub":"aktuell","vid":38704},{"icon":"cistern","label":"Zisterne","sub":"Fuellstand","vid":41522},{"icon":"bulb","label":"Lesezimmer","sub":"Deckenlicht","pill":"Ein","state":"on"}]}},
    "kpi": {"titel":"KPI","zweck":"Kennzahl-Kachel mit Icon, Beschriftung, grossem Zahlenwert samt Einheit und einer Zusatzzeile darunter. Die Zusatzzeile ist entweder ein selbst geschriebener Delta-Text oder ein automatisch berechneter Vergleich mit einem frueheren Zeitraum.","funktionen":[{"name":"Variable","beschreibung":"Gemeinsame Eigenschaft: die dargestellte Variable. Der Wert wird live nachgefuehrt (formatierter Profilwert, inkl. Praefix/Suffix aus applyVal)."},{"name":"Einheit","beschreibung":"Kleiner Zusatz hinter der Zahl, z. B. % oder kWh. Wird auch fuer die Absolut-Anzeige des Vergleichs verwendet."},{"name":"Farbe nach Schwelle -> Aktiv","beschreibung":"Schaltet die Zustandsfaerbung des Zahlenwerts ein."},{"name":"Gruen bis / Gelb bis","beschreibung":"Zwei Schwellen: bis zur ersten gruen (OK), bis zur zweiten gelb/warm, darueber rot (kritisch)."},{"name":"Invertieren (Schwellen)","beschreibung":"Dreht die Logik um: kleine Werte werden rot, grosse gruen. Fuer Groessen, bei denen wenig schlecht ist (z. B. Fuellstand)."},{"name":"Delta-Text","beschreibung":"Freier Text der dritten Zeile, z. B. '+6 % ggue. gestern'. Das Feld erscheint nur, solange der Vergleich ausgeschaltet ist."},{"name":"Richtung","beschreibung":"Pfeil und Faerbung des Delta-Textes: auf (gruen, Dreieck hoch), ab (rot, Dreieck runter) oder neutral ohne Pfeil. Erscheint nur ohne aktiven Vergleich."},{"name":"Vergleich (Zeitversatz)","beschreibung":"Ersetzt den Delta-Text durch einen automatisch aus dem Archiv berechneten Vergleich mit einer frueheren Periode; wird direkt nach dem Rendern (mount) berechnet, nicht erst beim naechsten Poll."},{"name":"Zaehlervariable (Verbrauch je Periode)","beschreibung":"Fuer Zaehler: statt des Zaehlerstands wird der Verbrauch der laufenden Periode als Hauptwert gezeigt und mit dem gleichen Zeitfenster der Vorperiode verglichen."},{"name":"Aggregationsstufe / Anzeige / Veraenderung invertieren","beschreibung":"Teil der Vergleichslogik (Route ?api=cmp): Bezugsperiode, Ausgabe als Prozent oder absolute Differenz, sowie Umkehr der Farbe wenn Rueckgang gut ist. Nur Farbe dreht, der Pfeil bleibt richtungstreu."},{"name":"Nachkommastellen / Praefix / Suffix","beschreibung":"Gemeinsame Eigenschaften: feste Dezimalstellen (0 bis 6) und Text vor/hinter dem Wert. Ist Suffix ODER Einheit gesetzt, wird die Profileinheit aus dem Rohwert entfernt; ein Praefix allein bewirkt das nicht."},{"name":"Icon (Fallback) und Icon-Farbe","beschreibung":"Gemeinsame Eigenschaften: Icon im runden Kaestchen links, Farbwahl (Standard/Akzent/OK/Warnung/Kritisch/Info/Neutral) erst nach gesetztem Icon. Adaptive Icons fuellen sich nach dem Variablenwert."},{"name":"Assoziationen (Icons & Farben)","beschreibung":"Gemeinsame Eigenschaft bei Variable mit Profil-Assoziationen: je Zustand eigenes Icon und Skin-Farbe. Ist 'Farbe nach Schwelle' aktiv, gewinnt die Schwellenfarbe."},{"name":"Label, Farben, Rahmen, Hintergrund, Beschriftung, Typografie","beschreibung":"Gemeinsame Eigenschaften. Label ist die kleine Grossbuchstaben-Zeile ueber dem Wert; ein \\n darin erzwingt einen Umbruch."},{"name":"Interaktion, Lang-Druck, Sichtbarkeit, Animation, Ebene, X/Y/B/H","beschreibung":"Gemeinsame Eigenschaften: Seite/Popup/Skript bei Klick, zweite Aktion beim Halten, variablengesteuerte Sichtbarkeit, Einblendung, Geometrie."}],"hinweis":"Der Zeitversatz-Vergleich braucht ein Archiv-Control und Archivdaten der Variablen; ohne Archiv bleibt die Zeile bei '-'. Der Hauptwert folgt dem normalen Poll. Ein Format-Feld gibt es beim KPI nicht, nur Nachkommastellen, Praefix und Suffix.","groesse":[300,120],"demo":{"varId":41522,"label":"Zisterne","unit":"%","icon":"cistern","dir":"up","delta":"+4 % ggue. gestern","colThr":true,"t1":30,"t2":60,"thrInvert":true}},
    "light": {"titel":"Licht","zweck":"Kachel fuer eine Lampe: Name, optionaler Untertitel, grosser Zustandswert und rechts ein senkrechter Fuellbalken mit unsichtbarem Schieberegler fuer die Helligkeit. Die Kachel schaltet beim Antippen oder dimmt am Balken und faerbt sich im eingeschalteten Zustand ein.","funktionen":[{"name":"Variable","beschreibung":"Gemeinsame Eigenschaft: Statuskanal (bool/0-1). Bestimmt den Ein-Zustand und wird per Klick umgeschaltet."},{"name":"Helligkeit","beschreibung":"Zweite Variable (0 bis 100). Erst wenn sie gesetzt ist, erscheint der senkrechte Balken; sein Fuellstand folgt dem Wert, der darueberliegende Regler schreibt beim Ziehen zurueck."},{"name":"Untertitel","beschreibung":"Kleine Zeile unter dem Namen, z. B. der Raum oder das Geschoss."},{"name":"Status anzeigen","beschreibung":"Blendet 'Ein' bzw. 'Aus' in der Fusszeile ein oder aus."},{"name":"Zeit anzeigen","beschreibung":"Blendet 'seit HH:MM' in der Fusszeile ein - den Zeitpunkt der letzten Aenderung der massgeblichen Variablen (Status, sonst Helligkeit). Status und Zeit mit ' · ' getrennt; sind beide aus, verschwindet die Zeile."},{"name":"Balkenbreite (%)","beschreibung":"Breite des Helligkeitsbalkens in Prozent der Kachel (4 bis 60, Vorgabe 20)."},{"name":"Balken-Rundung (px)","beschreibung":"Eckenradius des Balkens (0 bis 999). 0 = eckige Ecken, hoher Wert = Pillenform; leer = vollrund."},{"name":"Klick auf die Kachel","beschreibung":"Mit Statusvariable: schaltet um. Ohne Status, aber mit Helligkeit: setzt auf 100 %, bei bereits 100 % zurueck auf 0 %. Ein Klick auf den Balken schaltet NICHT. Navigationsziel (Seite/Popup/Zurueck) hat Vorrang."},{"name":"Wert- und Zustandsanzeige (automatisch)","beschreibung":"Gerundet 0 % ergibt 'Aus', 100 % 'Ein', dazwischen die Prozentzahl. Ohne Helligkeit nur 'Ein'/'Aus'. Bei Ein faerben sich Icon und Fusszeile im Akzent und der Rahmen wird angehoben."},{"name":"Icon (Fallback)","beschreibung":"Gemeinsame Eigenschaft. Adaptive Icons (bulb, ceilinglamp, spot, floorlamp, candle, ledstrip ...) zeichnen ihren Fuellstand nach der Helligkeit. Eine Icon-Farb-Auswahl gibt es hier nicht - die Farbe kommt aus dem Ein/Aus-Zustand."},{"name":"Format / Nachkommastellen / Praefix / Suffix","beschreibung":"Format wird angeboten, wirkt hier aber nicht: das Widget schreibt seinen Wert selbst ('Ein'/'Aus'/Prozent). Nachkommastellen/Praefix/Suffix gibt es beim Licht nicht."},{"name":"Assoziationen","beschreibung":"Gemeinsame Eigenschaft bei Variable mit Profil-Assoziationen. Beim Licht faerbt sie nur den Wert-Text; das Icon zeichnet das Widget selbst."},{"name":"Label, Farben, Rahmen, Hintergrund, Beschriftung, Typografie","beschreibung":"Gemeinsame Eigenschaften. Label ist der Lampenname; 'Beschriftung mehrzeilig' laesst Name, Untertitel und Fusszeile umbrechen."},{"name":"Interaktion, Lang-Druck, Sichtbarkeit, Animation, Ebene, X/Y/B/H","beschreibung":"Gemeinsame Eigenschaften. Wer schalten UND navigieren will, legt die Navigation auf den Lang-Druck."}],"hinweis":"Schalten funktioniert nur im Bedien-/Run-Modus. Ohne Helligkeitsvariable gibt es keinen Balken und keine Prozentanzeige. Ist eine Status- oder Helligkeitsvariable gebunden, schaltet der Klick - 'Popup schliessen' und 'Skript ID' greifen dann nicht, dafuer Lang-Druck oder Navigationsziel nutzen.","groesse":[320,210],"demo":{"varId":30519,"varId2":13239,"label":"Lesezimmer","sub":"Obergeschoss","icon":"bulb","showState":true,"showSince":true}},
    "line": {"titel":"Linie","zweck":"Reines Gestaltungselement: zeichnet eine gerade Linie in Widget-Groesse, wahlweise mit Pfeilspitzen. Dient zum Trennen von Bereichen oder zum Andeuten von Verbindungen zwischen Kacheln.","funktionen":[{"name":"Richtung","beschreibung":"horizontal (Mitte, links nach rechts), vertikal (Mitte, oben nach unten) oder diagonal (links oben nach rechts unten)."},{"name":"Breite (px)","beschreibung":"Strichstaerke, in halben Schritten einstellbar, Vorgabe 3. Die Linie hat runde Enden."},{"name":"Pfeile: Start","beschreibung":"Setzt eine Pfeilspitze an den Anfang der Linie."},{"name":"Pfeile: Ende","beschreibung":"Setzt eine Pfeilspitze an das Ende der Linie."},{"name":"Farbe","beschreibung":"Gemeinsame Eigenschaft: Farbe von Linie und Pfeilspitzen (Vorgabe #00cdab)."},{"name":"Interaktion (Seite/Popup/Skript)","beschreibung":"Gemeinsame Eigenschaften: auch eine Linie kann angeklickt werden und eine Seite, ein Popup oder ein Skript ausloesen."},{"name":"Lang-Druck -> Seite / Popup","beschreibung":"Gemeinsame Eigenschaft: zweite Aktion beim Halten."},{"name":"Sichtbarkeit, Animation, Ebene, X/Y/B/H","beschreibung":"Gemeinsame Eigenschaften. Die Linie skaliert ohne Seitenverhaeltnis und fuellt das Rechteck immer vollstaendig aus."}],"hinweis":"Das Linien-Widget hat keine Variable, keinen Rahmen, keinen Hintergrund und keine Typografie. Bei diagonaler Richtung verzerrt sich der Winkel mit dem Seitenverhaeltnis des Widgets, weil die Zeichnung nicht proportional skaliert.","groesse":[220,90],"demo":{"ldir":"h","lw":3,"color":"#00cdab","arrowE":true}},
    "marquee": {"titel":"Lauftext","zweck":"Zeigt den Wert einer Variablen als horizontal durchlaufenden Text. Sinnvoll fuer lange Texte, die in einer schmalen Flaeche sonst abgeschnitten wuerden, oder als dezenter Hinweisstreifen.","funktionen":[{"name":"Variable","beschreibung":"Gemeinsame Eigenschaft: die angezeigte Variable. Der Text wird bei jeder Wertaenderung live ausgetauscht, der Lauf selbst laeuft ununterbrochen weiter."},{"name":"Tempo (s/Durchlauf)","beschreibung":"Dauer eines vollstaendigen Durchlaufs in Sekunden, Vorgabe 12. Groessere Werte = langsameres Wandern; 0 oder leer faellt auf 12 zurueck."},{"name":"Praefix","beschreibung":"Gedaempfter Text vor dem Wert, z. B. 'Aktuell: '. Wird sofort in der Vorschau uebernommen."},{"name":"Suffix","beschreibung":"Gedaempfter Text hinter dem Wert, z. B. eine Einheit. Ist ein Suffix gesetzt, entfaellt die automatisch angehaengte Profileinheit; ein Praefix allein bewirkt das nicht."},{"name":"Nachkommastellen","beschreibung":"Gemeinsame Eigenschaft: feste Anzahl Dezimalstellen (0 bis 6) fuer numerische Variablen."},{"name":"Label","beschreibung":"Gemeinsame Eigenschaft, wird von diesem Widget nicht gezeichnet."},{"name":"Farben, Rahmen, Hintergrund","beschreibung":"Gemeinsame Eigenschaften. Der Streifen zeichnet einen eigenen Hintergrund in Flaechenfarbe mit abgerundeten Ecken."},{"name":"Beschriftung (mehrzeilig)","beschreibung":"Gemeinsame Eigenschaft. Wird angeboten, wirkt hier aber nicht - der Lauftext bleibt zwingend einzeilig."},{"name":"Typografie","beschreibung":"Gemeinsame Eigenschaften. Von Haus aus halbfette Ziffernschrift mit gleich breiten Ziffern; Schrift, Gewicht, Stil und Groesse ueberschreiben das."},{"name":"Interaktion, Lang-Druck, Sichtbarkeit, Animation, Ebene, X/Y/B/H","beschreibung":"Gemeinsame Eigenschaften: Klick/Halten fuer Seite, Popup oder Skript, variablengesteuerte Sichtbarkeit, Geometrie."}],"hinweis":"Der Text laeuft von rechts nach links durch und ist zwischendurch komplett ausserhalb des Fensters - bei sehr langsamem Tempo dauert es entsprechend, bis wieder etwas zu sehen ist. Es gibt kein Format-Feld, nur Nachkommastellen mit Praefix/Suffix.","groesse":[300,80],"demo":{"varId":38122,"label":"Wetter","mqSpeed":14,"mqPre":"Aktuell: "}},
    "media": {"titel":"Media","zweck":"Kleine Fernbedienung fuer einen Medienspieler: Titelzeile, ein Wiedergabe-/Pause-Knopf und ein Lautstaerkeregler. Alle drei Teile haengen an je einer eigenen Variablen.","funktionen":[{"name":"Variable","beschreibung":"Gemeinsame Eigenschaft: liefert den Text der Titelzeile (Interpret/Titel oder Sender). Wird live aktualisiert und bei Platzmangel mit Auslassungspunkten gekuerzt."},{"name":"Zustand (Variable 2)","beschreibung":"Zweite Variable (bool/0-1): steuert das Symbol im Knopf - laeuft (Pause-Symbol) oder gestoppt (Play-Symbol). Ein Klick schreibt den umgekehrten Wert zurueck."},{"name":"Lautstaerke (Variable 3)","beschreibung":"Dritte Variable (0 bis 100): Position des Schiebereglers. Loslassen schreibt den neuen Wert. Solange der Regler den Fokus hat, wird er nicht von aussen ueberschrieben."},{"name":"Wiedergabe/Pause (Klick)","beschreibung":"Nicht als Feld sichtbar: der Knopf wirkt nur, wenn die Zustands-Variable gesetzt ist, und nur im Bedien-Modus."},{"name":"Label","beschreibung":"Gemeinsame Eigenschaft, wird nicht gezeichnet - die Titelzeile kommt ausschliesslich aus der Variablen."},{"name":"Farben, Rahmen, Hintergrund, Beschriftung","beschreibung":"Gemeinsame Eigenschaften. Bei aktiver mehrzeiliger Beschriftung darf die Titelzeile umbrechen."},{"name":"Typografie","beschreibung":"Gemeinsame Eigenschaften fuer die Titelzeile."},{"name":"Interaktion, Lang-Druck, Sichtbarkeit, Animation, Ebene, X/Y/B/H","beschreibung":"Gemeinsame Eigenschaften. Achtung: Seite/Popup/Skript werden VOR dem Knopf ausgewertet - ist eines gesetzt, loest auch ein Klick auf den Wiedergabe-Knopf nur die Navigation aus. Der Lautstaerkeregler bleibt unberuehrt."}],"hinweis":"Das Widget hat keine eigenen Einstellungen ausser den drei Variablen - ohne Variable 2 bleibt der Knopf wirkungslos, ohne Variable 3 schreibt der Regler nichts. Bedienung nur im Bedien-/Run-Modus. Es gibt kein Cover-Bild und keine Vor-/Zurueck-Tasten.","groesse":[300,140],"demo":{"varId":38122,"varId2":30519,"varId3":13239,"label":"Media"}},
    "meterlist": {"titel":"Metrik-Liste","zweck":"Zeigt mehrere Messgroessen als Kachelraster (zwei Spalten) mit Name, Zusatz, Zahlenwert samt Einheit und einem schmalen Fortschrittsbalken. Gedacht fuer Uebersichten wie Systemlast, Fuellstaende oder Auslastungen auf engem Raum.","funktionen":[{"name":"Metrik: Name (Listen-Editor, Spalte \"Name\")","beschreibung":"Bezeichnung oben links in der Metrik-Kachel."},{"name":"Metrik: Zusatz (Spalte \"Zusatz\")","beschreibung":"Kleiner, blasser Text rechts oben in derselben Zeile - etwa Quelle oder Kontext."},{"name":"Metrik: Wert (Spalte \"Wert\")","beschreibung":"Angezeigter Zahlenwert. Ohne VarID fester Text, mit VarID nur Startwert bis der erste Live-Wert eintrifft. Leer ergibt einen Gedankenstrich."},{"name":"Metrik: Dez (Spalte \"Dez\")","beschreibung":"Optionale Nachkommastellen fuer den Live-Wert je Zeile; leer = Profil-Formatierung. Die Einheit steht in der eigenen Spalte."},{"name":"Metrik: Einh (Spalte \"Einh\")","beschreibung":"Kleiner gedaempfter Zusatz hinter dem Wert, z. B. % oder W."},{"name":"Metrik: % (Spalte \"%\")","beschreibung":"Fuellstand des Balkens in Prozent (0 bis 100). Ohne VarID der feste Balkenwert."},{"name":"Metrik: ID (Spalte \"ID\")","beschreibung":"Variablen-ID. Der Wert wird live in die Zahl geschrieben (formatierter Profilwert) und derselbe Rohwert steuert zugleich die Balkenbreite, begrenzt auf 0 bis 100 %."},{"name":"Metrik hinzufuegen / entfernen","beschreibung":"Plus haengt eine Kachel an, Minus je Zeile loescht sie. Die Kacheln fuellen das Raster in Eingabereihenfolge, zwei je Reihe."},{"name":"Nachkommastellen","beschreibung":"Gemeinsame Eigenschaft, wird angeboten, greift hier aber nicht - das Widget hat keine Hauptvariable, die Zeilenwerte kommen aus den Zeilenspalten."},{"name":"Label","beschreibung":"Gemeinsame Eigenschaft, wird nicht gezeichnet."},{"name":"Farben, Rahmen, Hintergrund, Typografie","beschreibung":"Gemeinsame Eigenschaften fuer Rahmen des Widgets und Textdarstellung der Kacheln."},{"name":"Beschriftung (mehrzeilig)","beschreibung":"Gemeinsame Eigenschaft. Wird angeboten, wirkt hier aber nicht - die Kacheltexte brechen ohnehin um."},{"name":"Interaktion, Lang-Druck, Sichtbarkeit, Animation, Ebene, X/Y/B/H","beschreibung":"Gemeinsame Eigenschaften: Klick/Halten fuer Seite, Popup oder Skript, variablengesteuerte Sichtbarkeit, Stapelreihenfolge, Geometrie. Es wirkt das ganze Widget, nicht die einzelne Kachel."}],"hinweis":"Der Balken interpretiert den Rohwert der Variablen unmittelbar als Prozent. Fuer Groessen ausserhalb 0 bis 100 (z. B. Leistung in W) steht der Balken deshalb dauerhaft am Anschlag - dort auf eine Prozent-Variable binden oder die VarID weglassen und nur den festen Prozentwert setzen.","groesse":[380,230],"demo":{"label":"Werte","items":[{"label":"Zisterne","sub":"Fuellstand","val":"22","unit":"%","pct":22,"vid":41522},{"label":"CPU","sub":"jottaclient","val":"28","unit":"%","pct":28,"vid":11964},{"label":"HDD","sub":"belegt","val":"14","unit":"%","pct":14,"vid":10825},{"label":"Luftfeuchte","sub":"Kueche","val":"60","unit":"%","pct":60,"vid":10649}]}},
    "msglog": {"titel":"Meldungen","zweck":"Zeigt Meldungen aus zwei Quellen: dem IP-Symcon-Logfile (DEBUG ausgefiltert) ODER den Servicemeldungen einer Homematic-CCU (per XML-RPC + ReGaHss, es genuegt die CCU-IP). Kategorien per Pille filterbar; Ansicht als Liste oder als Kompakt-Zaehler mit einer grossen Gesamtzahl der markierten Kategorien.","funktionen":[{"name":"Typ (Quelle)","beschreibung":"Symcon-Log oder Homematic-CCU. Bei Homematic wird die CCU-IP eingetragen; Geraetenamen werden aufgeloest."},{"name":"CCU-IP","beschreibung":"Nur bei Quelle Homematic: IP der CCU (z. B. 10.10.20.240). Erst mit gesetzter IP ist die Homematic-Quelle und der Kopf-Umschalter ueberhaupt moeglich."},{"name":"Bestaetigen erlauben (nur Homematic)","beschreibung":"Blendet je Meldung einen Haken ein, der die Servicemeldung direkt auf der CCU quittiert (ReGaHss AlReceipt). Danach wird die Liste neu geladen."},{"name":"Interfaces (HM / IP)","beschreibung":"Getrennte Auswahl der Funk-Interfaces BidCos-RF (klassisch HM) und HmIP-RF. Als Builder-Standard (beide an) und im Betrieb per Chip (HM / IP) im Kopf live an-/abwaehlbar. Nie beide aus (waere immer leer)."},{"name":"Quelle live umschalten (kein Feld)","beschreibung":"Ist eine CCU-IP hinterlegt, erscheint in der Listen-Ansicht im Kopf ein kleiner Umschalter Symcon/HM. Ein Tipp wechselt die Quelle im Betrieb (je Geraet gespeichert, localStorage lvmsgsrc_<ID>). Im Kompaktmodus ausgeblendet."},{"name":"Darstellung","beschreibung":"Liste (Zeilen mit Farbpunkt, Kategorie, Zeit, Quelle und Text) oder Kompakt: EINE grosse Zahl = Anzahl der offenen gefilterten Meldungen der aktiven Quelle, gefaerbt nach hoechster Severity oder nach Farbgrenzen. Kompakt hat keine Pillen/Umschalter und skaliert mit der Kachelgroesse."},{"name":"Farbgrenzen (Anzahl) - nur Kompakt","beschreibung":"Zwei Schwellen (gruen <= / gelb <=) teilen die Anzahl in drei Bereiche: 0..gruen, ..gelb, darueber. Leer = Farbe nach der hoechsten vorhandenen Severity."},{"name":"Gruen-/Gelb-/Rot-Bereich - nur Kompakt","beschreibung":"Je Bereich lassen sich Schriftfarbe UND Kachelfarbe frei aus den Skin-Farben waehlen (kein RGB-Picker). Kachel Auto = kein Hintergrund. So faerben sich Zahl und Kachel nach der Menge unbestaetigter Meldungen."},{"name":"Kachel-Hintergrund (gedaempft) - nur Kompakt","beschreibung":"Schalter: an = Kachelfarbe abgeschwaecht als Tint (color-mix mit Surface), aus = Vollfarbe."},{"name":"Bestaetigen (nur Symcon) - Bestaetigt-bis-Variable","beschreibung":"Das Symcon-Log ist append-only. Eine gebundene String-Variable (w.ackVid) haelt den Bestaetigt-Status als JSON {cutoff, keys}: cutoff = Stichzeitpunkt (Unix-Zeit), keys = einzeln ausgeblendete Meldungen (Schluessel aus Zeit+Text). Bestaetigen setzt cutoff auf jetzt; das X je Zeile blendet einzelne aus; Verlauf zeigt Bestaetigte ausgegraut mit Zurueckhol-Pfeil. Die Variable liegt auf dem Server (geraeteuebergreifend). Reine Integer-Variablen werden weiter als nur cutoff akzeptiert (abwaertskompatibel). Kompakt: kleiner Haken oben rechts bestaetigt alles."},{"name":"Severity-Filter (Standard)","beschreibung":"Sechs Kaestchen ERROR, WARNING, CUSTOM, NOTIFY, MESSAGE, SUCCESS. Nur angehakte Kategorien werden geholt/gezaehlt. Ohne eigene Einstellung sind ERROR, WARNING und CUSTOM aktiv. Homematic-Typen werden auf diese Schweren gemappt."},{"name":"Pillen im Betrieb (kein Feld)","beschreibung":"Nur in der Listen-Ansicht: Ein Tipp auf eine farbige Kategorie-Pille schaltet diese Kategorie um. Der Zustand wird je Geraet im Browser gespeichert (localStorage lvmsg_<ID>) und ueberlagert dort den Builder-Filter. Im Kompaktmodus sind die Pillen ausgeblendet."},{"name":"Neuen folgen","beschreibung":"Kaestchen (Vorgabe an): scrollt bei neuen Meldungen ans Ende der Liste - aber nur, wenn man bereits ganz unten steht (nur Symcon-Liste)."},{"name":"Max. Eintraege","beschreibung":"Wie viele Meldungen gehalten/gezaehlt werden, 1 bis 500 (Vorgabe 25). Der Server durchsucht das Log rueckwaerts und liefert die letzten Treffer der aktiven Kategorien."},{"name":"Aktualisierung (Sek.)","beschreibung":"Eigener Abrufabstand dieses Widgets, 1 bis 600. Leer = globaler Wert (Vorgabe 15 s). Ein 1-Sekunden-Grundtakt versorgt auch Widgets in Laufzeilen und Popups."},{"name":"Zustandsfaerbung (kein Feld)","beschreibung":"Punkt, Kategoriekuerzel und Pillenrahmen sind je Schwere eingefaerbt: ERROR rot, WARNING gelb, CUSTOM violett, NOTIFY blau, MESSAGE grau, SUCCESS gruen."}],"hinweis":"Findet der Server keine passenden Zeilen, steht Keine Meldungen da; CCU nicht erreichbar bzw. Nicht lesbar nur, wenn die Abfrage selbst scheitert. Sind alle Pillen aus, steht Keine Kategorie aktiv. Der Pillen-/Quellen-Zustand aus dem Betrieb wird pro Browser gespeichert und ueberstimmt den Builder-Standard. Das allgemeine Feld Variable oben hat fuer dieses Widget keine Wirkung.","groesse":[520,270],"demo":{"label":"Meldungen","max":20,"sev":{"ERROR":1,"WARNING":1,"CUSTOM":1,"NOTIFY":1,"MESSAGE":1,"SUCCESS":1},"refreshSec":15}},
    "objinfo": {"titel":"Objekt-Info","zweck":"Zeigt eine Metainformation eines beliebigen IP-Symcon-Objekts statt seines Werts - etwa wann eine Variable zuletzt aktualisiert wurde oder wann ein Ereignis das naechste Mal laeuft.","funktionen":[{"name":"Objekt-ID","beschreibung":"ID des auszuwertenden Objekts. Der Knopf waehlen bindet nur Variablen aus dem Objektbaum. Fuer Ereignisse, Skripte oder Instanzen die ID von Hand eintragen."},{"name":"Feld","beschreibung":"Was angezeigt wird: Letzte Aktualisierung (VariableUpdated), Letzte Aenderung (VariableChanged), Naechster Lauf (NextRun eines Ereignisses), Letzter Lauf (LastRun eines Ereignisses) oder Objektname."},{"name":"Label","beschreibung":"Obere, gedaempfte Zeile. Bleibt das Label leer, setzt das Widget dort automatisch den Objektnamen aus der Abfrage ein."},{"name":"Zeitdarstellung (kein Feld)","beschreibung":"Zeitstempel werden als deutsches Datum mit Uhrzeit ausgegeben; fehlt der Wert oder ist er 0, steht dort ein Gedankenstrich."},{"name":"Aktualisierung (kein Feld)","beschreibung":"Der Wert wird beim Zeichnen der Seite geholt (auch beim Oeffnen eines Popups und beim Seitenwechsel) und danach nachgefuehrt. Das Widget haengt an keiner Live-Variablen."}],"hinweis":"Das Widget hat bewusst kein Feld Variable - die Auswertung laeuft ueber die Objekt-ID. Naechster/Letzter Lauf liefern nur bei Ereignis-Objekten etwas, Letzte Aktualisierung/Aenderung nur bei Variablen; sonst bleibt ein Gedankenstrich. Der Knopf waehlen hilft nur bei Variablen; Ereignis- und Skript-IDs muessen getippt werden.","groesse":[280,90],"demo":{"objId":26109,"field":"updated","label":"Außentemperatur"}},
    "raincard": {"titel":"Regenmenge","zweck":"Stellt eine Niederschlagsmenge als Messzylinder dar: die Fuellhoehe folgt dem Wert in mm im Verhaeltnis zum eingestellten Skalen-Maximum, daneben stehen Zahlenwert und wahlweise die aktuelle Regenrate.","funktionen":[{"name":"Menge mm (Var)","beschreibung":"Variable mit der Niederschlagsmenge in Millimetern (varId). Bestimmt Zahlenwert und Fuellhoehe des Zylinders. Ein allgemeines Feld Variable gibt es bei diesem Widget nicht - dieses Feld ersetzt es."},{"name":"Rate mm/h (Var)","beschreibung":"Optionale Variable mit der aktuellen Regenrate (varId2). Ist sie gesetzt, zeigt die untere Zeile x mm/h statt des Labels."},{"name":"Skala max (mm)","beschreibung":"Wert, bei dem der Zylinder voll ist (Vorgabe 30 mm, Minimum 1). Die Fuellung wird auf 0 bis 100 % begrenzt, groessere Mengen laufen nicht ueber."},{"name":"Tropfen-Animation","beschreibung":"Im Zylinder fallen tropfenfoermige Symbole, sobald die Raten-Variable groesser als 0 ist; die Fallgeschwindigkeit folgt der Rate (mehr mm/h = schneller). Per Schalter abschaltbar. Bei Rate 0, ohne Raten-Variable oder abgeschaltet sind die Tropfen unsichtbar."},{"name":"Nachkommastellen (dec)","beschreibung":"Feste Stellenzahl fuer Menge und Rate. Ohne Angabe wird auf eine Nachkommastelle gerundet; Dezimaltrennzeichen ist stets das Komma."},{"name":"Label","beschreibung":"Untertitel unter dem Zahlenwert - sichtbar nur, solange keine Raten-Variable eingetragen ist (Vorgabe Regen heute)."},{"name":"Skalenstriche (kein Feld)","beschreibung":"Drei feste Teilstriche rechts am Zylinder als Viertelmarken; nicht beschriftet, nicht konfigurierbar."},{"name":"Live-Aktualisierung (kein Feld)","beschreibung":"Aendert sich eine der beiden Variablen, werden Fuellstand, Zahl, Untertitel und Tropfen sofort neu gesetzt - ohne Neuaufbau des Widgets."}],"hinweis":"Beide Variablen muessen numerisch sein; Texte oder Zustaende ergeben einen leeren Zylinder und einen Gedankenstrich. Die Einheit mm ist fest verdrahtet - eine Profil-Einheit wird nicht ausgewertet. Zylinderfuellung und Tropfen nutzen fest die Skin-Farbe Info. Sobald eine Raten-Variable eingetragen ist, verschwindet das Label aus der Anzeige.","groesse":[230,150],"demo":{"varId":53423,"varId2":53424,"rmax":30,"dec":1,"label":"Regen heute"}},
    "rainintensity": {"titel":"Regen-Intensitaet 48 h","zweck":"Binarisierte Regen-Leiste ueber ein Zeitfenster (Vorgabe 48 h): je Slot 0 oder 1 (Regen ja/nein nach mm/h-Schwelle), zusammenhaengende 1er = eine Phase. Kopf: Titel + Zusammenfassung <Intensitaet> gegen HH:MM - N Phasen. Zeitachse mit 6-h-Ticks. Datenquelle: die RadarMeta-JSON-Variable (Feld forecast) - dieselbe wie beim Niederschlagsradar.","funktionen":[{"name":"Radar-Meta-Variable","beschreibung":"String-Variable mit dem RadarMeta-JSON (Feld forecast:[{t,v}]). Var bindet sie per Klick im Baum."},{"name":"Titel","beschreibung":"Kopfzeile links (Vorgabe Regen 48 h)."},{"name":"Fenster (h) / Slot (h)","beschreibung":"Fensterlaenge (6-96 h) und Slot-Dauer (1-6 h). 48 h bei 2 h ergibt 24 Zellen; je Slot zaehlt der Maximalwert der enthaltenen Stunden."},{"name":"Regen-Schwelle (mm/h)","beschreibung":"Ab dieser Rate gilt ein Slot als Regen (1). Vorgabe 0,1 mm/h."},{"name":"Farbe (Regen)","beschreibung":"Skin-Farbe der 1-Zellen (Vorgabe Info/Blau); 0-Zellen bleiben gedaempft."},{"name":"Phasen / Onset (kein Feld)","beschreibung":"Phasenzahl = Anzahl der 1er-Laeufe; Onset = Startzeit des ersten Laufs (im Kopf hervorgehoben); der Intensitaetstext folgt der Maximalrate im Fenster."}],"hinweis":"Braucht die RadarMeta-Variable (das RainRadar-Modul schreibt sie). Ohne Daten erscheint Keine Vorhersagedaten, bei 0 Phasen Kein Regen in den naechsten N h. Die Zellen zeigen 0/1, nicht die Rohmenge.","groesse":[560,96],"demo":{"title":"Regen 48 h","riSlot":2,"riColor":"info"}},
    "rainradar": {"titel":"Niederschlagsradar","zweck":"Zeigt das Radar (RainRadar-Modul) mit STANDORT-ZENTRIERTEM Cover-Clipping: der Standort (aus RadarMeta img.lx/ly in Prozent, im Widget ueberschreibbar) sitzt immer in der Mitte, das Bild fuellt die Kachel verzerrungsfrei (uniforme Skalierung) und wird am Rand beschnitten - kein Stretch, Standort immer sichtbar. Zusaetzlich Kopfzeile mit Vorhersage-Kurztext und Zeitstempel.","funktionen":[{"name":"Radar-Meta-Variable","beschreibung":"String-Variable mit dem RadarMeta-JSON (img.url, img.w/h, img.lx/ly, img.ts, optional frames[] und forecast[]). Var bindet sie per Klick im Baum."},{"name":"Titel","beschreibung":"Kopfzeile links (Vorgabe Niederschlagsradar)."},{"name":"Standort X / Y (%)","beschreibung":"Ueberschreibt die Standort-Position aus der Meta (0-100 %). Leer = Wert aus img.lx/ly. Um diesen Punkt wird zentriert."},{"name":"Zoom","beschreibung":"1 = Standort zentriert und Kachel gefuellt; hoeher (bis 5) zoomt enger an den Standort."},{"name":"Standort-Marker","beschreibung":"Fadenkreuz/Punkt in der Mitte (weil der Standort immer zentriert ist), ein-/ausschaltbar."},{"name":"Dauer je Frame (ms) - Animation","beschreibung":"> 0 und mit Einzelframes (RadarMeta.frames): das Widget schaltet die Frames clientseitig im eingestellten Tempo durch und zeigt die Bild-Uhrzeit des Frames. 0 = animiertes GIF im Original-Tempo. Vorgabe 500 ms."},{"name":"Zeitstempel","beschreibung":"Zeigt img.ts (juengster Frame) bzw. im Frame-Modus die Uhrzeit des aktuellen Bildes rechts im Kopf; ein-/ausschaltbar."},{"name":"Vorhersage-Text","beschreibung":"Kurztext aus RadarMeta.forecast im Kopf, z. B. Kein Regen in den naechsten 48 h oder <Intensitaet> gegen HH:MM. Ein-/ausschaltbar."},{"name":"Fenster (h)","beschreibung":"Zeitfenster fuer den Vorhersage-Text (6-96 h). Leer = 48 (bzw. die verfuegbaren Stunden)."}],"hinweis":"Das Bild wird direkt aus der Radar-Quelle geladen (kein Media-Objekt noetig). Cover schneidet Kartenraender weg - der Standort bleibt garantiert sichtbar. Braucht die RadarMeta-Variable des RainRadar-Moduls; ohne Daten steht Radarkarte ....","groesse":[420,300],"demo":{"title":"Niederschlagsradar"}},
    "room": {"titel":"Raum","zweck":"Kompakte Raumkachel mit Icon, Raumname und bis zu drei Messwerten nebeneinander — etwa Temperatur, Luftfeuchte und Leistung eines Zimmers. Reine Anzeige, schaltet nichts.","funktionen":[{"name":"Variable","beschreibung":"Erste Metrik (varId), links in der Wertzeile."},{"name":"Metrik 2","beschreibung":"Zweite Variable (varId2). Bleibt sie leer, fehlt der zweite Wert komplett — samt zugehörigem Einheitenfeld."},{"name":"Metrik 3","beschreibung":"Dritte Variable (varId3), analog zur zweiten."},{"name":"Einheit","beschreibung":"Freitext hinter dem ersten Wert, klein und gedämpft (z. B. °C). Steht hier etwas, wird bei allen drei Werten die Profil-Einheit vom Zahlenwert abgeschnitten, damit sie nicht doppelt erscheint."},{"name":"Einheit 2 / Einheit 3","beschreibung":"Dasselbe für die zweite und dritte Metrik. Die Felder erscheinen im Editor erst, sobald die jeweilige Variable eingetragen ist."},{"name":"Format","beschreibung":"Darstellungsform des Werts (Auto, kW, kWh, W, 0/1 Dezimale, Prozent, Uhrzeit, Datum, Relativzeit), gilt für alle drei Metriken gemeinsam."},{"name":"Nachkommastellen","beschreibung":"Feste Stellenzahl 0 bis 6 aus dem Rohwert gerechnet; ohne Angabe zeigt das Widget den formatierten Wert von Symcon."},{"name":"Icon (Fallback)","beschreibung":"Symbol links oben; ohne Auswahl wird das Haus-Icon verwendet."},{"name":"Icon-Farbe","beschreibung":"Skin-Farbfeld (Standard, Akzent, OK, Warnung, Kritisch, Info, Neutral). Erscheint erst, wenn ein Icon gesetzt ist, und färbt es themetreu statt mit fester Hexfarbe."},{"name":"Assoziationen","beschreibung":"Bei Variablen mit Profil-Zuordnungen: „Icons & Farben nutzen“ übernimmt Symbol und Farbe je Zustand der ersten Variablen; jeder Zustand lässt sich mit eigenem Icon und eigener Skin-Farbe belegen."},{"name":"Label","beschreibung":"Raumname rechts neben dem Icon. Ein \\n im Text erzwingt einen Zeilenumbruch."},{"name":"Live-Aktualisierung","beschreibung":"Jede der drei Variablen aktualisiert gezielt ihren eigenen Wert; die übrigen bleiben unangetastet."},{"name":"Farben / Rahmen / Hintergrund / Beschriftung","beschreibung":"Text- und Hintergrundfarbe, Kachelrahmen, transparenter Hintergrund, mehrzeilige Beschriftung."},{"name":"Typografie","beschreibung":"Schriftart, Gewicht, Stil, Schriftgröße; die Zahlen laufen in der Monospace-Schrift."},{"name":"Interaktion","beschreibung":"Seite öffnen, Lang-Druck → Seite, Popup öffnen, Lang-Druck → Popup, Popup schließen, Skript-ID bei Klick. Typisch: Klick öffnet die Raumseite, Lang-Druck ein Detail-Popup."},{"name":"Sichtbarkeit / Animation / Ebene / Position","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Laufzeile, Einblend-Animation, Stapelreihenfolge, X, Y, Breite, Höhe."}],"hinweis":"Die drei Werte stehen in einer Zeile nebeneinander; bei schmaler Kachel oder langen Zahlen wird es schnell eng — dann breiter ziehen oder auf zwei Metriken beschränken. Das Abschneiden der Profil-Einheit hängt allein am ersten Feld „Einheit“ — bleibt es leer und sind nur Einheit 2/3 gefüllt, steht die Einheit dort doppelt.","groesse":[260,140],"demo":{"varId":39529,"unit":"°C","varId2":58345,"unit2":"%","varId3":11410,"unit3":"W","icon":"home","label":"Wohnzimmer","dec":0}},
    "sankey": {"titel":"Sankey","zweck":"Flussdiagramm auf ECharts-Basis: Jede Zeile der Fluss-Liste verbindet zwei frei benannte Knoten, die Bandbreite entspricht dem aktuellen Wert der zugeordneten Variablen.","funktionen":[{"name":"Flüsse: von · nach · Variablen-ID","beschreibung":"Die eigentliche Datenquelle. Je Zeile Startknoten, Zielknoten und Variablen-ID; Knoten entstehen automatisch aus den Namen. Zeilen anlegen/entfernen. Vorbelegt sind vier Beispielflüsse (PV/Netz → Haus → EG/Einspeisung) ohne Variablen."},{"name":"Knoten-Farbe","beschreibung":"Skin-Farbe der Knotenbalken (Auto/Akzent/OK/Warnung/Kritisch/Info/Warm/Gedämpft …). Die Bänder laufen als Verlauf zwischen den Knotenfarben."},{"name":"Ausrichtung","beschreibung":"Horizontal (links → rechts) oder vertikal (oben → unten)."},{"name":"Beschriftung","beschreibung":"Knotennamen ein-/ausblenden. Aus ist sinnvoll bei sehr kleinen Diagrammen."},{"name":"Fluss-Wert","beschreibung":"Blendet den Zahlenwert an jedem Band ein, auf eine Nachkommastelle gerundet."},{"name":"Deckkraft %","beschreibung":"Transparenz der Bänder, 0 bis 100 (Vorgabe 35). Höher = kräftigere Flüsse."},{"name":"Kurvigkeit %","beschreibung":"Krümmung der Bänder, 0 bis 100 (Vorgabe 50). 0 = gerade Verbindungen."},{"name":"Titel anzeigen","beschreibung":"Zeigt das Label als Diagrammtitel und reserviert dafür Platz. Ist das Label leer, weist der Editor darauf hin, dass nichts erscheint."},{"name":"Titel-Position","beschreibung":"Links, zentriert oder rechts; erscheint erst, wenn der Titel aktiv ist."},{"name":"Hervorhebung","beschreibung":"Beim Überfahren eines Knotens/Bands hebt ECharts den zusammenhängenden Pfad hervor (focus: adjacency) und zeigt einen Tooltip."},{"name":"Live-Aktualisierung","beschreibung":"Ändert sich eine der Listen-Variablen, wird das Diagramm neu gesetzt. Negative Werte gehen als Betrag ein, fehlende/nicht numerische als 0."},{"name":"Farben / Typografie / Interaktion / Sichtbarkeit / Position","beschreibung":"Text-/Hintergrundfarbe, Rahmen, transparenter Hintergrund, Schrift (skaliert mit Widgetgröße und wirkt auf Knoten-/Wertlabels), Seiten-/Popup-Aktionen, Sichtbarkeitsregeln, Ebene und Position."}],"hinweis":"Braucht die ECharts-Bibliothek; ohne sie bleibt die Fläche leer. Das allgemeine Feld „Variable“ ganz oben hat keine Wirkung — Daten kommen nur aus der Fluss-Liste. Zeilen ohne Von/Nach werden übersprungen; ein Wert 0 wird auf 0,001 angehoben, damit das Band nicht verschwindet. Kreisförmige Verbindungen (A → B → A) kann ECharts nicht zeichnen.","groesse":[440,270],"demo":{"label":"Energiefluss","showTitle":true,"titlePos":"left","snNode":"accent","snOrient":"h","snLabels":true,"snVal":true,"snOpacity":40,"snCurve":50,"links":[{"from":"PV","to":"Haus","vid":22213},{"from":"Netz","to":"Haus","vid":46587},{"from":"Haus","to":"Erdgeschoss","vid":54251},{"from":"Haus","to":"Dachgeschoss","vid":29885}]}},
    "select": {"titel":"Auswahl","zweck":"Setzt eine Variable auf einen von mehreren festen Werten — als Knopfreihe, kompakte Klappliste oder Schieber (Mehrpositions-Toggle). Der aktuell gültige Wert ist markiert.","funktionen":[{"name":"Variable","beschreibung":"Die zu schreibende Variable. Ohne sie zeigt das Widget zwar Optionen an, schaltet aber nichts."},{"name":"Darstellung","beschreibung":"Knopfreihe (Vorgabe, gut für zwei bis vier Optionen), Klappliste (wenn mehrere Auswahlfelder nebeneinander in eine Zeile müssen) oder Schieber — ein Mehrpositions-Toggle mit gleitendem Knopf in der Farbe des aktiven Zustands (derselbe Schieber wie im Schalter-Widget)."},{"name":"Rundung (nur Schieber)","beschreibung":"swmShape — Form von Track und Knopf: Pille (Vorgabe), Abgerundet oder Eckig."},{"name":"Optionen aus","beschreibung":"„eigener Liste“ (Vorgabe) verwendet die selbst gepflegte Liste; „Variablenprofil“ holt die Zuordnungen des Profils (inkl. Farbe und Icon) über ?api=assoc und folgt ihnen automatisch, wenn sich das Profil in Symcon ändert."},{"name":"Optionen: Wert · Text · Gruppe · Icon · Farbe","beschreibung":"Die manuelle Liste. Je Zeile der zu schreibende Wert, die Beschriftung, eine optionale Gruppe, ein Icon (Icon-Picker) und eine Skin-Farbe. Icons erscheinen in Knopfreihe UND Schieber. Ausgeblendet, solange die Optionen aus dem Profil kommen."},{"name":"Gruppen-Cluster","beschreibung":"Ist bei mindestens einer Option ein Gruppen-Feld gesetzt, werden die Optionen geclustert: in der Knopfreihe je Gruppe eine kleine Überschrift, in der Klappliste als optgroup. Reihenfolge = erstes Auftreten der Gruppe."},{"name":"Schalten per Klick","beschreibung":"Knopfreihe: ein Klick schreibt sofort den Wert und markiert ihn. Klappliste: die Auswahl löst den Schreibvorgang aus. Der Server wandelt den Text passend zum Variablentyp (Bool/Integer/Float)."},{"name":"Markierung des Istwerts","beschreibung":"Der Knopf, dessen Wert dem Variablenwert entspricht, wird hervorgehoben; die Klappliste springt auf den passenden Eintrag — außer während sie gerade geöffnet ist."},{"name":"Profil-Abruf","beschreibung":"Die Zuordnungen werden je Variable genau einmal geholt und zwischengespeichert; mehrere Auswahlfelder auf derselben Variablen teilen sich den Abruf. Bis die Antwort da ist, steht ein Platzhalter „…“."},{"name":"Label","beschreibung":"Wird links neben den Optionen angezeigt (mit optionalem Icon), wenn gesetzt; ohne Label gehört die Fläche ganz den Optionen."},{"name":"Farben / Typografie / Interaktion / Sichtbarkeit / Position","beschreibung":"Text-/Hintergrundfarbe, Rahmen, transparenter Hintergrund, Schrift, Seiten-/Popup-Aktionen (werden VOR dem Schalten geprüft), Sichtbarkeitsregeln, Ebene und Position."}],"hinweis":"Geschaltet wird nur außerhalb des Bearbeiten-Modus. Die Option-Farbe wird im Schieber voll genutzt (Knopf + getönter Track); in Knopfreihe/Klappliste ist nur die Akzentmarkierung des aktiven Eintrags sichtbar. Die Markierung vergleicht Zeichenketten: bei einer Boolean-Variablen liefert der Server true/false, Optionswerte 0/1 passen darauf nie — für reines Ein/Aus lieber das Schalter-Widget im Toggle-Modus.","groesse":[300,90],"demo":{"varId":13239,"label":"Helligkeit Lesezimmer","smode":"btn","options":[{"value":0,"text":"Aus","color":""},{"value":50,"text":"Halb","color":"warn"},{"value":100,"text":"Voll","color":"ok"}]}},
    "shape": {"titel":"Form","zweck":"Reines Gestaltungselement ohne Datenbindung: ein Rechteck, ein Kreis oder eine waagerechte Linie zum Gruppieren, Hinterlegen und Trennen anderer Widgets.","funktionen":[{"name":"Farbe","beschreibung":"Füllfarbe der Form (bei „Linie“ nur wirksam, solange keine Konturfarbe gesetzt ist). Ersetzt bei diesem Widget das sonst übliche Feld „Variable“."},{"name":"Form","beschreibung":"rect (Rechteck), circle (Kreis bzw. Ellipse, füllt die Widgetfläche) oder line (waagerechte Linie mittig im Widget)."},{"name":"Kontur","beschreibung":"Konturfarbe und Konturbreite in Pixeln, dazu ein Knopf zum Entfernen der Kontur. Wird eine Farbe gewählt und war die Breite 0, setzt das Widget sie automatisch auf 2. Die Zeile erscheint nur bei Rechteck und Kreis."},{"name":"Eckenradius","beschreibung":"Rundung der Rechteckecken in Pixeln (Vorgabe 8). Nur beim Rechteck sichtbar; der Kreis rundet immer auf 50 %."},{"name":"Ebene","beschreibung":"„nach hinten“ ist die wichtigste Einstellung für dieses Widget: Nur so liegt die Fläche unter den Kacheln, die sie zusammenfassen soll."},{"name":"Farben / Hintergrund / Beschriftung","beschreibung":"Die allgemeinen Farbfelder wirken auf die Kachel hinter der Form, nicht auf die Form selbst — die Form deckt die Kachel vollständig ab. Für „Form“ gibt es kein Feld „Rahmen“ und keine Typografie."},{"name":"Kein Text (kein Feld)","beschreibung":"Das Label wird nicht dargestellt; für Beschriftungen ein Text-Widget darüberlegen."},{"name":"Interaktion","beschreibung":"Seite öffnen, Lang-Druck → Seite, Popup öffnen, Lang-Druck → Popup, Popup schließen, Skript-ID bei Klick — damit lässt sich eine Form als unsichtbare oder farbige Schaltfläche verwenden."},{"name":"Sichtbarkeit","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung — eine Form kann so als zustandsabhängige Markierung eingeblendet werden."},{"name":"Animation / Ebene / Position","beschreibung":"Einblend-Animation, nach vorn/hinten legen, X, Y, Breite, Höhe (Vorgabegröße 80 × 80)."}],"hinweis":"Stolperfalle: „Hintergrund → Transparent“ macht nicht nur die Kachel, sondern auch die Form selbst durchsichtig — die Füllfarbe verschwindet dann. Zweite Stolperfalle: Bei „line“ blendet der Editor die Kontur-Zeile aus; Strichfarbe und Strichstärke müssen also gesetzt sein, BEVOR man auf Linie umstellt, sonst zeichnet das Widget die Linie in der Füllfarbe und 3 px stark. Ein Rahmen-Feld gibt es für „Form“ nicht.","groesse":[180,120],"demo":{"shape":"rect","color":"#16323a","radius":16,"stroke":"#00cdab","strokeW":2,"frame":false}},
    "skinswitch": {"titel":"Skin-Wechsler","zweck":"Auswahlfeld für den aktiven Skin plus zwei Tasten für Hell/Dunkel. Der Betrachter wechselt damit im laufenden Betrieb die Darstellung der gesamten Ansicht.","funktionen":[{"name":"Skin-Auswahl (Klappliste)","beschreibung":"Listet alle verfügbaren Skins (eingebaute plus die unter Einstellungen angelegten). Die Auswahl setzt store.skin, wendet den Skin sofort auf alle Widgets an und merkt ihn im Browser."},{"name":"Sonne / Mond (zwei Tasten)","beschreibung":"Schaltet zwischen hellem und dunklem Modus (store.theme). Die aktive Taste ist hervorgehoben; die Wahl wird pro Browser gespeichert und beim nächsten Laden im Run-Modus wieder gesetzt."},{"name":"Label","beschreibung":"Wird von diesem Widget nicht gezeichnet – es hat keine eigene Beschriftung. Der Text dient nur der Orientierung im Editor."},{"name":"Keine Variable","beschreibung":"Das Widget hat bewusst keine Variablen-Zeile; es wirkt rein auf die Anzeige und schreibt nichts nach IP-Symcon zurück."},{"name":"Automatischer Abgleich","beschreibung":"Wird der Skin oder das Thema an anderer Stelle geändert, ziehen Klappliste und Tastenzustand automatisch nach."},{"name":"Farben, Rahmen, Hintergrund, Typografie","beschreibung":"Zentrale Gestaltungszeilen wie bei jedem Widget: Text-/Hintergrundfarbe, Rahmen an/aus/Standard, transparenter Hintergrund, Schriftart, Gewicht, Stil, Größe."},{"name":"Interaktion","beschreibung":"Zentrale Zeilen Seite/Popup öffnen (auch per Lang-Druck), Popup schließen, Skript-ID. Achtung: Diese werden im Klick-Ablauf VOR dem Skin-Wechsler abgearbeitet – ist eine davon gesetzt, reagieren die Hell/Dunkel-Tasten nicht mehr. Die Klappliste hängt am separaten Änderungs-Ereignis und wirkt weiterhin."},{"name":"Sichtbarkeit / Animation / Ebene","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, Einblend-Animation, nach vorn/hinten, sowie X/Y/Breite/Höhe."}],"hinweis":"Wirkt nur im Bedien-/Run-Modus; im Bearbeiten-Modus sind Liste und Tasten ohne Funktion. Die Wahl gilt pro Browser (localStorage), nicht anlagenweit.","groesse":[260,64],"demo":{"label":"Ansicht"}},
    "slider": {"titel":"Regler","zweck":"Eine Widget-Familie zum Setzen von Zahlenwerten: Schieberegler, Bereichsregler mit zwei Griffen (linear oder rund), Stepper mit +/− Tasten und runder Dial-Sollwertregler. Der eingestellte Wert wird direkt in die Variable geschrieben.","funktionen":[{"name":"Regler-Typ","beschreibung":"Wählt die Variante, gruppiert in Linear (Schieberegler, Bereichsregler, Stepper) und Rund (Dial, Bereichsregler rund). Beim Wechsel werden Standardgröße und Standard-Beschriftung übernommen, solange man sie nicht selbst geändert hat; eine gesetzte zweite Variable wird bei Ein-Wert-Varianten verworfen."},{"name":"Variable","beschreibung":"Die geschriebene Variable (zentrale Zeile). Bei den Zwei-Griff-Varianten ist das der untere Wert."},{"name":"Oben (Var)","beschreibung":"Nur bei Bereichsregler linear und rund: Variable für den oberen Griff (mit Wähl-Knopf). Die Zahlen dort haben eine eigene Formatierung (linear bis 3 Nachkommastellen, rund eine), Format/Präfix/Suffix greifen nicht. Fehlt ein Live-Wert, startet der obere Griff linear am Maximum, rund dagegen am Minimum."},{"name":"Min / Max","beschreibung":"Skalenanfang und -ende (zentrale Zeilen). Beim Stepper sind es die Klemmgrenzen für das Hoch-/Runterzählen."},{"name":"Schritt","beschreibung":"Rasterung des Werts. Beim Stepper ist es das Inkrement je Tastendruck."},{"name":"Spiegeln","beschreibung":"Nur beim Schieberegler: kehrt die Skala optisch um (z. B. für Rollos, die von oben zählen); der geschriebene Wert selbst bleibt unverändert."},{"name":"Nachkommastellen","beschreibung":"Nur bei Stepper und Dial: Anzahl der angezeigten Dezimalstellen (0–6); leer = Vorgabe des Profils."},{"name":"Format","beschreibung":"Zentrale Formatzeile für die Wertanzeige (z. B. Prozent, Leistung, Uhrzeit); wirkt bei Schieberegler, Stepper und Dial."},{"name":"Schreibverhalten Schieberegler","beschreibung":"Der Wert wird beim Loslassen geschrieben; solange der Griff den Fokus hat, überschreibt der Live-Wert die Position nicht."},{"name":"Schreibverhalten Bereichsregler","beschreibung":"Während des Ziehens wird höchstens alle 110 ms geschrieben, beim Loslassen einmal final (linear wie rund). Der untere Griff kann nicht über den oberen und umgekehrt. Live-Werte werden während des Ziehens ignoriert."},{"name":"Bedienung Stepper","beschreibung":"Kurzes Tippen setzt einen Schritt, Halten wiederholt nach 420 ms alle 200 ms, bis losgelassen wird."},{"name":"Bedienung Dial","beschreibung":"Tippen auf den 270°-Bogen setzt den Wert direkt (kein Ziehen). Sind Popup, Seitenwechsel, Menü, Region oder Skript-ID konfiguriert, gewinnen diese und der Wert wird nicht gesetzt."},{"name":"Live-Aktualisierung","beschreibung":"Alle Varianten ziehen bei jedem eingehenden Wert nach: Zahlanzeige, Griffposition, Füllbalken bzw. Bogen."},{"name":"Interaktion / Sichtbarkeit / Gestaltung","beschreibung":"Zentrale Zeilen: Seite/Popup öffnen (auch per Lang-Druck), Popup schließen, Skript-ID, Sichtbarkeit über Steuer-Variable, Farben, Rahmen, transparenter Hintergrund, Typografie, Animation, Ebene, Geometrie."}],"hinweis":"Bedienbar nur im Bedien-/Run-Modus, im Bearbeiten-Modus reagieren die Griffe nicht. Die Varianten teilen sich Min/Max/Schritt; alte Eigenschaften rsMin/rsMax/rsStep bzw. crMin/crMax/crStep werden beim ersten Zeichnen still übernommen. Die früheren eigenen Typen rangeslider, circlerange, rangebtn und dial werden beim Laden still auf slider + rmode umgeschrieben.","groesse":[280,100],"demo":{"rmode":"slider","varId":13239,"label":"Dimmer","min":0,"max":100,"step":1}},
    "statelog": {"titel":"Zustands-Verlauf","zweck":"Zeigt die letzten Zustandswechsel einer Variablen als Aktivitätsliste: farbiger Punkt, Klartextname des Zustands und Uhrzeit, neuester Eintrag oben.","funktionen":[{"name":"Variable","beschreibung":"Die ausgewertete Variable (zentrale Zeile „Variable“). Ihr Verlauf wird über die History-Schnittstelle aus dem Archiv geholt."},{"name":"Zeitraum","beschreibung":"Anzahl plus Einheit (Stunden, Tage, Wochen, Monate), gespeichert als range = {n, unit}. Legt fest, wie weit zurück Wechsel gesucht werden."},{"name":"Max. Einträge","beschreibung":"Obergrenze der angezeigten Zeilen (Eigenschaft count, Vorgabe 20). Es werden die jüngsten Wechsel gezeigt, ältere fallen weg."},{"name":"Zustände: Wert · Farbe · Name","beschreibung":"Listeneditor (states mit v · color · label). Wert erlaubt exakte Werte, Operatoren (>0, >=1, <5, <=3, !=0, =2), Bereiche (1..5 oder 1:5) sowie Platzhalter (* bzw. else/sonst/default). Farbe ist eine Skin-Farbe aus der Auswahlliste und färbt den Punkt. Name ist der Text in der Zeile; ohne Treffer wird der Rohwert angezeigt."},{"name":"Zustände aus Profil füllen","beschreibung":"Übernimmt die Assoziationen des Variablenprofils (Wert, Farbe, Name) in einem Zug in die Zustandsliste. Ohne gewählte Variable kommt nur ein Hinweis."},{"name":"Label","beschreibung":"Überschrift über der Liste (in Großbuchstaben gesetzt); leer lassen blendet die Kopfzeile aus."},{"name":"Live-Aktualisierung","beschreibung":"Ändert sich die Variable, wird der Verlauf rund 1,2 Sekunden später entprellt neu aus dem Archiv geladen – neue Wechsel erscheinen von selbst oben."},{"name":"Leerzustände","beschreibung":"Ohne Variable steht „Variable wählen“, ohne Wechsel im Zeitraum „keine Wechsel im Zeitraum“ in der Liste."},{"name":"Beschriftung mehrzeilig","beschreibung":"Zentrale Option; erlaubt Umbruch statt Abschneiden der Zustandsnamen."},{"name":"Interaktion / Sichtbarkeit / Gestaltung","beschreibung":"Zentrale Zeilen: Seite oder Popup öffnen (auch per Lang-Druck), Skript-ID, Sichtbarkeit über Steuer-Variable, Farben, Rahmen, transparenter Hintergrund, Typografie, Animation, Ebene, Geometrie."}],"hinweis":"Braucht das Archiv: Die Variable muss im Archiv-Handler protokolliert werden, sonst bleibt die Liste leer. Nur der geloggte Wechselverlauf zählt – ein reiner Live-Wert ohne Archiv erzeugt keine Zeile.","groesse":[320,280],"demo":{"varId":30519,"label":"Licht Lesezimmer","range":{"n":24,"unit":"hour"},"count":12,"states":[{"v":"1","color":"ok","label":"Licht ein"},{"v":"0","color":"muted","label":"Licht aus"}]}},
    "statetl": {"titel":"Zustands-Timeline","zweck":"Zeichnet für eine oder mehrere Zustandsvariablen einen durchgehend gefüllten Zeitbalken, in dem jeder Zustand seine eigene Farbe hat. Der Zeitraum kann rollierend oder kalender-ausgerichtet sein; optional läuft darunter eine Aktivitätsliste der Wechsel mit.","funktionen":[{"name":"Signale (Zustands-Variablen)","beschreibung":"Listeneditor items mit vid und label je Spur. Jede Zeile wird zu einer eigenen Bahn; der Name steht daneben und nimmt die Farbe des aktuellen Zustands an. Ohne Signal steht ein Hinweis in der Fläche."},{"name":"Zeitraum","beschreibung":"Zentrale Zeitraum-Steuerung: rollierend (Anzahl + Einheit) ODER kalender-ausgerichtet (Perioden-Modus mit Einheit Stunde/Tag/Woche/Monat/Jahr). Im Kalender-Modus wird der VOLLE Zeitraum gezeigt; die noch nicht abgelaufene Zeit der laufenden Einheit erscheint schraffiert als „offen“."},{"name":"Orientierung","beschreibung":"horizontal (Zeit läuft nach rechts) oder vertikal (Zeit läuft nach oben); Beschriftung und Zeitachse werden entsprechend umgestellt."},{"name":"Legende","beschreibung":"Ein-/ausblendbar: aus jedem Zustand mit Farbe wird automatisch ein Legendeneintrag in der Kopfzeile erzeugt; im Perioden-Modus zusätzlich „offen“ für die schraffierte Restzeit."},{"name":"Signal-Bezeichnung","beschreibung":"Ein-/ausblendbar: die Namen der Bahnen (und im Perioden-Modus der Titel); ausgeblendet füllen die Balken die Kachel."},{"name":"Uhrzeit / Achse","beschreibung":"Ein-/ausblendbare Zeitachse unter bzw. neben den Bahnen; im Kalender-Modus mit passenden Marken (Stunden, Wochentage, Monatstage, Monate)."},{"name":"Perioden-Umschalter","beschreibung":"Ein-/ausblendbare Pfeil-Navigation in der Kopfzeile, um im Kalender-Modus durch die Perioden zu blättern (nur bis zur aktuellen)."},{"name":"Verlaufsliste","beschreibung":"Blendet unter dem Balken eine Aktivitätsliste (Punkt, Name, Uhrzeit) ein; sie zeigt immer das erste Signal der Liste mit gesetzter ID."},{"name":"Max. Einträge","beschreibung":"Nur bei eingeschalteter Verlaufsliste: Obergrenze der Zeilen (Eigenschaft logCount, Vorgabe 20)."},{"name":"Zustände: Wert · Farbe · Name (leer = transparent)","beschreibung":"Listeneditor states mit v · color · label, gilt für alle Spuren. Wert erlaubt exakte Werte, Operatoren (>0, <=3, !=0 …), Bereiche (1..5) und Platzhalter (*/else). Ohne Farbe bleibt das Segment durchsichtig, zeigt also die Schiene – so lässt sich „Aus“ bewusst leer darstellen."},{"name":"Zustände aus Profil füllen","beschreibung":"Liest die Assoziationen des ersten Signals mit Variable aus dem Variablenprofil und legt daraus die Zustandsliste an."},{"name":"Live-Aktualisierung","beschreibung":"Ein Wechsel einer Signalvariablen löst nach etwa 1,2 Sekunden entprellt ein Nachladen aus; bis dahin füllt der bekannte Live-Wert das Segment bis zum rechten Rand."},{"name":"Label / Beschriftung mehrzeilig","beschreibung":"Titel in der Kopfzeile; die zentrale Option „mehrzeilig statt abschneiden“ wirkt auf Titel, Spurnamen und Verlaufszeilen."},{"name":"Interaktion / Sichtbarkeit / Gestaltung","beschreibung":"Zentrale Zeilen: Seite oder Popup öffnen (auch per Lang-Druck), Skript-ID, Sichtbarkeit über Steuer-Variable, Farben, Rahmen, transparenter Hintergrund, Typografie, Animation, Ebene, Geometrie."}],"hinweis":"Braucht das Archiv: Jede Signalvariable muss protokolliert werden, sonst bleibt die Bahn leer. Die zentrale Zeile „Variable“ wird zwar angeboten, aber für die Darstellung nicht ausgewertet – maßgeblich ist ausschließlich die Liste „Signale“.","groesse":[380,300],"demo":{"label":"Zustände 24 h","range":{"n":24,"unit":"hour"},"orient":"h","showLog":true,"logCount":6,"items":[{"vid":30519,"label":"Licht Lesezimmer"},{"vid":41522,"label":"Zisterne"}],"states":[{"v":"1","color":"ok","label":"Ein"},{"v":"0","color":"","label":"Aus"},{"v":">1","color":"info","label":"Wert > 1"}]}},
    "statusgrid": {"titel":"Status-Grid","zweck":"Raster aus Statuszeilen: je Zeile ein Icon, ein Name und eine farbige Pille mit Punkt und Text. Kompakte Uebersicht ueber Fenster, Tueren, Zaehler oder Geraete. Das Raster fuellt sich zweispaltig und scrollt bei Bedarf.","funktionen":[{"name":"Zeilen: Icon · Name · Status · Text · ID","beschreibung":"Listeneditor items mit den Spalten icon, label, state, text und vid; jede Zeile ergibt eine Kachel im Raster. Beliebig viele Zeilen."},{"name":"Icon","beschreibung":"Name eines Icons aus der eingebauten Bibliothek (z. B. window, door, lock, garage, bulb, bolt). Leer laesst die Zeile ohne Icon."},{"name":"Name","beschreibung":"Beschriftung links neben der Pille (label)."},{"name":"Status","beschreibung":"Farbklasse der Pille (state): ok (gruen), warn (gelb), off (blass) und weitere CSS-Klassen. Fester Wert aus dem Editor – er wird nicht aus dem Variablenwert abgeleitet; ohne Eintrag gilt ok."},{"name":"Text","beschreibung":"Text in der Pille. Ist eine ID hinterlegt, ersetzt der vom Server formatierte Variablenwert diesen Text im Betrieb; ohne ID bleibt der feste Text stehen."},{"name":"ID","beschreibung":"Variable der Zeile (vid). Ihr formatierter Wert fuellt ueber den generischen Slot data-vid den Pillentext, zusaetzlich bekommt die Pille bei wahr/1 die Klasse „on“ (Akzent) und verliert sie bei falsch/0 (data-viddot)."},{"name":"Keine zentrale Variable","beschreibung":"Das Widget hat bewusst keine Zeile „Variable“; alle Bindungen laufen ueber die ID-Spalte der Zeilen."},{"name":"Interaktion / Sichtbarkeit / Gestaltung","beschreibung":"Zentrale Zeilen: Seite oder Popup oeffnen (auch per Lang-Druck), Skript-ID, Sichtbarkeit ueber Steuer-Variable, Farben, Rahmen, transparenter Hintergrund, Typografie, Animation, Ebene, Geometrie."}],"hinweis":"Die Statusfarbe ist statisch und richtet sich nicht nach dem Variablenwert – nur der Zusatzzustand „on“ (Akzent) kommt aus der Variablen. Wer echte Wert-zu-Farbe-Logik braucht, nimmt ein Zustands-Widget. In einem Popup werden die generischen Slots nicht nachgezogen – sie wirken nur auf der Seitenflaeche.","groesse":[380,200],"demo":{"items":[{"icon":"bulb","label":"Lesezimmer","state":"on","text":"–","vid":30519},{"icon":"cistern","label":"Zisterne","state":"warn","text":"–","vid":41522},{"icon":"bolt","label":"Leistung","state":"ok","text":"–","vid":38704},{"icon":"temperature","label":"Außen","state":"off","text":"–","vid":26109}]}},
    "statusimage": {"titel":"Status-Bild","zweck":"Zeigt je nach Variablenwert ein anderes Media-Objekt an. Der Sonderwert „off“ zeigt statt eines zweiten Bildes das Farbbild in Graustufen und abgeschwaecht – das spart ein eigenes Aus-Bild.","funktionen":[{"name":"Variable","beschreibung":"Bestimmt den anzuzeigenden Zustand; bei jeder Aenderung wird das Bild sofort getauscht (varId)."},{"name":"Farbbild (Media)","beschreibung":"mediaId: Media-ID des Grundbilds. Es wird gezeigt, wenn kein Zustand passt oder ein Zustand keine eigene Media-ID hat, und dient als Vorlage fuer die Graustufen-Darstellung. Bleibt das Feld leer, wird die erste Media-ID aus der Zustandsliste als Farbbild benutzt."},{"name":"Zustände: Wert · Media-ID","beschreibung":"Listeneditor states mit den Spalten value und mediaId. Wert erlaubt true/false/0/1, exakte Werte, Operatoren (>0, <=3, !=0 …), Bereiche (1..5) und Platzhalter (*/else); Media-ID ist eine echte ID oder das Schluesselwort off."},{"name":"Media-ID „off“","beschreibung":"Statt eines zweiten Bildes wird das Farbbild mit Graustufenfilter und reduzierter Deckkraft gezeigt. Auch grau, gray, grey, bw, sw und s/w werden als Graustufen-Schluesselwort erkannt."},{"name":"Trefferreihenfolge","beschreibung":"Zuerst wird auf exakte Gleichheit geprueft (inklusive wahr/falsch-Gleichsetzung), erst danach auf Muster und Operatoren – der erste Treffer gewinnt (frueher gewann der letzte)."},{"name":"Label","beschreibung":"Beschriftung, die unten links ueber dem Bild liegt. Leer lassen blendet sie aus."},{"name":"Darstellung","beschreibung":"Das Bild wird proportional in die Widgetflaeche eingepasst (object-fit contain), es wird nichts beschnitten."},{"name":"Interaktion / Sichtbarkeit / Gestaltung","beschreibung":"Zentrale Zeilen: Seite oder Popup oeffnen (auch per Lang-Druck), Skript-ID, Sichtbarkeit ueber Steuer-Variable, Farben, Rahmen, transparenter Hintergrund, Typografie, Animation, Ebene, Geometrie."}],"hinweis":"Die Bilder kommen aus dem Media-Pool von IP-Symcon (?api=media&id=…); es braucht gueltige Media-Objekte, keine Dateipfade. Ohne Farbbild und ohne Media-ID in den Zustaenden bleibt die Flaeche leer.","groesse":[170,180],"demo":{"varId":30519,"label":"Licht Lesezimmer","mediaId":49869,"states":[{"value":false,"mediaId":"off"},{"value":true,"mediaId":0}]}},
    "statuslist": {"titel":"Status-Liste","zweck":"Schlanke Liste aus Namen mit vorangestelltem Statuspunkt. Der Punkt leuchtet in der OK-Farbe, sobald die zugehoerige Variable wahr bzw. 1 ist – gedacht fuer Dienste, Anwesenheiten oder Ein/Aus-Meldungen.","funktionen":[{"name":"Zeilen: Name · Status-ID","beschreibung":"Listeneditor rows mit den Spalten label und vid; jede Zeile ergibt einen Eintrag. Beliebig viele Zeilen, die Liste scrollt bei Ueberlaenge."},{"name":"Name","beschreibung":"Beschriftung der Zeile (label). Wird nicht aus der Variablen uebernommen, sondern hier fest eingetragen."},{"name":"Status-ID","beschreibung":"Variable der Zeile (vid). Nur der Ein/Aus-Zustand wird ausgewertet: wahr, 1 oder „1“ faerbt den Punkt in der OK-Farbe, alles andere laesst ihn blass. Ohne ID bleibt der Punkt dauerhaft blass."},{"name":"Live-Aktualisierung","beschreibung":"Laeuft ohne eigenen Live-Hook ueber den generischen Slot data-viddot; jeder eingehende Wert schaltet den Punkt sofort um."},{"name":"Keine Wertanzeige","beschreibung":"Das Widget zeigt bewusst keinen Zahlen- oder Textwert. Wer Werte je Zeile braucht, nimmt Geraete-Liste oder Status-Grid."},{"name":"Keine zentrale Variable","beschreibung":"Das Widget hat keine Zeile „Variable“; alle Bindungen laufen ueber die ID-Spalte der Zeilen."},{"name":"Interaktion / Sichtbarkeit / Gestaltung","beschreibung":"Zentrale Zeilen: Seite oder Popup oeffnen (auch per Lang-Druck), Skript-ID, Sichtbarkeit ueber Steuer-Variable, Farben, Rahmen, transparenter Hintergrund, Typografie, Animation, Ebene, Geometrie."}],"hinweis":"Der Punkt kennt nur an oder aus. Zahlenvariablen (z. B. 22 % Fuellstand) lassen ihn immer blass – dafuer Status-Grid oder ein Zustands-Widget verwenden. In einem Popup werden die Punkte nicht nachgezogen: Der generische Slot wirkt nur auf der Seitenflaeche.","groesse":[260,180],"demo":{"rows":[{"label":"Licht Lesezimmer","vid":30519},{"label":"Alarmanlage","vid":22090},{"label":"Zisterne","vid":41522}]}},
    "sun": {"titel":"Sonne","zweck":"Zeigt Sonnenaufgang und Sonnenuntergang nebeneinander, jeweils mit festem Symbol und Beschriftung. Reine Anzeige zweier Zeit-Variablen ohne Bogen oder Verlauf.","funktionen":[{"name":"Variable","beschreibung":"Zeit-Variable fuer den Sonnenaufgang (linke Spalte, varId). Der Wert wird live nachgefuehrt."},{"name":"Untergang","beschreibung":"Zweite Variable (varId2) fuer den Sonnenuntergang (rechte Spalte). Das Eigenschaftsfeld heisst bei diesem Typ „Untergang“."},{"name":"Format","beschreibung":"Wert-Format fuer BEIDE Zeiten gemeinsam. Bei ~UnixTimestamp-Variablen liefert „Uhrzeit“ (fmt='time') die reine hh:mm-Anzeige."},{"name":"Label / Name","beschreibung":"Das Label wird NICHT dargestellt (die Spaltenbeschriftungen „Aufgang“/„Untergang“ sind fest im Markup). Name dient nur der Wiedererkennung, z. B. in der Laufzeile."},{"name":"Farben / Rahmen / Hintergrund","beschreibung":"Text- und Hintergrundfarbe, Rahmen an/aus/Ansicht-Standard, Hintergrund deckend oder transparent."},{"name":"Typografie","beschreibung":"Schriftart, Gewicht, Stil/kursiv und Schriftgroesse in px."},{"name":"Interaktion","beschreibung":"Klick: Seite oeffnen, Popup oeffnen/schliessen, Skript starten. Lang-Druck (550 ms): eigene Seite oder eigenes Popup. Nur im Bedien-/Run-Modus aktiv."},{"name":"Sichtbarkeit / Animation / Ebene / Geometrie","beschreibung":"Ein-/Ausblenden zur Laufzeit oder ueber eine Steuer-Variable, Einblend-Animation, Z-Reihenfolge, X/Y/Breite/Hoehe."},{"name":"Live-Verhalten","beschreibung":"Jede der beiden Zeiten wird einzeln aktualisiert, sobald ihre Variable einen neuen Wert meldet."}],"hinweis":"Beide Variablen muessen gesetzt sein, sonst bleibt die jeweilige Spalte auf „–“. Ohne Format „Uhrzeit“ zeigt eine ~UnixTimestamp-Variable Datum UND Uhrzeit, was in der schmalen Spalte umbricht. Ein Icon- oder Assoziations-Feld gibt es bei diesem Typ nicht.","groesse":[240,110],"demo":{"varId":40329,"varId2":16467,"fmt":"time","label":"Sonne"}},
    "suncard": {"titel":"Sonnenbogen","zweck":"Stellt den Tagesverlauf der Sonne als Bogen dar: Aufgang links, Untergang rechts, die Sonne wandert entsprechend der aktuellen Uhrzeit. Darunter stehen beide Zeiten und die Tageslaenge. Optional mit durchgehender Nachtkurve und Mond.","funktionen":[{"name":"Variable","beschreibung":"Zeit-Variable des Sonnenaufgangs (varId); bestimmt den linken Bogenanfang."},{"name":"Untergang","beschreibung":"Zeit-Variable des Sonnenuntergangs (varId2); bestimmt das Bogenende."},{"name":"Uhrzeit anzeigen","beschreibung":"showTime – blendet ein kleines Zeitschild direkt an der Sonnen-/Mondposition ein (aktuelle Uhrzeit hh:mm)."},{"name":"Nacht + Mond","beschreibung":"showNight – schaltet von der reinen Tageskurve auf eine durchgehende 24-Stunden-Kurve mit Horizontlinie: Tagbogen oberhalb, Nachtbogen unterhalb, Mond statt Sonne in der Nacht; weiche Daemmerungs-Umblendung."},{"name":"Tageslaenge","beschreibung":"Wird ohne Einstellung automatisch aus der Differenz der beiden Zeiten berechnet und mittig angezeigt (z. B. „15 h 02 min“)."},{"name":"Fuellflaeche","beschreibung":"Die Flaeche unter dem Bogen fuellt sich bis zur aktuellen Sonnenposition, nachts unter dem Nachtbogen – ohne Einstellung, rein aus der Uhrzeit."},{"name":"Label / Name","beschreibung":"Das Label wird nicht gezeichnet (der Vorgabewert „Sonne“ dient nur der Wiedererkennung im Baum). Name ist die interne Kennung."},{"name":"Farben / Rahmen / Typografie","beschreibung":"Text- und Hintergrundfarbe, Rahmen an/aus/Standard, Hintergrund deckend/transparent, Schriftart/-gewicht/-stil/-groesse fuer die Zeitzeile."},{"name":"Interaktion / Sichtbarkeit / Animation","beschreibung":"Klick auf Seite/Popup/Skript, Lang-Druck auf zweite Seite/Popup; Ein-/Ausblenden zur Laufzeit oder per Steuer-Variable; Einblend-Animation, Ebene, Geometrie."},{"name":"Live-Verhalten","beschreibung":"Die Kurve wird bei jeder Wertaenderung UND im Sekundentakt neu gezeichnet; Sonne, Mond, Fuellflaeche und Zeitschild folgen der Systemzeit des anzeigenden Geraets."}],"hinweis":"Bogen, Sonne und Tageslaenge werden nur gezeichnet, wenn beide Zeiten gueltig sind und der Untergang nach dem Aufgang liegt; die Zeittexte darunter erscheinen trotzdem. Ein Format-Feld gibt es nicht (immer hh:mm). Die Sonnenposition kommt aus der Uhrzeit des anzeigenden Geraets, nicht aus Symcon.","groesse":[320,180],"demo":{"varId":40329,"varId2":16467,"showTime":true,"showNight":true,"label":"Sonnenbogen"}},
    "sval": {"titel":"Statistik","zweck":"Zeigt Minimum, Mittelwert und/oder Maximum einer geloggten Variablen ueber eine Periode (Minute bis Jahr). Die Werte kommen zeitgewichtet aus dem Symcon-Archiv (Server-Endpunkt ?api=agg), nicht aus eigener Rechnung.","funktionen":[{"name":"Variable","beschreibung":"Standardvariable, deren Archivdaten ausgewertet werden. Muss geloggt sein."},{"name":"Aggregationsstufe","beschreibung":"cmpStage – Periode der Auswertung: minuetlich, stuendlich, taeglich, woechentlich, monatlich, jaehrlich. Die laufende Periode erscheint als Zusatz im Label."},{"name":"Werte (Min / Ø / Max)","beschreibung":"statMin / statAvg / statMax – beliebige Kombination. Bei mehreren Werten steht jeder mit kleiner Vorsatzmarke in einer Zeile und die Schrift wird kleiner. Ohne Auswahl wird Ø gezeigt."},{"name":"Einheit","beschreibung":"unit – Freitext, wird hinter jede Zahl gesetzt (z. B. °C, kWh)."},{"name":"Wert-Größe","beschreibung":"valfs – feste Schriftgroesse der Zahl in px; leer = automatisch (groesser bei einem Wert, kleiner bei mehreren)."},{"name":"Ausrichtung","beschreibung":"align – Label und Wert links, zentriert oder rechts."},{"name":"Farbe nach Schwelle","beschreibung":"colThr schaltet die Wertfaerbung ein: bis „Grün bis“ (t1) gruen, bis „Gelb bis“ (t2) warm/gelb, darueber rot. „Invertieren“ (thrInvert) dreht die Reihenfolge um."},{"name":"Präfix / Suffix / Nachkommastellen","beschreibung":"pre/suf setzen Zeichen vor bzw. nach die Zahl; dec legt die feste Stellenzahl 0..6 fest (leer = automatisch)."},{"name":"Label / Farben / Rahmen / Typografie","beschreibung":"Beschriftung, Text- und Hintergrundfarbe, Rahmen, deckender oder transparenter Hintergrund, Schriftart/-gewicht/-stil/-groesse."},{"name":"Interaktion / Sichtbarkeit / Animation","beschreibung":"Klick auf Seite oder Popup, Lang-Druck auf zweite Seite/Popup, Skript-ID; Ein-/Ausblenden zur Laufzeit oder per Steuer-Variable; Einblend-Animation, Ebene, Geometrie."},{"name":"Live-Verhalten","beschreibung":"Die Kennzahlen werden per Server-Abfrage geholt und kurz zwischengespeichert; jede Wertaenderung stoesst eine Neuberechnung an."}],"hinweis":"Die Variable muss im Archiv geloggt sein – ohne Logging bleibt die Anzeige auf „–“. Ausgewertet wird die LAUFENDE Periode (heute, diese Woche …), nicht die abgeschlossene. Ein Format-Feld gibt es bei diesem Typ nicht.","groesse":[240,110],"demo":{"varId":26109,"cmpStage":"day","statMin":true,"statAvg":true,"statMax":true,"unit":"°C","dec":1,"label":"Außentemperatur"}},
    "switch": {"titel":"Schalter","zweck":"Schalter mit zwei Modi: Toggle (klassischer Ein/Aus-Schieber fuer eine boolesche Variable) und Multi-State (Mehrpositions-Schieber im Toggle-Stil fuer eine Integer-Variable). Klick schaltet bzw. setzt den Wert, die Stellung folgt live.","funktionen":[{"name":"Modus","beschreibung":"swMode – „Toggle (Ein/Aus, Bool)“ (Vorgabe) oder „Multi-State (Schieber, Integer)“ fuer eine Integer-Variable mit mehreren Zustaenden."},{"name":"Variable","beschreibung":"Toggle: boolesche (oder 0/1-) Variable, Klick schreibt den invertierten Zustand. Multi-State: Integer-Variable; ein Klick auf ein Segment schreibt dessen Wert (setVar/RequestAction)."},{"name":"Multi-State: Zustände","beschreibung":"Ohne eigene Liste kommen die Zustaende aus den Profil-Zuordnungen der Variable (Wert/Text/Icon/Farbe via ?api=assoc) und folgen dem Profil. Eine gefuellte Liste states (Wert · Text · Icon · Farbe) ueberschreibt das Profil IMMER; der aktive Zustand faerbt den gleitenden Knopf, toent die Spur und passt die Textfarbe lesbar an."},{"name":"Multi-State: Rundung","beschreibung":"swmShape – Form von Track und Knopf: Pille (Vorgabe), Abgerundet oder Eckig."},{"name":"Ein-Farbe / Aus-Farbe","beschreibung":"swOn / swOff – Skin-Farben des Toggle-Schiebers je Zustand. Ein faerbt Knubbel, Rahmen und Spur, Aus nur den Knubbel."},{"name":"Ein-Icon / Aus-Icon","beschreibung":"swOnIcon / swOffIcon – je ein kleines Symbol im Knubbel, das abhaengig vom Zustand eingeblendet wird (z. B. Gluehbirne an/aus); waehlbar und entfernbar."},{"name":"Label / Icon","beschreibung":"Beschriftung links neben dem Schieber (Vorgabetext „Schalter“); ein optionales Icon (icon) steht davor, mit einstellbarer Icon-Farbe."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Text- und Hintergrundfarbe der Kachel, Rahmen, transparenter Hintergrund, mehrzeilige Beschriftung, Schriftart/-gewicht/-stil/-groesse."},{"name":"Interaktion / Sichtbarkeit / Animation","beschreibung":"Seite oeffnen, Popup oeffnen/schliessen, Skript-ID, Lang-Druck (550 ms) auf Seite/Popup; Anzeige im Betrieb, Steuer-Variable mit Vergleich, Einblend-Animation, Ebene, Geometrie."},{"name":"Live-Verhalten","beschreibung":"Der Schieber springt bei jedem eingehenden Wert auf den tatsaechlichen Zustand; beim Klick wird die Stellung sofort vorweggenommen und danach vom Live-Wert bestaetigt."}],"hinweis":"Ist unter Interaktion ein Popup, eine Skript-ID oder eine Seite hinterlegt, hat das Vorrang: der Klick navigiert bzw. startet das Skript und schaltet NICHT mehr. Geschaltet wird nur im Bedien-/Run-Modus. Wer alle Optionen als Knopfreihe oder Klappliste statt als Schieber will, nutzt das Auswahl-Widget (select) – es teilt sich den Schieber-Code mit dem Schalter.","groesse":[220,64],"demo":{"varId":30519,"label":"Licht Lesezimmer","icon":"bulb","iconColor":"accent","swOn":"ok","swOff":"muted","swOnIcon":"lighton","swOffIcon":"lightoff"}},
    "table": {"titel":"Tabelle","zweck":"Zeigt den Inhalt einer Text-Variablen als sortierbare Datentabelle mit Kopfzeile, Blaetterfunktion und alternativer Kartenansicht. Erwartet ein Array im Format [Zeile][Spalte], wobei Zeile 0 die Spaltenkoepfe liefert.","funktionen":[{"name":"Variable","beschreibung":"Text-Variable mit JSON oder serialisiertem PHP-Array. Zeile 0 liefert die Spaltenkoepfe, alle weiteren Zeilen die Daten. JSON wird direkt aus dem Live-Wert geparst, alles andere (z. B. serialisiertes PHP) ueber den Server-Endpunkt ?api=tabledata geholt."},{"name":"Label","beschreibung":"Titel im Kopfbereich der Tabelle (Vorgabe 'Tabelle'); darunter steht automatisch die Anzahl der Eintraege ('n Eintraege')."},{"name":"Zeilen/Seite","beschreibung":"pageSize — Groesse einer Seite (Vorgabe 10); 0 schaltet die Blaetterfunktion ab. Bei mehr Zeilen als pageSize erscheinen rechts oben die Pfeile mit Bereichsanzeige ('1–5 von 9')."},{"name":"Start-Ansicht","beschreibung":"tblView — 'table' (Raster mit Kopfzeile) oder 'cards' (je Zeile eine Karte mit Feldname/Wert-Paaren)."},{"name":"Umschalter ausblenden","beschreibung":"hideToggle — entfernt die Segmentschalter Tabelle/Karten, die Start-Ansicht wird damit fest."},{"name":"Status-Stil","beschreibung":"sevStyle — Severity-Darstellung: erkennt automatisch eine Spalte mit Namen wie 'Status'/'Zustand' und eine mit 'Wert'/'Ladung'/'Prozent'/'%'. Die Status-Spalte bekommt einen farbigen Chip (ok/warn/crit) und die Zeile einen Severity-Streifen, die %-Spalte einen Mini-Ladebalken. Schweregrad wird aus dem Zellentext abgeleitet (leer/kritisch = crit, bald/mittel/niedrig = warn, ok/voll/gut = ok)."},{"name":"Spalte: Ausrichtung","beschreibung":"colAlign[ci] — pro Spalte Standard, Links, Zentriert oder Rechts. Der Spalten-Editor erscheint erst, sobald Daten geladen sind, und zeigt je Spalte den Kopftext."},{"name":"Spalte: Breite","beschreibung":"colW[ci] — feste Spaltenbreite: reine Zahl = Pixel, oder mit Einheit (z. B. 20%). Leer = automatisch. Nicht gesetzte Spalten bleiben inhaltsbasiert; Platz wird nur der breitesten (flexiblen) Spalte entzogen, die als einzige umbrechen darf, damit die Tabelle ohne Scrollen in die Breite passt."},{"name":"Spalte: HTML","beschreibung":"colRaw[ci] — Zellinhalt dieser Spalte wird als Roh-HTML gerendert statt escaped (z. B. <img>, <span style>). Nur bei vertrauenswuerdiger Quelle nutzen."},{"name":"Sortieren (Klick)","beschreibung":"Klick auf einen Spaltenkopf sortiert aufsteigend, erneuter Klick dreht die Richtung. Reine Zahlen werden numerisch verglichen, alles andere natuerlich sortiert (localeCompare, numeric); die Blaetterposition springt auf Seite 1."},{"name":"Ansicht umschalten (Klick)","beschreibung":"Die Schalter Tabelle/Karten wirken direkt im Betrieb, ohne die gespeicherte Start-Ansicht zu aendern."},{"name":"Zahlenspalten","beschreibung":"Spalten, in denen ALLE Datenzeilen als Zahl erkannt werden, werden automatisch in Festbreitenschrift (Mono) gesetzt."},{"name":"Farben / Rahmen / Typografie / Sichtbarkeit / Animation","beschreibung":"Die gemeinsamen Eigenschaften greifen wie bei allen Widgets: Farben, Rahmen (frame), Hintergrund, Schrift, Ein-/Ausblenden per Steuer-Variable, Einblend-Animation, Ebene und Geometrie."},{"name":"Live-Verhalten","beschreibung":"Aendert sich die Variable, wird die Tabelle um 300 ms entprellt neu geladen; Sortierung und Seitenzahl bleiben erhalten."}],"hinweis":"Die Quelle muss ein Array von Zeilen-Arrays sein. Ein serialisiertes PHP-Array aus assoziativen Zeilen laeuft ueber den Server-Endpunkt und wird auf reine Werte reduziert — die Spaltennamen gehen dabei verloren, und der erste Datensatz wird als Kopfzeile verbraucht. Ein JSON-Array aus Objekten wird direkt im Browser geparst und dabei NICHT zerlegt: jede Zeile schrumpft auf eine einzige Zelle '[object Object]'. Der Spalten-Editor (Ausrichtung/Breite/HTML) erscheint erst, wenn Daten geladen sind — also zuerst die Variable waehlen.","groesse":[470,300],"demo":{"varId":39594,"label":"Regen Daten","pageSize":5,"tblView":"table"}},
    "tempbar": {"titel":"Temp-Säule","zweck":"Vertikale Temperatursaeule mit Skalenendwerten, Sollwert-Marke und Status-Badge. Der Fuellstand ergibt sich aus dem Messwert zwischen Min und Max.","funktionen":[{"name":"Variable","beschreibung":"Temperatur-Variable; ihr formatierter Wert steht oben, die Fuellhoehe folgt dem Rohwert."},{"name":"Min / Max","beschreibung":"min / max — Skalenanfang und -ende (Vorgabe 16 und 24). Max steht oben, Min unten neben der Saeule; beide begrenzen die Fuellung."},{"name":"Soll","beschreibung":"soll — gestrichelte Querlinie in der Saeule an der Position des Sollwerts (Eingabe in 0,5er-Schritten, Vorgabe 22). Reine Anzeige, schreibt nichts zurueck."},{"name":"Badge","beschreibung":"pill — Freitext fuer die Pille unter der Zone (Vorgabe 'Komfort'); leerer Text blendet sie aus."},{"name":"Status","beschreibung":"pillState — Farbe der Badge: OK (ok, gruen), Warnung (warn), Kritisch (crit), An (on, Akzent), Aus (off, blass)."},{"name":"Warm","beschreibung":"warm — faerbt die Saeulenfuellung im warmen Verlauf statt im Akzentverlauf."},{"name":"Label","beschreibung":"Zonenname unter der Saeule (Vorgabe 'EG')."},{"name":"Nachkommastellen","beschreibung":"dec — gemeinsame Formatoption fuer die Zahl ueber der Saeule; leer = formatierter Wert aus dem Variablenprofil."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Gestaltung: Text- und Hintergrundfarbe, Rahmen, transparenter Hintergrund, mehrzeilige Beschriftung, Schrifteinstellungen."},{"name":"Interaktion / Sichtbarkeit / Animation / Geometrie","beschreibung":"Klick auf Seite oder Popup, Lang-Druck, Skript-ID, Ein-/Ausblenden zur Laufzeit oder per Steuer-Variable, Animation, Ebene, X/Y/Breite/Hoehe."},{"name":"Live-Verhalten","beschreibung":"Bei jedem neuen Wert (auch beim Aufbau aus dem Cache) werden Zahltext und Fuellhoehe gesetzt; die Fuellung animiert in 0,4 s auf die neue Hoehe."}],"hinweis":"Liegt der Messwert ausserhalb von Min/Max, wird die Fuellung auf 0 bzw. 100 Prozent begrenzt — die Skala also passend zum Messbereich waehlen. Die Soll-Marke ist reine Anzeige. Ein Format-Feld (Uhrzeit/Prozent/kW ...) bietet dieses Widget NICHT an, nur Nachkommastellen.","groesse":[140,220],"demo":{"varId":26109,"min":10,"max":40,"soll":24,"pill":"Mild","pillState":"ok","warm":true,"dec":1,"label":"Außen"}},
    "text": {"titel":"Text","zweck":"Statische Textzeile fuer Ueberschriften, Zwischentitel und Erklaerungen. Zeigt keinen Variablenwert an.","funktionen":[{"name":"Label","beschreibung":"Der dargestellte Text (Vorgabe 'Text'). Ein \\n im Text erzwingt an dieser Stelle einen Zeilenumbruch."},{"name":"Text oben","beschreibung":"vtop — richtet mehrzeiligen Text am oberen Rand aus statt senkrecht zentriert. Bei kurzem Text wirkt Zentrierung gut, bei langem Text laesst sie oben/unten Luecken."},{"name":"Typografie","beschreibung":"Schriftart (Standard, Sans, Serif, Mono, Segoe/Arial, Courier, Verdana), Gewicht 300..800, Kursiv und Schriftgroesse in px — damit werden Ueberschriften und Fliesstext unterschieden."},{"name":"Farben","beschreibung":"Textfarbe und Hintergrundfarbe, mit Reset-Knopf."},{"name":"Hintergrund / Rahmen","beschreibung":"Hintergrund deckend oder transparent (bgT, fuer freistehende Ueberschriften) und Rahmen an, aus oder Ansicht-Standard."},{"name":"Interaktion","beschreibung":"Auch ohne Variable klickbar: Seite oeffnen, Popup oeffnen oder schliessen, Skript per Skript-ID starten; Lang-Druck (550 ms) fuehrt auf eine zweite Seite oder in ein zweites Popup."},{"name":"Sichtbarkeit","beschreibung":"'Zur Laufzeit' blendet den Text im Betrieb aus; ueber eine Steuer-Variable mit Vergleich (wahr, =, !=, >=, <=) laesst er sich zustandsabhaengig einblenden."},{"name":"Name / Laufzeile","beschreibung":"Ueber den Namen ist das Element referenzierbar; liegt auf der Seite eine Laufzeile (ticker), erscheint zusaetzlich ein Knopf zum Verschieben in die Laufzeile und zurueck."},{"name":"Animation / Ebene / Geometrie","beschreibung":"Einblend-Animation (Fade, Scale, SlideUp), nach vorn/hinten legen, X, Y, Breite und Hoehe."}],"hinweis":"Das Widget hat bewusst kein Variablenfeld — fuer angezeigte Messwerte ist das Wert-Widget zustaendig. Der allgemeine Schalter 'Beschriftung mehrzeilig' wirkt hier nicht; steuere die vertikale Lage stattdessen ueber 'Text oben'. Fuer mehrere Zeilen genug Hoehe einplanen.","groesse":[260,80],"demo":{"label":"Wohnzimmer\nÜbersicht der wichtigsten Werte","fsz":18,"fwt":"600","bgT":true}},
    "textbox": {"titel":"Eingabe","zweck":"Ein Text-Eingabefeld, das den Wert einer Variablen anzeigt und die Benutzereingabe zurueckschreibt. Wahlweise einzeilig, mehrzeilig oder als Passwortfeld.","funktionen":[{"name":"Variable","beschreibung":"Ziel-Variable. Ihr Rohwert wird beim Aufbau in das Feld geschrieben; die Eingabe wird beim Verlassen des Feldes bzw. mit Enter (change-Ereignis) per setVar dorthin zurueckgeschrieben."},{"name":"Label","beschreibung":"Wird NICHT als Beschriftung gezeichnet, sondern als Platzhaltertext im leeren Feld angezeigt. Ein \\n wird hier nicht in einen Umbruch umgesetzt."},{"name":"Mehrzeilig","beschreibung":"multi — schaltet von <input> auf <textarea> um (Textfeld statt Zeile, Groessenaenderung durch den Benutzer gesperrt, Schrift 13px statt 14px)."},{"name":"Passwort","beschreibung":"pw — Eingabe verbergen: rendert type=password statt type=text. Nur im einzeiligen Modus wirksam, da das mehrzeilige Feld immer Klartext zeigt."},{"name":"Live-Aktualisierung","beschreibung":"Aendert sich die Variable von aussen, wird der Feldinhalt nachgezogen — aber nur, wenn das Feld gerade NICHT den Fokus hat. Eine laufende Eingabe wird nicht ueberschrieben."},{"name":"Schreiben nur im Betrieb","beschreibung":"Der Eingabe-Handler laeuft nur ausserhalb des Bearbeiten-Modus. Im Editor ist das Feld sichtbar, schreibt aber nicht."},{"name":"Farben / Rahmen / Hintergrund","beschreibung":"Gemeinsame Eigenschaften. Sie greifen hier kaum: Das Feld liegt deckend ueber der ganzen Kachel und zeichnet einen eigenen Rahmen in --line, --surface-2 als Fuellung und feste Textfarbe --text. Nur 'Hintergrund transparent' wirkt und nimmt dem Feld Fuellung und Rahmen."},{"name":"Typografie","beschreibung":"Schriftart, Gewicht, Stil und Schriftgroesse. Ohne eigene Wahl nutzt das Feld die Schriftart der Ansicht (--fu); eine gesetzte Typografie wird auf das Eingabefeld durchgereicht und ueberschreibt auch die 13/14px."},{"name":"Interaktion","beschreibung":"Seite oeffnen, Lang-Druck auf Seite/Popup, Popup oeffnen, Popup schliessen, Skript-ID. Achtung — diese Aktionen feuern auch beim Antippen des Eingabefeldes."},{"name":"Sichtbarkeit / Animation / Ebene / Geometrie","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, in Laufzeile verschieben, Einblend-Animation, Z-Reihenfolge, X/Y/Breite/Hoehe."}],"hinweis":"Schreibt in die gebundene Variable, sobald das Feld verlassen wird. Der Server wandelt den Text in den Variablentyp um und schreibt per RequestAction (falls Aktion hinterlegt), sonst per SetValue. Das Label ist der Platzhalter, nicht die Beschriftung.","groesse":[240,90],"demo":{"varId":26237,"label":"Text eingeben","multi":false}},
    "thermostat": {"titel":"Thermostat","zweck":"Heizungs-/Klimakarte mit Ist- und Solltemperatur, Balken mit Soll-Marke, Betriebszustand (heizt/kuehlt/bereit/Aus), Modus-Buttons aus dem Variablenprofil und +/- Steller fuer den Sollwert.","funktionen":[{"name":"Variable","beschreibung":"Ist-Temperatur (varId). Bestimmt die grosse Zahl links und die Fuellbreite des Balkens."},{"name":"Ziel-Var","beschreibung":"Sollwert-Variable (varId2). Wird als 'Soll' oben und im Steller unten angezeigt und von den +/- Buttons beschrieben."},{"name":"Modus/Profil-Var","beschreibung":"Optionale Modus-Variable (varId3). Aus ihren Profil-Assoziationen werden automatisch die Modus-Buttons erzeugt; der aktive Modus wird hervorgehoben."},{"name":"Min / Max","beschreibung":"Skala des Balkens (Vorgabe 14 bis 28). Ist-Fuellung und Soll-Marke werden in diesen Bereich eingepasst und gekappt."},{"name":"Schritt","beschreibung":"step — Schrittweite der +/- Buttons (Vorgabe 0,5). Der neue Sollwert wird mit einer Nachkommastelle geschrieben."},{"name":"Heizstatus","beschreibung":"showState — Element abschaltbar: die Statuszeile oben rechts mit Icon und Text (heizt / kuehlt / bereit / Aus)."},{"name":"Ist/Soll-Balken","beschreibung":"showBar — Element abschaltbar: der Fortschrittsbalken mit der senkrechten Soll-Marke."},{"name":"Modus-Buttons","beschreibung":"showModes — Element abschaltbar: die Buttonzeile mit den Profil-Modi. Ein Klick schreibt den Assoziationswert in die Modus-Variable."},{"name":"+/- Steller","beschreibung":"showSet — Element abschaltbar: die untere Zeile mit Minus, Sollwert und Plus. Ein Klick veraendert den Sollwert um die Schrittweite."},{"name":"Zustandsfaerbung (automatisch)","beschreibung":"Aus dem Modusnamen abgeleitet: enthaelt er aus/off gilt Ton 'off' (blass); enthaelt er kuehl/cool und Ist liegt >0,1 ueber Soll gilt 'cool' (blau); sonst heizt-Logik — Ist >0,1 unter Soll ergibt 'heat' (warm). Heat/Cool legen einen farbigen Rahmenschimmer ueber die Karte, sonst 'idle' (bereit). Ohne Modus-Variable greift immer die heizt-Logik. Der Ton faerbt Statustext, Balkenfuellung und aktive Modus-Buttons."},{"name":"Format","beschreibung":"Die gemeinsame Formatwahl wird angeboten, vom Thermostat aber NICHT ausgewertet: Ist- und Sollwert zeigen immer den profilformatierten Text. Nachkommastellen sind fuer diesen Typ nicht einstellbar."},{"name":"Label","beschreibung":"Name oben links; \\n erzwingt einen Zeilenumbruch, 'Beschriftung mehrzeilig' laesst ihn umbrechen statt abschneiden."},{"name":"Live-Aktualisierung","beschreibung":"Jede Aenderung an Ist-, Soll- oder Modus-Variable zeichnet die Karte sofort neu (Werte, Balken, Ton, aktiver Modus)."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Gestaltung: Vorder- und Hintergrundfarbe, Rahmen, transparenter Hintergrund, Schriftart/Gewicht/Stil/Groesse."},{"name":"Interaktion","beschreibung":"Seite oeffnen, Popup oeffnen, Lang-Druck auf Seite/Popup, Popup schliessen, Skript-ID. Achtung: diese Aktionen werden ZUERST ausgewertet — ist eine gesetzt, verschlucken sie auch die Klicks auf Modus-Buttons und +/-, die Karte laesst sich dann nicht mehr bedienen."},{"name":"Sichtbarkeit / Animation / Ebene / Geometrie","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, in Laufzeile verschieben, Einblend-Animation, Z-Reihenfolge, X/Y/B/H."}],"hinweis":"Die Modus-Buttons entstehen ausschliesslich aus den Assoziationen des Profils der Modus-Variablen — ohne Profil mit Zuordnungen bleibt die Zeile leer. Der Sollwert wird nur ausserhalb des Bearbeiten-Modus geschrieben; die +/- Buttons ueberschreiben die Ziel-Variable per SetValue.","groesse":[270,215],"demo":{"varId":26109,"varId2":41522,"min":14,"max":35,"step":0.5,"label":"Wohnzimmer","showState":true,"showBar":true,"showModes":false,"showSet":true}},
    "heatplan": {"titel":"Heizplan","zweck":"Voll interaktiver Wochen-Temperaturplan der HomeMatic-Heizungssteuerung: Raum waehlen, Praesenz-Profil (Normal/Erweitert/Abgesenkt) umschalten, Tages-Sollkurve mit ziehbaren Griffen bearbeiten, Wochenuebersicht anspringen, Slots per Stepper feinjustieren, auf andere Tage uebertragen und mit einem Klick ans Thermostat speichern.","funktionen":[{"name":"Datenquelle (Root-ID)","beschreibung":"Wurzel-Objekt der Heizungssteuerung im Panel einstellbar (leer = Standard #53700). Die Raumliste wird live von dieser Wurzel geholt."},{"name":"Raeume & Gruppen (Liste)","beschreibung":"Zeilen-Editor: pro Zeile ein darzustellender Raum (Root-Variable) + Etage EG/OG/DG (EG = Firma). \"+ Raum\", Vorlagen \"Firma -> EG\" und \"Alle Raeume\". Die Tab-Leiste gruppiert nach Etage."},{"name":"Farben","beschreibung":"Akzentfarbe des Widgets (Skin-Farbe oder eigene) und die Temperatur-Farbskala (5 Stuetzstellen kuehl->warm) sind im Panel anpassbar; \"Farben zuruecksetzen\" stellt die Vorgabe wieder her."},{"name":"Praesenz-Profil","beschreibung":"Normal / Erweitert / Abgesenkt. Jedes Profil zeigt seinen Wochen-Durchschnitt; das an der Heizung aktive Profil ist mit \"aktiv\" markiert. Umschalten laedt das jeweilige Wochenprofil des Raums."},{"name":"Sollkurve (ziehbar)","beschreibung":"Der gewaehlte Tag als Stufenkurve ueber 24 h. Plateau senkrecht ziehen aendert die Solltemperatur (Raster 0,5 C, 5-30 C), den runden Grenzgriff waagrecht ziehen verschiebt die Slotgrenze (Raster 10 min, durch die Nachbarslots begrenzt). Die \"jetzt\"-Linie zeigt die aktuelle Uhrzeit."},{"name":"Ist/Soll live","beschreibung":"Rechts in der Kurvenlegende: aktuelle Uhrzeit, geplanter Soll-Wert und die vom Thermostat gemessene Ist-Temperatur (ACTUAL_TEMPERATURE), alle 60 s aktualisiert. Reine Ventilantriebe ohne Fuehler (HM-CC-TC) liefern kein Ist - dann entfaellt die Anzeige."},{"name":"Slot-Pillen","beschreibung":"Alle Slots des Tages mit Temperatur und Zeitspanne, nach Solltemperatur eingefaerbt. Anklicken waehlt den Slot fuer den Editor rechts."},{"name":"Wochenuebersicht","beschreibung":"Sieben Streifen Mo-So, je Tag die Slots als Farbband (kuehl gruen bis warm orange) samt Tages-Durchschnitt. Ein Tag anklicken oeffnet ihn zum Bearbeiten."},{"name":"Slot-Editor","beschreibung":"Sollwert (-1 / -0,1 / +0,1 / +1 C), Start und Ende (-1h / -10m / +10m / +1h). Der erste Slot beginnt fix 00:00, der letzte endet fix 24:00. \"+ Einfuegen\" haengt einen Slot an, \"- Loeschen\" entfernt den gewaehlten (mind. 1, max. 24)."},{"name":"Uebertragen","beschreibung":"Den aktuellen Tag auf beliebige andere Wochentage kopieren."},{"name":"Profil speichern","beschreibung":"Prueft die Integritaet und schreibt das Wochenprofil zurueck in die Steuerung; passt es zum aktiven Praesenz-Profil (bzw. bei Geraeten mit drei Speicherprofilen immer), wird es zusaetzlich direkt ans Thermostat uebertragen. Der Knopf leuchtet, sobald ungespeicherte Aenderungen vorliegen."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Gestaltung. Die Temperatur-Farbskala nutzt die Skin-Akzentfarbe und deckt sich mit den bestehenden Heizungs-Anzeigen."},{"name":"Interaktion / Sichtbarkeit / Geometrie","beschreibung":"Gemeinsame Sektionen. Hinweis: gesetzte Klick-Aktionen (Seite/Popup/Skript) koennen mit der Bedienung des Editors kollidieren."}],"hinweis":"Daten und Speichern laufen ueber ?api=heat (Proxy auf das IPS-Skript HM_Heizung_LVB, das die serialisierten HomeMatic-Wochenprofile liest, prueft und schreibt). Diese Doku-Vorschau ist rein lokal: Sie zeigt Beispieldaten, greift NIE auf die echte Steuerung zu und speichert nichts. Tipp fuer eine eigene Vollbild-Seite: in den Seiten-Einstellungen \"Fit sperren\" aktivieren, dann bleibt die Seite am Handy/Tablet immer im skalierten Querformat statt in eine schmale Spalte umzubrechen.","groesse":[960,600],"demo":{"label":"Heizplan","rooms":[{"idx":12,"group":"EG"},{"idx":3,"group":"EG"},{"idx":14,"group":"EG"},{"idx":16,"group":"EG"},{"idx":1,"group":"OG"},{"idx":5,"group":"OG"},{"idx":20,"group":"DG"},{"idx":24,"group":"DG"}]}},
    "rooms": {"titel":"Räume / Zonen (Controller)","zweck":"Steuernder Familien-Baustein: Raum-/Zonen-Tab-Leiste (nach Geschoss gruppiert) plus Titel + Status. Wählt als „Controller“ die aktive Zone/Variante/Tag für ALLE Bausteine mit derselben Session-ID (Heizung, Beschattung & Bewässerung).","funktionen":[{"name":"Session-ID","beschreibung":"Frei wählbare Kennung (Vorgabe „heat“). Gleiche ID = geteilte Bedienung mit curve/week/slots/slotedit/variantbox/transfer/save."},{"name":"Domäne","beschreibung":"heating (Heizung, °C), shading (Beschattung, Position %) oder irrigation (Bewässerung, An/Aus-Zeitplan). Bestimmt Farbskala, Einheit und Datenquelle der ganzen Session; shading/irrigation nutzen fix die HomeSuite-Zonen."},{"name":"Quelle (HomeSuite-Zonen)","beschreibung":"An = Zonen aus den HomeSuite-Modulen (?api=mod). Aus = Legacy-Heizung (?api=heat). Bei Domäne Beschattung/Bewässerung fest an."},{"name":"Steuerung (Root-ID)","beschreibung":"Nur ohne HomeSuite-Zonen: Objekt-ID der Legacy-Heizsteuerung (Vorgabe 53700)."},{"name":"Geschoss (Filter)","beschreibung":"Alle Geschosse oder nur EG/OG/DG. Deaktiviert, wenn Geschoss-Tabs aktiv sind."},{"name":"Geschoss-Tabs","beschreibung":"Eine Seite, Etagen als zusätzliche Tab-Reihe (statt einer Seite je Geschoss). Setzt den festen Geschoss-Filter außer Kraft."},{"name":"Räume/Zonen-Liste","beschreibung":"Listeneditor: welche Zonen/Räume die Leiste zeigt und ihre Etage (EG/OG/DG). Tab-Beschriftung = Raumname (bei mehreren Beschattungen je Raum mit Ausrichtung)."},{"name":"Selektor-Stil","beschreibung":"Einheitlicher Raum-Selektor: Darstellung (Buttons/Pills/Underline) wie in allen Domänen."},{"name":"Haus/Wohnung","beschreibung":"Vorschaltung mehrerer Häuser/Wohnungen (falls vorhanden) über den gemeinsamen Selektor."},{"name":"Reihenfolge & Ausblenden","beschreibung":"Reihenfolge der Räume festlegen und einzelne ausblenden (gemeinsamer Selektor-Editor)."},{"name":"Farbskala (nur Heizung)","beschreibung":"Fünf Stützstellen (≤14/16/19/21/≥23 °C), Zwischenwerte interpoliert, „↺ Standard“ setzt zurück. Gilt session-weit für alle Heizplan-Widgets derselben Session."},{"name":"Verhalten","beschreibung":"Tab-Klick wechselt die Zone für die ganze Session; ungespeicherte Änderungen werden vorher abgefragt. Titelzeile zeigt Zone · Variante · Slots · Ø-Wert · „ungespeichert“."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Position (X/Y/Breite/Höhe), Sichtbarkeit, Einblend-Animation, Ebene."}],"hinweis":"Reiner Frontend-Baustein; lädt/speichert über ?api=mod (HomeSuite) bzw. ?api=heat (Legacy). Die Farbskala erscheint nur in der Domäne Heizung. Doku-Vorschau rein lokal.","groesse":[720,120],"demo":{"session":"heat","rooms":[{"idx":12,"group":"EG"},{"idx":3,"group":"EG"},{"idx":1,"group":"OG"},{"idx":20,"group":"DG"}]}},
    "curve": {"titel":"Sollkurve","zweck":"Familien-Baustein (Heizung, Beschattung & Bewässerung): ziehbare 24h-Kurve der aktiven Zone/Variante. Kopfzeile jetzt/Soll/Ist.","funktionen":[{"name":"Session-ID","beschreibung":"Gleiche Kennung wie die übrigen Familien-Bausteine (rooms/curve/week/slots/…) = gemeinsame Zone/Variante/Tag."},{"name":"Plateau ziehen","beschreibung":"Senkrecht = Wert des Slots (°C bzw. Position %); wirkt sofort in der Session."},{"name":"Grenzgriff ziehen","beschreibung":"Waagrecht = Slot-Grenze (Uhrzeit)."},{"name":"Sonnen-Anker","beschreibung":"An Sonnenereignisse gebundene Grenzen (aus dem Slot-Editor) erscheinen als Marker."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Teilt die Session der Familie. Doku-Vorschau rein lokal.","groesse":[560,320],"demo":{"session":"heat"}},
    "week": {"titel":"Woche","zweck":"Familien-Baustein: Wochenübersicht der aktiven Variante (sieben Farbband-Zeilen, Farbe = Wert je Slot).","funktionen":[{"name":"Session-ID","beschreibung":"Gleiche Kennung wie die übrigen Familien-Bausteine (rooms/curve/week/slots/…) = gemeinsame Zone/Variante/Tag."},{"name":"Tag wählen","beschreibung":"Klick auf eine Zeile setzt den Bearbeitungstag der Session; Ø-Wert je Tag rechts."},{"name":"Farbskala","beschreibung":"Nach Domäne: Temperatur (Heizung) bzw. Position (Beschattung)."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Teilt die Session der Familie. Doku-Vorschau rein lokal.","groesse":[420,240],"demo":{"session":"heat"}},
    "slots": {"titel":"Slots","zweck":"Familien-Baustein: Wochentag-Leiste + Schaltpunkte des Tages als Pillen (Wert + Zeitspanne).","funktionen":[{"name":"Session-ID","beschreibung":"Gleiche Kennung wie die übrigen Familien-Bausteine (rooms/curve/week/slots/…) = gemeinsame Zone/Variante/Tag."},{"name":"Tag","beschreibung":"Wochentag-Leiste Mo–So."},{"name":"Slot-Pille","beschreibung":"Zeigt Wert + Zeitspanne; Klick wählt den Slot für den Slot-Editor."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Teilt die Session der Familie. Doku-Vorschau rein lokal.","groesse":[560,150],"demo":{"session":"heat"}},
    "editor": {"titel":"Editor (kompakt)","zweck":"Kompakt-Baustein: Slot-Editor + Varianten + Übertragen + Speichern in einer Spalte (Heizung, Beschattung & Bewässerung).","funktionen":[{"name":"Session-ID","beschreibung":"Gleiche Kennung wie die übrigen Familien-Bausteine (rooms/curve/week/slots/…) = gemeinsame Zone/Variante/Tag."},{"name":"Enthält","beschreibung":"slotedit (Wert/Zeit/Sonnen-Anker) + variantbox (Präsenz bzw. Plan·Saison) + transfer + Speichern."},{"name":"Empfehlung","beschreibung":"Für neue Seiten die vier Einzel-Bausteine nutzen; der Editor bleibt für Bestandsseiten."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Nicht mehr in der Palette (noPalette). Doku-Vorschau rein lokal.","groesse":[300,780],"demo":{"session":"heat"}},
    "stepper": {"titel":"Stepper","zweck":"Universelles +/--Feld: schreibt eine Variable in Schritten (grob und optional fein) mit Min/Max. Zeigt den formatierten Wert; optional laesst sich der Wert direkt eintippen. Verallgemeinert die +/--Logik von Thermostat und Heizplan.","funktionen":[{"name":"Variable","beschreibung":"Die zu stellende Variable. Ein Klick liest den aktuellen Wert, addiert/subtrahiert den Schritt und schreibt (setVar: RequestAction, sonst SetValue). Ohne aktuellen Wert startet der Stepper bei Min."},{"name":"Direkt eintippen","beschreibung":"typein – macht die Wertanzeige zu einem Eingabefeld: Zahl (auch mit Komma) tippen, Enter oder Verlassen schreibt sie (auf Min/Max begrenzt)."},{"name":"Min","beschreibung":"min – untere Grenze; leer = keine Grenze."},{"name":"Max","beschreibung":"max – obere Grenze; leer = keine Grenze."},{"name":"Schritt grob","beschreibung":"step – Schrittweite der aeusseren Knoepfe (Vorgabe 1); die Knopfbeschriftung zeigt den Wert mit Komma."},{"name":"Schritt fein","beschreibung":"stepFine – optionaler feiner Schritt; ist er gesetzt, erscheinen zusaetzliche innere Knoepfe (leer = aus)."},{"name":"Wert & Format","beschreibung":"Gemeinsame Format-Einstellungen wirken auf die Anzeige: Nachkommastellen, Praefix/Suffix (Einheit), Faktor/Skalierung, Tausendertrennung."},{"name":"Interaktion / Sichtbarkeit / Gestaltung","beschreibung":"Label, Farben, Rahmen, Hintergrund, Typografie, Sichtbarkeit ueber Steuer-Variable, Einblend-Animation, Ebene und Geometrie wie bei allen Widgets."}],"hinweis":"Die Schrittweite bestimmt die Genauigkeit der Rundung (Nachkommastellen des Schritts). Beim Eintipp-Modus wird der Wert erst nach Enter/Verlassen geschrieben, damit die Eingabe nicht live ueberschrieben wird.","groesse":[220,72],"demo":{"label":"Sollwert","varId":900001,"min":15,"max":30,"step":1,"stepFine":0.5,"suffix":" °C","dec":1}},
    "weekstrip": {"titel":"Wochen-Streifen","zweck":"Kompakte Nur-Anzeige eines Symcon-Wochenplans: sieben Tageszeilen als Farbband aus den Aktionen (Name+Farbe) plus jetzt-Marke am heutigen Tag. Der Anzeige-Begleiter zum Wochenplan-Editor (weekedit).","funktionen":[{"name":"Plan waehlen","beschreibung":"Im Panel wird der Wochenplan (Ereignis) aus der Liste aller Wochenplaene gewaehlt; Farben und Aktionen kommen aus dem Plan."},{"name":"Farbbaender","beschreibung":"Je Tag die Schaltpunkte als farbige Segmente ueber 24 Stunden; die aktuelle Uhrzeit als senkrechte Marke am heutigen Tag."},{"name":"Titel zeigen","beschreibung":"showTitle — Kopfzeile mit Planname und aktuell gueltiger Aktion ein-/ausblenden."},{"name":"Legende zeigen","beschreibung":"showLegend — die Legende mit Aktionen und Farbe ein-/ausblenden."},{"name":"Verhalten: Aktualisierung","beschreibung":"Der Plan wird beim Aufbau geladen und danach im Minutentakt neu geholt (nur Anzeige, kein Bearbeiten)."}],"hinweis":"Nur-Anzeige — bearbeiten mit dem Wochenplan-Editor (weekedit). Lesen ueber ?api=week. Doku-Vorschau rein lokal.","groesse":[340,190],"demo":{"label":"Filterzeiten","eventId":900801}},
    "slotedit": {"titel":"Slot-Editor (HomeSuite)","zweck":"Familien-Baustein: bearbeitet den gewählten Schaltpunkt der aktiven Zone/Variante.","funktionen":[{"name":"Session-ID","beschreibung":"Gleiche Kennung wie die übrigen Familien-Bausteine (rooms/curve/week/slots/…) = gemeinsame Zone/Variante/Tag."},{"name":"Wert (Stepper)","beschreibung":"−1 / −0,1 / +0,1 / +1 je Domäne (°C bzw. %)."},{"name":"Start/Ende (Stepper)","beschreibung":"−1h / −10m / +10m / +1h verschieben die Grenzen."},{"name":"Uhrzeit ↔ Sonne","beschreibung":"Ende-Grenze umschalten: feste Uhrzeit ODER Sonnenereignis."},{"name":"Sonnen-Anker + Offset","beschreibung":"Bei Sonne: Ereignis (Aufgang/Untergang/Dämmerung civil/nautisch/astro) + ±Minuten; aufgelöste Uhrzeit wird angezeigt."},{"name":"Einfügen / Löschen","beschreibung":"Slot hinzufügen oder entfernen."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Teilt die Session der Familie. Doku-Vorschau rein lokal.","groesse":[300,360],"demo":{"session":"dokuheat"}},
    "variantbox": {"titel":"Varianten (HomeSuite)","zweck":"Familien-Baustein: wählt die aktive Zeitplan-Variante.","funktionen":[{"name":"Session-ID","beschreibung":"Gleiche Kennung wie die übrigen Familien-Bausteine (rooms/curve/week/slots/…) = gemeinsame Zone/Variante/Tag."},{"name":"Variante wählen","beschreibung":"Heizung = Präsenz (Normal/Erweitert/Abgesenkt); Beschattung = Plan · Saison (Anwesend/Abwesend/Urlaub × Sommer/Winter)."},{"name":"Aktiv-Markierung","beschreibung":"Die real aktive Variante ist als „aktiv“ hervorgehoben; Ø-Wert je Variante rechts."},{"name":"Schutz","beschreibung":"Rückfrage vor dem Wechsel, wenn ungespeicherte Änderungen bestehen."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Teilt die Session der Familie. Doku-Vorschau rein lokal.","groesse":[300,180],"demo":{"session":"dokuheat"}},
    "transfer": {"titel":"Übertragen (HomeSuite)","zweck":"Familien-Baustein: überträgt Zeitpläne innerhalb der Woche oder aus einer anderen Zone.","funktionen":[{"name":"Session-ID","beschreibung":"Gleiche Kennung wie die übrigen Familien-Bausteine (rooms/curve/week/slots/…) = gemeinsame Zone/Variante/Tag."},{"name":"Tag kopieren","beschreibung":"Zieltage (Di–So) ankreuzen, „Auf gewählte Tage übertragen“ dupliziert den aktuellen Tag."},{"name":"Woche übernehmen","beschreibung":"Quell-Zone + Quell-Variante wählen, „Übernehmen“ kopiert die ganze Woche."},{"name":"Schutz","beschreibung":"Rückfrage bei ungespeicherten Änderungen."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Teilt die Session der Familie. Doku-Vorschau rein lokal.","groesse":[300,230],"demo":{"session":"dokuheat"}},
    "save": {"titel":"Speichern (HomeSuite)","zweck":"Familien-Baustein: persistiert den bearbeiteten Plan der aktiven Zone/Variante (schreibt über ?api=mod) und lädt frisch nach.","funktionen":[{"name":"Session-ID","beschreibung":"Gleiche Kennung wie die übrigen Familien-Bausteine (rooms/curve/week/slots/…) = gemeinsame Zone/Variante/Tag."},{"name":"Speichern","beschreibung":"Schreibt die aktive Variante dauerhaft."},{"name":"Ungespeichert-Anzeige","beschreibung":"Der Knopf hebt sich hervor, solange ungespeicherte Änderungen bestehen."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Teilt die Session der Familie. Doku-Vorschau rein lokal (speichert nichts).","groesse":[300,54],"demo":{"session":"dokuheat"}},
    "homesuite": {"titel":"HomeSuite Uebersicht","zweck":"Manifest-getriebene Suite-Uebersicht: holt ueber den Hub das Aggregat-Manifest und rendert Hub-Status plus alle Entitaeten (Heizung/Beschattung/Audio/Bewaesserung) generisch, unabhaengig von der Domaene.","funktionen":[{"name":"Kopf / Label","beschreibung":"Kopfzeile mit dem Widget-Label (Vorgabe 'HomeSuite') und der Zahl der erkannten Entitaeten."},{"name":"Entitaeten-Kacheln","beschreibung":"Rasterkacheln je Entitaet aus dem Objektbaum (Status-Punkt, Name, Domaene und Instanz-ID). Datenweg ist der Lese-Endpunkt ?api=mod&op=entities ueber den gecachten/gepollten Panel-Transport."},{"name":"Zustandsboxen","beschreibung":"Zeigt Lade-, Leer- und Fehlerzustaende (kein Hub angelegt, Modul nicht erreichbar) als eigene Hinweisbox statt einer leeren Kachel."},{"name":"Keine eigenen Parameter","beschreibung":"Rein manifest-getrieben; Bedienung/Verwaltung erfolgt ueber die Zeitplan- und Navigations-Widgets. In der Doku wird eine statische Demo ohne Fetch gezeigt."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Hoehe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Braucht den HomeSuite-Hub. Uebersicht/Diagnose; die Live-Daten kommen ueber ?api=mod&op=entities (alle 8 s gepollt). Ist kein Hub angelegt, weist die Kachel darauf hin.","groesse":[420,320],"demo":{}},
    "roomnav": {"titel":"Raum-Navigation","zweck":"Universelle Navigations-/Tab-Leiste aus dem HomeSuite-RoomManager: holt die Topologie (Haus › Bereich/Geschoss › Raum) und blendet die gewählten Räume als Tabs bzw. Liste ein. Ein Klick navigiert zur zugeordneten Seite — unabhängig von den Zeitplan-Widgets einsetzbar.","funktionen":[{"name":"Geschoss/Bereich","beschreibung":"Alle Bereiche oder auf einen Bereich (EG/OG/DG/Garten …) einschränken. Räume direkt unterm Haus erscheinen als Pseudo-Bereich."},{"name":"Räume (an/aus)","beschreibung":"Checkbox-Liste: welche Räume des Bereichs die Leiste zeigt. Reihenfolge folgt dem Baum. Schnellwahl „Alle“ / „Keine“; alle an = die Auswahl wird geleert (zeigt automatisch alles)."},{"name":"Seiten-Zuordnung","beschreibung":"Je Raum wählbar, welche View der Klick öffnet. Ohne Zuordnung wird die gleichnamige Seite (Raumname) angesteuert; existiert keine, ist der Tab inaktiv („Keine Seite zugeordnet“)."},{"name":"Ausrichtung","beschreibung":"Tabs (horizontal) oder Liste (vertikal)."},{"name":"Aktiv-Stil","beschreibung":"Indikator (Unterstrich, beste Lesbarkeit — Vorgabe) oder Gefüllt (kontrastsichere Textfarbe via _contrastText). Nie Schrift direkt auf gesättigtem Akzent."},{"name":"Beschriftung","beschreibung":"Voller Raumname oder Kürzel (Abbr aus dem RoomManager)."},{"name":"Icons","beschreibung":"Raum-Icons an/aus."},{"name":"Akzentfarbe","beschreibung":"Skin-Farbe für den aktiven Eintrag; die kontrastsichere Textfarbe des gefüllten Tabs wird daraus abgeleitet."},{"name":"Aktiv-Markierung","beschreibung":"Der Tab der aktuell offenen Seite (store.current) wird hervorgehoben."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Liest die Struktur aus der HomeSuite-Topologie (?api=mod&op=topology), gecached mit seltener 15s-Aktualisierung. Ohne erreichbaren HomeSuite-Hub bleibt die Leiste leer („Topologie nicht erreichbar“). Doku-Vorschau rein lokal.","groesse":[560,60],"demo":{}},
    "zonesync": {"titel":"Zonen-Sync","zweck":"Kleines, domaenen-agnostisches Widget: zeigt den Sync-Status Geraet ⟷ Modul einer HomeSuite-Zone (Modul-Wochenplan gegen Live-Geraeteprogramm) und bietet 'Vom Geraet laden' / 'Ans Geraet schreiben'. Funktioniert fuer Heizung, Beschattung usw. gleichermassen.","funktionen":[{"name":"Modus","beschreibung":"bind — Session (folgt der gewaehlten Zone der heatplan-Familie ueber die gemeinsame Session-ID) oder feste Zone (fuer Live-View/Raum-Karten)."},{"name":"Session-ID","beschreibung":"session — bei Modus Session: an welche Familie gekoppelt (Vorgabe 'heat')."},{"name":"Zone (Instanz-ID)","beschreibung":"entityId — bei fester Zone: Instanz-ID der Heizung/Beschattung usw."},{"name":"Akzentfarbe","beschreibung":"accent — Skin-Farbe der Statuschips/Aktionen."},{"name":"Status & Aktionen","beschreibung":"Chip zeigt 'synchron' oder 'abweichend' (plus Varianten-Name). 'Vom Geraet' laedt das aktuelle Geraeteprogramm in den Editor, 'Ans Geraet' schreibt den Modul-Plan zurueck (Backup/Verify). Bei controller-Zonen ohne Geraeteprogramm steht 'Modul steuert laufend'; nicht erreichbar wird gesondert gemeldet."},{"name":"Verhalten: Aktualisierung","beschreibung":"Der Sync-Status wird beim Aufbau und danach alle 20 s ueber ?api=mod&op=manage (syncStatus) neu geholt."}],"hinweis":"Bedient ?api=mod (syncStatus/loadFromDevice/syncToDevice), token-geschuetztes Schreiben. Nur relevant bei Treibern mit eigenem Geraeteprogramm (scheduleMode 'device'). Doku-Vorschau rein lokal.","groesse":[300,150],"demo":{"session":"heat"}},
    "shadesun": {"titel":"Besonnung","zweck":"Vergleicht den LIVE-Sonnenstand (Azimut/Elevation aus der Location) mit dem Sonnenstands-Profil (geoProfile) EINER Beschattungs-Zone. Zwei bis drei Balken zeigen, ob die Sonne im Azimut-Fenster steht, über die Elevations- und optional die Helligkeitsschwelle kommt — falsche Sonnen-Configs werden so sofort sichtbar. Zusätzlich lässt sich der Schließgrad dieses Rollos direkt setzen.","funktionen":[{"name":"Modus","beschreibung":"„Session (folgt Auswahl)“ koppelt an die shadex-Familie derselben Session-ID, „Feste Zone“ bindet fest an eine Instanz-ID."},{"name":"Session-ID","beschreibung":"Nur bei Modus Session: ID der Beschattungs-Session, der das Widget folgt (Vorgabe „shade“)."},{"name":"Zone (Instanz-ID)","beschreibung":"Nur bei fester Zone: Instanz-ID der Beschattung, deren Sonnenstands-Profil verglichen wird."},{"name":"Akzentfarbe","beschreibung":"Skin-Farbe für Balken, Marker und den Schließgrad-Regler."},{"name":"Höhe-Achse max","beschreibung":"Maximum der Elevations-(Höhen-)Achse in Grad für die Balkendarstellung (Vorgabe 70)."},{"name":"Statuskopf","beschreibung":"Chip „aktiv/inaktiv“ mit Klartext-Urteil: Sonne im Fenster, außerhalb des Fensters, zu tief (unter Schwelle) oder zu dunkel."},{"name":"Azimut-Balken","beschreibung":"0–360°-Skala mit N/O/S/W-Marken, dem Fassaden-Fenster (auch über 0° umlaufend) und dem Live-Azimut als Marker; darunter das Fenster in Grad, mit Warnung bei 0–360° = immer."},{"name":"Höhen-Balken","beschreibung":"0 bis Höhe-Achse-max mit Elevations-Schwelle, Füllbalken und Sonnen-Marker; Warnung bei 0° = keine Schwelle."},{"name":"Helligkeits-Balken","beschreibung":"Optional, nur wenn im Profil eine Helligkeits-Mindestschwelle gesetzt ist: Schwelle plus aktueller Wert."},{"name":"Schließgrad · dieses Rollo","beschreibung":"Eigene Karte mit Regler (0–100 %, 5er-Schritt) und den Presets 50/75/100 %. Setzt entprellt (300 ms) den Schließgrad dieses Rollos bei diesem Sonnenprofil über ?api=shading&op=setclose. Das Profil legt nur das Sonnenfenster fest, dieser Wert legt fest, wie weit das Rollo dann schließt."},{"name":"Live","beschreibung":"Sonnenstand und Zonen-Config werden alle 30 s über ?api=mod (reconcileProbe) neu geholt; folgt die Bindung der Session, wird bei Zonenwechsel neu geladen."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Ohne gebundenes Rollo steht „Kein Rollo gebunden“, ohne gesetztes Sonnenstands-Profil der Hinweis, es im Editor „Sonne“ zu konfigurieren. Liest read-only über ?api=mod (reconcileProbe); der Schließgrad wird dagegen aktiv geschrieben. Doku-Vorschau rein lokal.","groesse":[560,150],"demo":{"session":"shade"}},
    "shadeprofiles": {"titel":"Beschattungs-Profile","zweck":"Verwaltet die GETEILTEN benannten HomeSuite-Beschattungsprofile über den Hub (ProfileEngine) und ersetzt die IPSShadowing-Profilverwaltung. Je Typ (Sonne, Wetterschutz, Tagesbeginn, Tagesende, Temperatur) lassen sich Profile anlegen, bearbeiten, duplizieren, umbenennen, löschen und einer Zone zuweisen. Die Eingabefelder werden generisch aus dem Typ-Schema des Hubs erzeugt.","funktionen":[{"name":"Zone","beschreibung":"Bindung für die Zuweisung: „Session (folgt Auswahl)“ koppelt an die shadex-Familie derselben Session-ID, „Feste Zone“ bindet fest an eine Instanz-ID."},{"name":"Session-ID","beschreibung":"Nur bei Bindung Session: ID der Beschattungs-Session, der das Widget folgt (Vorgabe „shade“)."},{"name":"Zone (Instanz-ID)","beschreibung":"Nur bei fester Zone: Instanz-ID der Beschattungs-Zone, deren Zuweisung gezeigt und gesetzt wird."},{"name":"Typ-Reiter","beschreibung":"Unterstrich-Tabs je Profiltyp aus dem Hub-Schema (Sonnenprofil, Wetterschutz, Tagesbeginn, Tagesende, Temperatur). Jeder Typ führt eine eigene Profil-Liste; das der aktuellen Zone zugewiesene Profil ist mit einer „Rollo“-Marke gekennzeichnet."},{"name":"Profil-Liste","beschreibung":"Linke Spalte mit allen Profilen des gewählten Typs; das aktive ist hervorgehoben, das der Zone zugewiesene trägt die Rollo-Marke. „+ Neues Profil“ legt per Namensabfrage ein leeres Profil an."},{"name":"Profil-Editor","beschreibung":"Rechts die Felder aus dem Typ-Schema, generisch gerendert je Feldtyp (Zahl, Fließkomma mit 0,1-Schritt, Ja/Nein-Schalter, Auswahl, Uhrzeit). Beispielfelder Sonne: Azimut von/bis, Elevations-Schwelle, Ziel-Position; Wetterschutz: Wind max, Bei Regen schützen, sichere Position. Das Temperatur-Gate deckt sowohl Innen- als auch Außen-Schwellen ab, sofern im Schema vorhanden."},{"name":"Speichern","beschreibung":"Schreibt die Felder über den Hub (profileSetFields); alle Zonen, die dieses Profil verwenden, werden dabei aktualisiert."},{"name":"Duplizieren / Umbenennen / Löschen","beschreibung":"Kopiert das Profil unter neuem Namen, benennt es um oder entfernt es (mit Rückfrage) — jeweils über den Hub."},{"name":"Zuweisung","beschreibung":"Der Block „Zuweisung“ zeigt das aktuell zugewiesene Profil der gebundenen Zone. „Dieses Rollo → <Profil>“ weist das gewählte Profil zu, „entfernen“ hebt die Zuweisung auf. Ohne gebundene Zone erscheint ein Hinweis auf Session/festes Rollo."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Läuft komplett über den Hub (?api=mod&op=hubmanage → ProfileEngine); ist der Hub nicht erreichbar, meldet das Widget „Hub nicht erreichbar“. Die Doku-Vorschau zeigt nur Demodaten.","groesse":[560,420],"demo":{"session":"shade"}},
    "shadingpanel": {"titel":"Beschattungs-Panel (alt/Monolith)","zweck":"Fasst ALLE IPSShadowing-Rollos in EINEM Panel im Stil des Heizplans zusammen: Raum-Tabs gruppiert nach Etage (EG/OG/Markise), großer Detailbereich für das gewählte Rollo, eine Sonnenstands-Analyse mit Kompass und Tagesverlauf sowie eine Übersicht (Ledger) aller Rollos. Monolith-Altwidget, ersetzt durch die generische heatx-Familie.","funktionen":[{"name":"Raum-Tabs","beschreibung":"Oben die Rollos, gruppiert nach Etage (Erdgeschoss / Obergeschoss / Markise). Ein Tab wählt das Rollo für den Detailbereich."},{"name":"Detail-Steuerung","beschreibung":"Großer Positionswert in %, Slider und Presets (Beschriftungen aus „Preset-Knöpfe“, Vorgabe Auf/25%/Halb/75%/Zu), die direkt schreiben, ein Automatik-Schalter und die Statuszeile des Geräts."},{"name":"Programme","beschreibung":"Rechts die Programm-/Profil-Auswahlen des gewählten Rollos (Tag/Nacht/Sonne/Temperatur/Präsenz/Beginn/Ende); eine Auswahl schreibt sofort. Ohne Auswahlen steht ein Hinweis."},{"name":"Sonnenstand · Kompass","beschreibung":"Polar-Kompass für das gewählte Fenster: Winkel = Azimut (N oben), Radius = Elevation, mit Tagesbogen, Auf-/Untergangspunkten, Fassaden-Zeiger, Trefferkeil (Akzeptanzwinkel) und dem zugewiesenen Sun-Profil als Keil. Badges zeigen „Fenster besonnt“, „Profil-Automatik“ und Azimut/Höhe."},{"name":"Tagesverlauf · Profilvergleich","beschreibung":"Zeitbalken über den Tag: helle Zone = Tag, Gold = Sonne trifft das Fenster, Teal = wann das Shadowing-Sun-Profil nach Azimut/Elevation auslöst, plus Auf-/Höchststand-/Untergangszeiten und eine breitenabhängige Stundenachse."},{"name":"Sonnensimulation","beschreibung":"Uhrzeit-Regler mit Play/Pause spielt den Tag ab und treibt Kompass, Balken, Badges und die Sonnen-Glyphen der Übersicht; „Jetzt“ springt zurück auf Echtzeit."},{"name":"Übersicht (Ledger)","beschreibung":"Alle Rollos je Etage als Zeilen: Name, ziehbarer Positions-Regler, Prozent, Sonnen-Glyph (trifft/oben/Nacht mit Einfallswinkel), Raum-/geschätzte Temperatur und ein Auto/Hand-Umschalter. Zeile wählt das Rollo, der Umschalter schaltet die Automatik. Titel über „Übersicht-Titel“ einstellbar."},{"name":"Nordabweichung °","beschreibung":"Dreht alle Fassaden-Ausrichtungen gemeinsam, um das Haus korrekt gegen Nord auszurichten (Vorgabe 19°)."},{"name":"Sonne Akzeptanz ±°","beschreibung":"Wie weit seitlich die Sonne noch als Treffer am Fenster zählt (Vorgabe ±90°)."},{"name":"Ausrichtung je Fenster","beschreibung":"Himmelsrichtung (N/NO/O/SO/S/SW/W/NW) je Rollo; der resultierende Fassaden-Azimut wird zur Kontrolle angezeigt. Vorbelegt aus bekannten Angaben, im Editor überschreibbar."},{"name":"Beschriftungen","beschreibung":"„Übersicht-Titel“ betitelt die Ledger-Liste, „Preset-Knöpfe“ setzt die fünf Preset-Beschriftungen der Detail-Steuerung (kommagetrennt)."},{"name":"Ein Sammel-Abruf","beschreibung":"Alle Daten inkl. Sonnenstand und Geo kommen aus einem einzigen ?api=getall-Request (5-s-Cache, 7-s-Refresh), unabhängig von der Zahl der Rollos."}],"hinweis":"Nicht in der Palette (noPalette): bleibt für die noch nicht migrierte Rollos-Seite funktionsfähig, wird aber nicht mehr neu platziert. Der Sonnenstand kommt aus der verifizierten Location; Lesen über ?api=shading&op=getall, Schreiben über ?api=setvar. Doku-Vorschau rein lokal (Beispielrollos).","groesse":[980,600],"demo":{"label":"Beschattung"}},
    "shading": {"titel":"Beschattung / Rollo (IPSShadowing)","zweck":"Steuert EIN IPSShadowing-Rollo als kompakte Karte: aktuelle Position (Jalousie-Visual + Slider und Auf/Halb/Zu), Automatik-Schalter, die Programm-/Profil-Auswahlen (Tag/Nacht/Sonne …) und der Live-Status. Legacy-Widget, das durch die generische HomeSuite-cover-Familie abgelöst wurde und nicht mehr in der Palette angeboten wird.","funktionen":[{"name":"Gerät","beschreibung":"Auswahl des Rollos aus der Liste aller IPSShadowing-Geräte (mit Etage EG/OG/Markise). Label leer = Geräte-Name."},{"name":"Position","beschreibung":"Jalousie-Visual + Prozentwert (geschlossen). Slider und die Presets Auf/Halb/Zu schreiben die Position direkt über RequestAction — manuelle Übersteuerung."},{"name":"Automatik","beschreibung":"Ein Knopf schaltet die IPSShadowing-Automatik des Geräts an/aus."},{"name":"Programme anzeigen","beschreibung":"Kontrollkästchen je Selektor legen fest, welche Programm-/Profil-Auswahlen die Karte zeigt (Tag, Nacht, Temperatur, Präsenz, Tagesbeginn, Tagesende, Sonne; Vorgabe Tag/Nacht/Sonne). Die Optionen kommen aus den Variablenprofilen; eine Auswahl schreibt sofort."},{"name":"Status","beschreibung":"Zeigt die IPSShadowing-Statuszeile (ProfileInfo), z. B. aktives Programm, Tagesfenster, Innen-/Außentemperatur."},{"name":"Live / Sammel-Abruf","beschreibung":"Alle Karten speisen sich aus EINEM ?api=getall-Request (5-s-Cache, 7-s-Refresh); während der Bedienung wird nicht dazwischen neu gezeichnet."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Wie bei allen Widgets: Position (X/Y/Breite/Höhe), Sichtbarkeit (zur Laufzeit / Steuer-Variable mit Bedingung), Einblend-Animation und Ebene (Stapelreihenfolge)."}],"hinweis":"Nicht in der Palette (noPalette): bleibt auf Bestandsseiten funktionsfähig, wird für Neues aber nicht mehr angeboten — für neue Layouts das cover-Widget nutzen. Lesen über ?api=shading, Schreiben über ?api=setvar (RequestAction). Doku-Vorschau rein lokal.","groesse":[260,230],"demo":{"label":"Büro","deviceId":900701}},
    "shadeprofile": {"titel":"Beschattungs-Profil (IPSShadowing)","zweck":"Bearbeitet ein IPSShadowing-Profil (Weather, Tagesbeginn/-ende, Sonne, Temperatur). Jede bedienbare Einstellung des Profils wird automatisch als passendes Element gezeigt — Schalter, Auswahl, Zahl oder Textfeld — und sofort geschrieben.","funktionen":[{"name":"Profil wählen","beschreibung":"Im Panel wird das Profil aus allen IPSShadowing-Profilen gewählt, nach Klasse gruppiert (Weather / BgnOfDay / EndOfDay / Sun / Temp)."},{"name":"Automatische Elemente","beschreibung":"Boolean → Schalter, Auswahl-Profil → Klappliste (Optionen aus dem Variablenprofil), Zahl → Eingabe, Text → Textfeld. Es werden nur bedienbare Config-Variablen gezeigt; Status/Name bleiben außen vor."},{"name":"Sofort schreiben","beschreibung":"Jede Änderung schreibt direkt in die Profilvariable (setvar/RequestAction) und liest den Status nach kurzer Verzögerung neu."},{"name":"Status","beschreibung":"Zeigt die ProfileInfo-Zeile des Profils (z. B. berechnete Zeit, aktive/inaktive Bedingung)."},{"name":"Label","beschreibung":"Kopf-Überschrift der Karte; leer = Profilname."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Position (X/Y/Breite/Höhe), Sichtbarkeit, Einblend-Animation, Ebene."}],"hinweis":"Legacy-Widget: nicht mehr in der Palette (noPalette), abgelöst durch „Beschattungs-Profile“ (HomeSuite-Hub, benannte Profile), bleibt aber auf Bestandsseiten funktionsfähig. Ein IPSShadowing-Profil ist GLOBAL — es gilt für alle Rollos, die es verwenden. Lesen über ?api=shading&op=profile, Schreiben über ?api=setvar. Doku-Vorschau rein lokal.","groesse":[280,300],"demo":{"label":"Tagesbeginn Normal","profileId":900901}},
    "weekedit": {"titel":"Wochenplan-Editor","zweck":"Bearbeitet einen beliebigen Symcon-Wochenplan (Ereignis) direkt im Dashboard: Pool-Filterzeiten, Maehroboter, Zirkulationspumpe usw. Die Werte sind die im Plan definierten Aktionen (mit Name und Farbe); Darstellung als Farbbaender je Wochentag plus Slot-Editor.","funktionen":[{"name":"Plan waehlen","beschreibung":"Im Panel wird der Wochenplan (Ereignis) aus einer Liste aller Wochenplaene des Systems gewaehlt. Aktionen und Farben kommen automatisch aus dem Plan."},{"name":"Wochentage & Gruppen","beschreibung":"Mo-So anwaehlbar. Symcon fasst Tage zu Gruppen zusammen (z. B. Mo-Fr, Sa+So) — der Editor zeigt, fuer welche Tage die gerade bearbeitete Gruppe gilt; Aenderungen wirken auf alle Tage der Gruppe."},{"name":"Wochenuebersicht","beschreibung":"Sieben Farbband-Zeilen, je Tag die Schaltpunkte nach Aktionsfarbe. Ein Tag anklicken oeffnet ihn."},{"name":"Slot-Editor","beschreibung":"Je Schaltpunkt: Aktion aus der Liste waehlen, Startzeit in -1h/-10m/+10m/+1h-Schritten. Der erste Punkt liegt fix auf 00:00. '+ Einfuegen' setzt einen Punkt in die groesste Luecke, '- Loeschen' (mind. 1 Punkt bleibt). Zusaetzlich ein '+ Slot'-Knopf in der Kopfzeile."},{"name":"Max. Ein-Fenster/Tag","beschreibung":"maxWin — begrenzt die schaltbaren Ein-Perioden pro Tag auf das, was das Zielgeraet tatsaechlich speichern kann (z. B. ProCon-Pool-Pumpe = 4 TIMEC-Fenster). Zeigt einen Zaehler x/N in der Gruppenzeile und sperrt das Einfuegen des naechsten Fensters, sobald das Limit erreicht ist. 0/leer = keine Grenze (fuer generische Plaene wie Maehroboter)."},{"name":"Farben (Anzeige)","beschreibung":"actColors — je Aktion des Plans eine Skin-Farbe, die die im Ereignis hinterlegte Farbe NUR in der Darstellung ueberschreibt (passt sich dem Theme an). 'Auto' = Farbe aus dem Plan."},{"name":"jetzt","beschreibung":"Oben rechts die aktuell gueltige Aktion, aus dem Plan zur aktuellen Uhrzeit berechnet."},{"name":"Speichern","beschreibung":"Schreibt die Schaltpunkte der Gruppe zurueck in den Symcon-Wochenplan (IPS_SetEventScheduleGroupPoint); ueberzaehlige Punkte werden entfernt. Ungespeicherte Aenderungen werden in der Kopfzeile markiert."}],"hinweis":"Lesen/Schreiben ueber ?api=week (Symcon-Wochenplan-Ereignisse, EventType 2); Schreiben ist token-geschuetzt. Diese Doku-Vorschau ist rein lokal (Beispiel-Plan, speichert nichts).","groesse":[720,460],"demo":{"label":"Wochenplan","eventId":900801}},
    "mowplan": {"titel":"Maehplan-Editor","zweck":"Bearbeitet die Maeh-ZEITFENSTER EINES Maehroboters (HomeSuite/HSMW). Ein Maehplan ist eine Liste diskreter Fenster {Start, Dauer, Wochentage, Bereich} - Fenster duerfen sich UEBERLAPPEN (mehrere Flaechen gleichzeitig), was ein Symcon-Wochenplan nicht kann. Deshalb ein eigenes Modell statt weekedit.","funktionen":[{"name":"Maeher (HomeSuite)","beschreibung":"Eigenschaft mowerId: das Widget ist fest EINEM Maeher zugeordnet (kein Umschalter im Betrieb). Auswahl im Panel aus der Maeherliste (?api=mower&op=list). Der Kopf zeigt Maehername und Anzahl der Zeitfenster."},{"name":"Bezeichnung","beschreibung":"Freie Ueberschrift des Widgets (w.label, Vorgabe Maehplan), z. B. Maehplan Lefty. Steht im Kopf neben dem Maehnamen."},{"name":"Bereiche (Skin-Farben)","beschreibung":"Die Maehflaechen (Husqvarna-Missions/WorkAreas, z. B. Gross, Pool oben, Hausbereich) kommen live vom Modul. Jeder Bereich bekommt zyklisch eine Skin-Farbe (accent/info/ok/warm/crit/warn/accent-2) und wird als Legende ueber dem Wochenraster gezeigt - passt sich Hell/Dunkel an, keine festen Farben."},{"name":"Wochenraster","beschreibung":"Sieben Tageszeilen mit 0-24-h-Achse (3-h-Raster). Jedes Fenster ein farbiger Balken (Farbe = Bereich); ueberlappende Fenster stapeln sich automatisch in Spuren, die Zeile waechst proportional zur Spurenzahl. Balken-Beschriftung nur, wenn sie ganz passt - sonst nur Farbe. Der Ist-Tag ist hervorgehoben und traegt eine senkrechte Ist-Zeit-Linie."},{"name":"Fenster-Editor (Seitenspalte)","beschreibung":"Balken anklicken waehlt das Fenster. Bearbeitbar: Bereich (Auswahl), Start (-1h/-10m/+10m/+1h), Dauer (-30m/-10m/+10m/+30m), Wochentage (Mo-So-Umschalter). Knoepfe + Neues Fenster und - Loeschen. Styling wie der Heizplan-/Beschattungs-Editor (hp-*)."},{"name":"Speichern","beschreibung":"Schreibt alle Fenster ueber ?api=mower&op=settimers (token-geschuetzt) zurueck ans Modul. Nur wirksam, wenn der Maeher SCHARF ist; sonst Schatten (Antwort shadow:true, keine echte Aenderung, Hinweis-Toast). Ungespeicherte Aenderungen werden im Kopf und im Fuss markiert."},{"name":"Fluide Darstellung (kein Feld)","beschreibung":"Das Widget ist fluid: Zeilen/Balken fuellen die Kachelhoehe, Schriften und Elemente skalieren mit der Containergroesse (em/cqmin), ohne Verzerrung. Es gibt keine separaten Groessen-Regler mehr - einfach die Kachel groesser ziehen."}],"hinweis":"Lesen/Schreiben ueber ?api=mower (op=timers frei lesbar, op=settimers token-geschuetzt mit Modul-Gate). Ist kein Maeher gewaehlt, steht Kein Maeher gewaehlt. Die Doku-Vorschau ist rein lokal (Beispiel-Maeher, speichert nichts).","groesse":[720,470],"demo":{"label":"Maehplan Lefty","mowerId":0}},
    "ruletable": {"titel":"Regel-Tabelle","zweck":"Kompakte Matrix für Geräte-Regelmatrizen (z. B. ProCon TEMPC/ADCC/SWITCHC): eine ZEILE je Regel, eine SPALTE je Feld. Jede Zelle ist an eine eigene schreibbare Variable gebunden. Statt hunderter Einzelkacheln entsteht eine scanbare Tabelle mit sticky Kopf und sticky Regelspalte.","funktionen":[{"name":"Spalten (cols)","beschreibung":"Liste der Feld-Spalten: label, type (num/bool/sel), unit (nur num), options[] (nur sel). Wird i. d. R. generiert aus den Geräte-Regelvariablen. num-Spalten sind rechtsbündig, Einheit klein im Kopf."},{"name":"Regeln (rowLabels)","beschreibung":"Zeilenbeschriftungen, je eine Regel; jede Zeile zeigt Index + Text (z. B. Regel 0..7)."},{"name":"Zellen (items)","beschreibung":"Bindung je belegter Zelle: {vid, r, c}. Nicht belegte Zellen bleiben leer (·). Die Zell-Variablen werden automatisch gepollt und live aktualisiert."},{"name":"Bedienen","beschreibung":"num-Zelle: Tipp öffnet eine Zahleneingabe (Einheit wird abgeschnitten). bool-Zelle: Klick schaltet (Toggle). sel-Zelle: Klick schaltet auf die nächste Profil-Option weiter. Schreiben ist gegated (armed) — im Schatten-Modus passiert nichts am Gerät."},{"name":"Aktiv-Spalte","beschreibung":"Eine bool-Spalte mit Label wie „Aktiv/Anwenden/Enable/Ein“ wird erkannt: ist sie aus, wird die ganze Regelzeile gedämpft dargestellt."},{"name":"Nur Skin-Farben","beschreibung":"Kopf/Trenner/Akzente aus den Skin-Token — funktioniert im hellen und dunklen Skin."}],"hinweis":"Für die Pool-Controller-Konfig aus dem Generator (poolcfg) erzeugt; die Zellbindungen kommen aus dem Generator, nicht von Hand. Sehr breite Matrizen (viele Spalten) scrollen horizontal.","groesse":[900,320],"demo":{"label":"TEMPC-Regeln","cols":[{"label":"Aktiv","type":"bool"},{"label":"Ziel","type":"sel","options":[{"value":0,"text":"Pumpe"},{"value":1,"text":"Ventil"}]},{"label":"Diff","type":"num","unit":"K"}],"rowLabels":["Regel 0","Regel 1"],"items":[]}},
    "regiontabs": {"titel":"Region-Tabs","zweck":"Tab-Leiste im HomeSuite-Raum-Look (Buttons/Pills/Underline), die den Inhalt eines Komponenten-Bereichs zwischen mehreren Ansichten umschaltet. Der aktive Tab (= aktuell in der Region gezeigte Ansicht) wird hervorgehoben. Zusammen mit einem Komponente-Widget gleichen Region-Namens entsteht eine Seite mit festem Rahmen und tab-geschaltetem Inhalt.","funktionen":[{"name":"Stil","beschreibung":"style - Buttons, Pills oder Underline (identische Optik zu den Raum-Selektoren, hssel). Vorgabe Pills."},{"name":"Region-Name","beschreibung":"slot - muss zum Region-Namen (component.slot) des Komponente-Widgets passen, dessen Inhalt umgeschaltet wird. Vorgabe inhalt."},{"name":"Tabs","beschreibung":"tabs[] - Liste aus Label und Ziel-Ansicht (view). Klick schaltet die Region auf die Ansicht (setRegion) und markiert den Tab aktiv. Eintraege ohne view werden uebersprungen."},{"name":"Standard-Ansicht (kein Feld)","beschreibung":"w.default bestimmt, welche Ansicht anfangs aktiv ist (i. d. R. = die Komponente-Vorgabe); ohne Vorgabe der erste Tab."}],"hinweis":"Region-Umschaltung ist rein clientseitig (kein Speichern). Sehr viele Tabs brechen um (flex-wrap). Reine Skin-Farben. Passt der Region-Name nicht zu einer Komponente, schaltet nichts sichtbar um.","groesse":[900,48],"demo":{"style":"pills","slot":"demo","default":"A","tabs":[{"label":"Live","view":"A"},{"label":"Konfig","view":"B"}]}},
    "ticker": {"titel":"Laufzeile","zweck":"Endlos laufendes Meldungsband mit farbigem Titelblock und Zaehler fuer kritische Eintraege. Eine Zeile kann statischer Text mit Variablenwert sein, ein inline angelegtes Widget oder die Referenz auf ein bereits vorhandenes, benanntes Widget.","funktionen":[{"name":"Tempo (s)","beschreibung":"speed — Dauer eines vollen Durchlaufs in Sekunden (Vorgabe 46, Minimum 8). Groesserer Wert = langsamer. Das Band wird intern doppelt gerendert, damit der Umlauf nahtlos ist."},{"name":"Titel anzeigen","beschreibung":"hideLead (invertiert) — blendet den Kopfblock links (Pulspunkt + Label) ein oder aus."},{"name":"Punkte anzeigen","beschreibung":"hideDots (invertiert) — blendet die farbigen Statuspunkte vor jedem Textelement aus; die Abstaende bleiben erhalten."},{"name":"Anzahl-Badge","beschreibung":"hideCount (invertiert) — zaehlt die Textelemente mit Stufe crit und zeigt sie als Pille im Titelblock. Nur waehlbar, wenn der Titel eingeblendet ist."},{"name":"Elemente — Typ","beschreibung":"Je Zeile waehlbar: Text, Widget (Referenz) oder eines der inline-Widgets Wert, KPI, Delta, Chip, Icon, Text, Schalter, Kachel, Balken."},{"name":"Element: Text / Zusatz","beschreibung":"Bei Typ Text: Haupttext (fett) und kleiner Zusatztext dahinter."},{"name":"Element: VarID (Text)","beschreibung":"Bei Typ Text: der formatierte Wert dieser Variablen wird hinter dem Text eingeblendet und live aktualisiert."},{"name":"Element: Icon","beschreibung":"Icon-Kennung vor dem Text; wird in der Farbe der gewaehlten Stufe gezeichnet."},{"name":"Element: Stufe","beschreibung":"sev — info, ok, warn oder crit — faerbt Punkt und Icon und bestimmt, ob das Element in den crit-Zaehler eingeht. Ohne crit-Element werden Titelblock und Zaehlpille gruen statt rot."},{"name":"Element: Widget (Referenz)","beschreibung":"Auswahl aus allen Widgets mit gesetztem Namen (auch aus Leiste und Sidebar; Typ und Herkunft in Klammern). Das Widget wird als echte Instanz im Band gezeichnet und laeuft live mit."},{"name":"Element: inline-Widget","beschreibung":"VarID, Label und Icon fuer ein direkt in der Laufzeile angelegtes Widget des gewaehlten Typs."},{"name":"Element: Breite","beschreibung":"Breite der Widget-Kachel im Band in Pixel (Vorgabe: Breite des Originals bzw. 170)."},{"name":"Element hinzufuegen / entfernen","beschreibung":"Plus legt eine neue Referenz-Zeile an, Minus loescht sie. Wird die letzte Referenz auf ein Widget entfernt, wird dieses Widget auf der Seite automatisch wieder sichtbar geschaltet."},{"name":"Typografie-Uebernahme","beschreibung":"Referenzierte und inline-Widgets uebernehmen Textfarbe, Schriftart, Gewicht, Stil und Groesse ihrer Original-Konfiguration, werden aber ohne eigenen Hintergrund und Rahmen gezeichnet."},{"name":"Fehlende Referenz","beschreibung":"Zeigt der Name auf kein vorhandenes Widget, erscheint statt der Kachel ein Warn-Element '? name'."},{"name":"Farben / Rahmen / Typografie / Sichtbarkeit / Interaktion / Animation","beschreibung":"Gemeinsame Eigenschaften wie bei allen Widgets. Die Zeile 'in Laufzeile verschieben' fehlt hier — eine Laufzeile kann nicht in sich selbst wandern."}],"hinweis":"Referenzierbar sind nur Widgets mit gesetztem Namen (Eigenschaften -> Name) — ohne Namen bleibt die Auswahlliste leer. Umgekehrt bietet jedes andere Widget in seiner Sichtbarkeits-Sektion 'in Laufzeile verschieben': es wird benannt, in die erste Laufzeile referenziert und auf der Seite ausgeblendet. Das Band ist auf eine flache Bauform ausgelegt (Vorgabe 560x46); Schriftgroesse und Abstaende skalieren ueber die Containerhoehe.","groesse":[620,90],"demo":{"label":"Alarm","speed":46,"items":[{"sev":"warn","icon":"window","text":"2 Fenster offen","sub":"Bad OG"},{"sev":"info","icon":"bolt","text":"Bezug","vid":38704},{"wtype":"value","varId":26109,"label":"Aussen","icon":"temperature","w":150},{"sev":"ok","icon":"shield","text":"Alarm unscharf"}]}},
    "tile": {"titel":"Kachel","zweck":"Kompakte Geraetekachel aus Icon-Badge, Name und Statustext. Ein Klick schaltet die gebundene Variable um oder loest Navigation, Popup bzw. Skript aus; Ein- und Aus-Zustand koennen frei gestaltet werden.","funktionen":[{"name":"Variable","beschreibung":"Zustandsvariable. Ihr formatierter Wert erscheint als Statuszeile unter dem Namen; wahr/1 setzt den Badge auf 'ein' (Akzentfarbe gefuellt)."},{"name":"Klick schaltet","beschreibung":"Nur wenn keine der Aktionen (Popup schliessen/oeffnen, Skript, Menue oeffnen, Region setzen, Zurueck, Seite oeffnen) gesetzt ist, wird beim Klick die Variable getoggelt (wahr -> 0, sonst 1). Nur ausserhalb des Bearbeiten-Modus."},{"name":"Nur Icon","beschreibung":"iconOnly — blendet Name und Status aus, das Icon fuellt die gesamte Kachel — gedacht fuer Popup-/Navigations-Buttons."},{"name":"Icon (Fallback)","beschreibung":"Icon des Badges (Vorgabe bulb). Adaptive Icons wie bulb, blinds, battery oder window zeichnen sich abhaengig vom Variablenwert (Prozent bzw. Zustand)."},{"name":"Assoziationen","beschreibung":"Bei gesetzter Variablen: 'Icons & Farben nutzen' uebernimmt Icon und Farbe je Profil-Assoziation; je Zustand lassen sich Icon und Skin-Farbe ueberschreiben."},{"name":"Seite oeffnen / Popup oeffnen","beschreibung":"Statt zu schalten navigieren bzw. eine Ansicht als Popup einblenden; beim Popup erscheint die Alias-Tabelle Vorlagen-ID -> echte Geraete-ID, um dieselbe Vorlage fuer mehrere Geraete zu nutzen."},{"name":"Lang-Druck -> Popup / -> Seite","beschreibung":"Nach etwa 550 ms Halten wird ausgeloest; sind beide gesetzt, gewinnt der Seitenwechsel. Der anschliessende Klick wird unterdrueckt."},{"name":"Region setzen / Zurueck / Menue oeffnen / Popup schliessen","beschreibung":"Region setzen tauscht den Inhalt einer benannten Region gegen eine Ansicht (Region UND Ansicht noetig); Zurueck fuehrt zur vorherigen Seite; Menue oeffnen klappt die Seitenliste auf/zu; Popup schliessen macht die Kachel zum Schliessen-Button (vor allen anderen Aktionen ausgewertet)."},{"name":"Skript ID","beschreibung":"Fuehrt beim Klick das angegebene IP-Symcon-Skript aus."},{"name":"Zustand Ein / Aus: Text","beschreibung":"Ersetzt den Namen der Kachel im jeweiligen Zustand. Leer = Label wird angezeigt (ein gesetzter Text verdraengt das Label)."},{"name":"Zustand Ein / Aus: Hintergrund / Textfarbe / Icon","beschreibung":"Je Zustand eigene Hintergrundfarbe, Text-/Icon-Farbe und unterschiedliche Icons fuer Ein und Aus. Leer laesst das Standard-Icon stehen."},{"name":"Zustands-Stil zuruecksetzen","beschreibung":"Loescht alle acht Ein/Aus-Einstellungen auf einmal."},{"name":"Format / Beschriftung / Typografie","beschreibung":"Gemeinsame Formatwahl fuer den Statustext, mehrzeilige Beschriftung statt Abschneiden, Schriftart/Gewicht/Stil/Groesse, Farben, Rahmen, transparenter Hintergrund. Nachkommastellen bietet dieser Typ nicht."},{"name":"Sichtbarkeit / Animation / Ebene / Geometrie","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, in Laufzeile verschieben, Einblend-Animation, Z-Reihenfolge, X/Y/B/H."}],"hinweis":"Die Kachel hat — wie der Button — eine eigene Interaktions-Sektion; die allgemeine Interaktions-Sektion erscheint hier nicht. Die Ein/Aus-Gestaltung wird erst im Live-Update angewendet, ohne gebundene Variable bleibt sie wirkungslos. Ein gesetzter 'Zustand Ein/Aus: Text' verdraengt das Label, weil derselbe Platz benutzt wird.","groesse":[220,90],"demo":{"varId":30519,"icon":"bulb","label":"Licht Lesezimmer"}},
    "timer": {"titel":"Timer","zweck":"Countdown mit Restzeit als mm:ss bzw. h:mm:ss und einem Fortschrittsbalken. Zeigt entweder die Restsekunden einer Variablen oder die Zeit bis zu einem Unix-Zeitstempel.","funktionen":[{"name":"Variable","beschreibung":"Quelle der Restzeit. Werte groesser 1.000.000.000 werden als Unix-Zeitstempel verstanden und die Differenz zu jetzt gebildet; kleinere Werte gelten direkt als Restsekunden. Negative Ergebnisse werden auf 0 gekappt."},{"name":"Max","beschreibung":"Gesamtdauer in Sekunden fuer den Balken (Vorgabe 3600). Die Balkenbreite ist Restzeit/Max, auf 0 bis 100 % begrenzt."},{"name":"Min","beschreibung":"Wird zwar angeboten (gemeinsame Min/Max-Zeile), vom Timer aber nicht ausgewertet."},{"name":"Label","beschreibung":"Bezeichnung links in der Kopfzeile; \\n erzwingt einen Zeilenumbruch."},{"name":"Sekuendliche Aktualisierung","beschreibung":"Der Timer haengt an der globalen Sekundenschleife (wie die Uhr) und zaehlt selbstaendig herunter — auch ohne neue Variablenwerte. Das gilt auch fuer Timer innerhalb von Komponenten und Laufzeilen."},{"name":"Farben / Rahmen / Hintergrund / Typografie","beschreibung":"Gemeinsame Gestaltung: Vorder- und Hintergrundfarbe, Rahmen, transparenter Hintergrund, Schriftart/Gewicht/Stil/Groesse, mehrzeilige Beschriftung. Restzeit und Balken in der Akzentfarbe, die Zeit in Mono-Schrift."},{"name":"Interaktion","beschreibung":"Seite oeffnen, Popup oeffnen, Lang-Druck auf Seite/Popup, Popup schliessen, Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene / Geometrie","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, in Laufzeile verschieben, Einblend-Animation, Z-Reihenfolge, X/Y/B/H."}],"hinweis":"Rein anzeigend — der Timer startet und stoppt nichts, er stellt nur eine Variable dar. Es gibt weder Formatwahl noch Nachkommastellen; die Anzeige ist fest mm:ss bzw. h:mm:ss. Liegt der Zeitstempel in der Vergangenheit oder ist die Restzeit 0, steht dauerhaft 00:00 und der Balken ist leer. Ohne passend gesetztes Max ist der Balken sofort voll.","groesse":[230,90],"demo":{"varId":16467,"max":86400,"label":"Bis Sonnenuntergang"}},
    "bot": {"titel":"Roboter","zweck":"Karte fuer Saug- oder Maehroboter (frueher „Vacuum\"). ZWEI MODI: (1) Einfach — Statustext, Batteriestand und Start/Stop-Buttons ueber Variablen. (2) Mäher (HomeSuite) — waehlt man eine MowerDevice-Instanz, wird die volle Karte gezeigt: Akku-Ring, Aktivitaets-Icon+Farbe, Status-/Nächster-Start-Zeile, Bedien-Kacheln plus Schnitthoehe, Scheinwerfer und Automatik.","funktionen":[{"name":"Mäher (HomeSuite)","beschreibung":"Auswahl einer MowerDevice-Instanz (HSMW). Ist sie gesetzt, zieht die Karte Status/Akku/Aktivitaet/Kommandos alle 15 s live ueber ?api=mower&op=getall und schaltet ueber die Kommando-Variablen (im Modul durchs armed-Gate). „— aus —\" schaltet in den einfachen Modus."},{"name":"Bezeichnung","beschreibung":"Name in der Kopfzeile der Karte (bzw. Label im einfachen Modus)."},{"name":"Variable (einfach)","beschreibung":"Nur im einfachen Modus: Statusvariable. Ihr formatierter Wert steht als Statustext neben dem Roboter-Icon."},{"name":"Variable 2 (einfach)","beschreibung":"Akku-/Batteriestand (varId2), rechts in der Kopfzeile."},{"name":"Variable 3 (einfach)","beschreibung":"Start/Stop-Kommandovariable (varId3): Start schreibt 0, Stop schreibt 1."},{"name":"Bedien-Kacheln (Mäher)","beschreibung":"Je nach verfuegbaren Kommando-Variablen: Mähen, Parken, Pause, Weiter."},{"name":"Schnitthöhe (Mäher)","beschreibung":"Stepper 1–9 (mit Punkt-Skala), sofern die CuttingHeight-Variable vorhanden ist."},{"name":"Automatik (Mäher)","beschreibung":"Segment-Umschalter Auto / Pause / Manuell / Logik (AutoMode-Variable), inkl. Regen-/Empfehlungs-Badge, sofern vorhanden."},{"name":"Scheinwerfer (Mäher)","beschreibung":"Umschalter Immer an / Immer aus / Nur abends / Abends & nachts (Headlight-Variable), sofern vorhanden."},{"name":"Roboter-Icon (einfach)","beschreibung":"Standard mower in Akzentfarbe; ueber die gemeinsame Icon-Auswahl aenderbar (z. B. vacuum fuer Saugroboter)."}],"hinweis":"Im einfachen Modus schreiben Start/Stop starr 0 und 1 - passt nur zu Geraeten mit entsprechender Bool-/Aktionsvariable; nur ausserhalb des Bearbeiten-Modus wird geschrieben. Ist am Widget eine Klick-Aktion (Seite/Popup) gesetzt, verschluckt sie die Start/Stop-Klicks. Alte vacuum-Layouts werden automatisch auf bot migriert.","groesse":[240,130],"demo":{"varId":33327,"varId2":41522,"label":"Maehroboter"}},
    "value": {"titel":"Wert","zweck":"Die Standard-Wertanzeige: Label, grosser Zahlenwert, optional Icon, Praefix und Suffix. Der Wert kann nach Schwellen oder nach frei definierten Zustaenden eingefaerbt werden, wahlweise nur die Zahl oder die ganze Kachel.","funktionen":[{"name":"Variable","beschreibung":"Quelle des Werts. Angezeigt wird der vom Server formatierte Text; Aenderungen kommen per Poll bzw. WebSocket sofort an."},{"name":"Wert-Groesse (px)","beschreibung":"valfs — Schriftgroesse der Zahl (Vorgabe 24). Wird von einer in der Typografie gesetzten Schriftgroesse ueberschrieben, denn die gilt fuer alle Elemente des Widgets."},{"name":"Praefix / Suffix","beschreibung":"Text unmittelbar vor bzw. hinter dem Wert (z. B. ~ oder °C). Sobald ein Suffix gesetzt ist, wird die Einheit aus dem Variablenprofil abgeschnitten, damit sie nicht doppelt erscheint."},{"name":"Nachkommastellen","beschreibung":"dec — rundet den Rohwert auf 0 bis 6 Stellen und schreibt ihn mit Komma; ohne eigenes Suffix wird die Profileinheit wieder angehaengt. Wird zusaetzlich ein Format gewaehlt, gewinnt das Format."},{"name":"Format","beschreibung":"Umrechnung/Darstellung: kW, kWh, W, Prozent, auf 0 oder 1 Stelle gerundet, Uhrzeit, Datum oder Relativzeit ('vor 5 min'); 'Original' laesst den Servertext stehen."},{"name":"Ausrichtung","beschreibung":"align — Links, zentriert oder rechts. Wirkt auf den Textblock und — sobald ein Icon gesetzt oder Einzeilig aktiv ist — auf die Ausrichtung des gesamten Blocks."},{"name":"Einzeilig","beschreibung":"oneline — Icon und Wert nebeneinander in einer Zeile, das Label wird optional davorgesetzt statt darueber."},{"name":"Icon (Fallback)","beschreibung":"Icon links neben dem Wert. Adaptive Icons (z. B. battery, cistern, bulb) zeichnen sich abhaengig vom Wert."},{"name":"Icon-X ab links (px)","beschreibung":"icx — erscheint nur bei gesetztem Icon: schiebt den Inhalt per linkem Innenabstand vom Widget-Rand weg, um Icons mehrerer Kacheln buendig auszurichten."},{"name":"Icon-Farbe","beschreibung":"iconColor — Skin-Farbe des Icons ueber die zentrale Variable --wicon (Standard, Akzent, OK, Warnung, Kritisch, Info, Neutral). Ist sie gesetzt, ueberschreibt sie die Zustands-/Schwellenfaerbung des Icons."},{"name":"Farbe nach Schwelle: Aktiv","beschreibung":"colThr — schaltet die Schwellenfaerbung ein. Sind Schwellen gesetzt, aber 'Aktiv' ist aus, weist das Panel ausdruecklich auf die Wirkungslosigkeit hin."},{"name":"Gruen bis / Gelb bis","beschreibung":"t1 / t2 — zwei Schwellen: bis einschliesslich der ersten gruen (ok), bis zur zweiten warm/gelb, darueber kritisch/rot."},{"name":"Invertieren","beschreibung":"thrInvert — dreht die Schwellenlogik um: kleine Werte werden kritisch, grosse gut (z. B. Fuellstaende)."},{"name":"Farbe nach Zustand (Liste)","beschreibung":"vassoc — je Zeile Zustand, optionaler Ersatztext und Skin-Farbe. Erlaubt sind exakte Werte, Operatoren (>0, <=25, !=3), Bereiche (0..25) und * fuer alles andere; bei Bool 1/0 bzw. true/false. Exakte Treffer gehen Mustern vor. Der Ersatztext ersetzt die Anzeige (Praefix/Suffix bleiben), die Farbe schlaegt die Schwellenfarbe."},{"name":"Ganze Kachel einfaerben","beschreibung":"vaFill — statt nur der Zahl werden Hintergrund, Rahmen, Label und Icon in der Zustandsfarbe gehalten."},{"name":"Darstellung","beschreibung":"fillMode — nur bei eingeschalteter Kachelfaerbung: Automatisch (kritische Zustaende fuellen vollflaechig, andere toenen), Getoent oder Vollflaeche erzwingen."},{"name":"Assoziationen","beschreibung":"Bei gesetzter Variablen: Icons und Farben aus dem Variablenprofil uebernehmen und je Zustand mit eigenem Icon/eigener Skin-Farbe ueberschreiben."},{"name":"Label / Beschriftung / Typografie","beschreibung":"Label ueber dem Wert (\\n erzwingt Umbruch), mehrzeilig statt abschneiden, Schriftart/Gewicht/Stil/Groesse; Farben, Rahmen und transparenter Hintergrund."},{"name":"Interaktion","beschreibung":"Seite oeffnen, Popup oeffnen (mit Alias-Tabelle Vorlagen-ID -> echte Geraete-ID), Lang-Druck auf Seite/Popup, Popup schliessen, Skript-ID bei Klick."},{"name":"Sichtbarkeit / Animation / Ebene / Geometrie","beschreibung":"Zur Laufzeit anzeigen, Steuer-Variable mit Bedingung, in Laufzeile verschieben, Einblend-Animation, Z-Reihenfolge, X/Y/B/H."}],"hinweis":"Schwellen wirken nur bei eingeschaltetem 'Aktiv', und die Zustandsliste hat immer Vorrang vor den Schwellen. Wird die Kachelfaerbung genutzt, ueberschreibt sie die eingestellte Hintergrundfarbe, solange ein Zustand greift. Eine gesetzte Icon-Farbe verhindert, dass das Icon mitfaerbt.","groesse":[220,110],"demo":{"varId":26109,"label":"Aussentemperatur","icon":"temperature","valfs":26,"dec":1,"suf":" °C","colThr":true,"t1":20,"t2":28,"vaFill":true,"fillMode":"soft"}},
    "valuecard": {"titel":"Wertkarte","zweck":"Generische Karte: Icon/Titel oben links, oben rechts ein Schalter, eine Vergleichs-Pille ODER ein Badge, grosser Zahlenwert mit Einheit, Beschriftung, optional Bereichs-Leiste, Wert-Skala, Fortschrittsbalken oder Auswahl-Knoepfe. Die Merkmale sind FREI KOMBINIERBAR (Dosier-Karte = Schalter + Balken, Filterzeit = Akzent + Balken + Badge). Die Darstellung ist nur ein Schnell-Preset, das die passenden Optionen setzt.","funktionen":[{"name":"Darstellung (Preset)","beschreibung":"Schnellwahl, die die passenden Optionen unten setzt: Einfacher Wert, Zielbereich (Badge OK/PRUEFEN aus Min/Max), Bereich Min-Max (Skala), Balken, Schalter (Var 2) oder Auswahl (Profil-Zuordnungen von Var 1 als schaltbare Knoepfe). Danach lassen sich die Merkmale beliebig kombinieren."},{"name":"Variable (Var 1)","beschreibung":"Hauptwert; grosse Zahl, live aktualisiert. Im Auswahl-Modus die schaltbare Variable, deren Profil-Werte als Knoepfe erscheinen."},{"name":"Var 2","beschreibung":"Schaltkanal (Toggle oben rechts, Klick schreibt 1/0) — ODER, mit 'Var 2 = Akzent', faerbt sie die ganze Kachel — ODER, im Bereichsmodus, das Minimum. Dient sonst auch als Quelle der Zustandsfaerbung."},{"name":"Var 3","beschreibung":"Quelle des Fortschrittsbalkens (leer = Hauptwert) bzw. im Bereichsmodus das Maximum."},{"name":"Titel (oben-links)","beschreibung":"Kurztext neben oder statt des Icons in der Kopfzeile."},{"name":"Einheit","beschreibung":"Kleiner Zusatz hinter dem Wert. Ist eine Einheit gesetzt, wird die Profil-Einheit aus Symcon vom Wert abgezogen, damit nichts doppelt steht."},{"name":"Wert-Groesse (px)","beschreibung":"valfs — feste Schriftgroesse NUR der grossen Zahl in px; leer = automatisch (skaliert mit der Kachelhoehe). Die Einheit daneben bleibt unveraendert."},{"name":"Bereich zeigen (Min/Max)","beschreibung":"rngOn — Bereichsmodus: Var 2 = Minimum, Var 3 = Maximum, dazwischen eine Leiste mit Marker fuer den Hauptwert."},{"name":"Nachkommastellen (Min/Max)","beschreibung":"rngDec — rundet die beiden Beschriftungen links/rechts der Bereichs-Leiste auf feste Nachkommastellen (0-6, deutsches Komma). Leer = wie die Variable formatiert ist. Betrifft nur die Min/Max-Labels."},{"name":"Farbstufen: Wert · Farbe (Bereich)","beschreibung":"rngGrad — jede Stufe traegt einen Wert in der Einheit der Variable (z. B. 30 fuer 30 Grad), nicht in Prozent; die Umlegung auf die Leiste passiert zur Laufzeit, sobald Min und Max bekannt sind. Eine Stufe = einfarbig blass nach voll, keine Stufe = voreingestellte Temperaturskala."},{"name":"Wert-Skala (Farbe nach Wert)","beschreibung":"vcScale — Norm-Skala fuer Poolwerte, Toene 1:1 aus der ProCon.IP-Elektroden-Anzeige: faerbt den Grosswert je nach Messwert und zeigt eine Skalen-Leiste mit Marker. Preset pH (blassgelb niedrig -> orange hoch; 6,8-7,8) oder Redox/Chlor (blassrosa niedrig -> kraeftiges Pink hoch; mV-Schwellen aus der DPD-Kalibrierung 720-815 mV), zwischen den Stuetzstellen kontinuierlich interpoliert. Optional 'Ganze Kachel einfaerben' (scaleFill)."},{"name":"Badge (Text/Zustand)","beschreibung":"Nur ohne Bereichsmodus: Text und Zustandsfarbe der Plakette oben rechts (grau/OK/Aktiv/Warnung/Kritisch/Akzent)."},{"name":"Auto aus Zielbereich (okMin/okMax)","beschreibung":"Liegt der Hauptwert im Bereich, wird die Plakette gruen (Text OPTIMAL), sonst gelb (Text PRUEFEN). Beide Texte (okText/badText) sind einstellbar."},{"name":"Vergleich / Soll (Abweichung)","beschreibung":"cmpVid — optionale Soll-/Vergleichs-Variable: der Hauptwert (Var 1 = Ist) wird live gegen die Soll-Variable verglichen und die Abweichung als gefaerbte Pille oben rechts gezeigt — Modus Prozent oder Absolut (cmpMode), mit Toleranzband (cmpTol; innerhalb = gruen, ausserhalb = gelb), Pfeilrichtung und frei waehlbarem Zusatztext (cmpText, z. B. 'ggue. Plan'). Belegt den Badge-Platz; ein Schalter (Var 2) hat weiterhin Vorrang."},{"name":"Var 2 = Akzent","beschreibung":"v2acc — statt eines Schalters leuchtet die ganze Kachel auf, solange Var 2 wahr ist (in allen Modi ausser Schalter/Bereich)."},{"name":"Schalter-Farben / Knopf-Icons","beschreibung":"Im Schalter-Modus: Skin-Ein-/Aus-Farbe (swOn/swOff) und Ein-/Aus-Icon (swOnIcon/swOffIcon) des Schaltknopfs je Stellung."},{"name":"Fortschrittsbalken","beschreibung":"barOn — Balken zeigen; Quelle ist Var 3 (Balken-Var), sonst der Hauptwert. Balken min/max (barMin/barMax, Vorgabe 0-100) rechnet in 0-100 Prozent um; 'Text rechts' (barCap) ist eine feste Beschriftung neben dem Balken (z. B. 81 % Kanister)."},{"name":"Auswahl-Modus","beschreibung":"vcMode=select — die Knoepfe kommen aus den Profil-Zuordnungen von Var 1 (ueber ?api=assoc) und folgen dem Profil automatisch. Ein Klick schreibt den Wert (RequestAction, sonst SetValue). Ersetzt Schalter/Badge/Balken."},{"name":"Zustand · Farbe","beschreibung":"vassoc — Liste zur Zustandsfaerbung. Quelle ist Var 2, sonst der Hauptwert; true/false wird zu 1/0. Erlaubt exakte Werte, Operatoren (>, <, >=, <=, !=, =), Bereiche (25..60) und Platzhalter (*, else, default). Farbe aus den Skin-Farben."},{"name":"Ganze Kachel einfaerben","beschreibung":"vaFill — faerbt Hintergrund, Rahmen und Wert der Kachel in der Zustandsfarbe statt nur den Zahlenwert."},{"name":"Label / Icon / Format / Position","beschreibung":"Gemeinsame Eigenschaften: Beschriftung unter dem Wert, Symbol und Skin-Farbe der Kopfzeile, Zahlenformat/Nachkommastellen sowie freie Wert-/Icon-Position (X/Y-Felder oder Alt+Ziehen)."}],"hinweis":"Die Merkmale sind unabhaengig kombinierbar. Oben rechts hat der Schalter (Var 2, ohne Akzent, ohne Bereich) Vorrang vor der Vergleichs-Pille (Soll) und dem Badge. Der Auswahl-Modus ersetzt Schalter/Badge/Balken. 'Ganze Kachel einfaerben' und 'Var 2 = Akzent' duerfen nicht gleichzeitig aktiv sein; der Editor warnt.","groesse":[260,150],"demo":{"varId":41522,"vcMode":"bar","title":"Zisterne","label":"Fuellstand","unit":"%","icon":"cistern","dec":0,"barMin":0,"barMax":100,"barCap":"Regenwasser-Vorrat","vassoc":[{"v":"<25","color":"crit"},{"v":"25..60","color":"warn"},{"v":">60","color":"ok"}],"vaFill":true}},
    "weather": {"titel":"Wetter","zweck":"Zeigt das aktuelle Wetter aus einer einzigen String-Variable mit JSON: grosses Zustandssymbol, Temperatur, Zustandstext sowie Wind und Luftfeuchte. Ueber den Stil-Umschalter wird daraus zusaetzlich eine mehrtaegige oder stuendliche Vorhersage.","funktionen":[{"name":"Variable","beschreibung":"String-Variable mit dem Wetter-JSON. Erkannt werden OpenWeatherMap (One Call), Tempest/WeatherFlow (better_forecast), Open-Meteo und ein einfaches flaches JSON mit temp/condition. PHP-serialisierte Inhalte werden ebenfalls gelesen."},{"name":"Stil","beschreibung":"Standard zeigt nur den Ist-Zustand, Erweitert blendet zusaetzlich die Vorhersage ein (identisch zum Alt-Typ Wetter+)."},{"name":"Format","beschreibung":"Automatisch erkennen oder die Quelle fest vorgeben (OpenWeatherMap, Tempest/WeatherFlow, Open-Meteo). Das flache JSON gibt es nur ueber die Automatik."},{"name":"Temp-Einheit","beschreibung":"Zeichen hinter allen Temperaturen, Vorgabe ist das Gradzeichen."},{"name":"Aktuelle Werte (optional als Variable)","beschreibung":"Je Ist-Messwert optional eine eigene Symcon-Variable: Temperatur, Zustand, Feuchte %, Wind km/h und Regen (bool). Gesetzte Felder haben Vorrang vor dem JSON; die Zustands-Variable liefert Text, aus dem das Symbol abgeleitet wird. Ist die Regen-Variable wahr (true/1/groesser 0), wird die aktuelle Anzeige auf Regen gezwungen."},{"name":"Datenquelle anzeigen","beschreibung":"Blendet oben rechts einen kleinen Hinweis mit der erkannten Quelle ein (OpenWeatherMap, Tempest, Open-Meteo). Standardmaessig an, per Schalter abstellbar."},{"name":"Vorhersage (JSON)","beschreibung":"Variable 2: zweite JSON-Quelle nur fuer die Vorhersage. Bleibt sie leer, wird dieselbe Variable wie fuer den Ist-Zustand benutzt."},{"name":"Aktuell-Block","beschreibung":"Nur im erweiterten Stil: blendet den Ist-Zustand oben aus, damit die Vorhersagezeilen den Platz bekommen (sinnvoll, wenn zwei Karten nebeneinander stehen)."},{"name":"Vorhersage-Modus","beschreibung":"Ganz oben im erweiterten Stil: Taeglich (eine Zeile je Tag mit Temperatur-Bereichsbalken) oder Stuendlich (horizontale Spalten je Stunde: Uhrzeit, grosses Symbol, Temperatur, darunter Zusatzwerte), beginnend bei der aktuellen Stunde. Funktioniert mit allen drei Quellen."},{"name":"Vorhersage-Tage / Anzahl Stunden","beschreibung":"Anzahl der Zeilen bzw. Spalten, 1 bis 12."},{"name":"Zusatzwerte je Stunde","beschreibung":"Nur Stundenmodus, einzeln zuschaltbar: Luftfeuchte, Wind, Luftdruck und Niederschlag (Wahrscheinlichkeit % und — falls vorhanden — Menge mm nebeneinander, Regen % auch bei 0 %). Jeder Wert in eigener kleiner Zeile unter der Temperatur, das Wetter-Symbol bleibt gross. Fehlt ein Wert in der Quelle, bleibt die Zeile leer."},{"name":"Erster Tag","beschreibung":"Nur im Tagesmodus: beginnt die Liste bei Heute oder erst bei Morgen (Stunden starten immer bei jetzt)."},{"name":"Regenwahrsch.","beschreibung":"Nur Tagesmodus: blendet je Zeile den Tropfen mit der Niederschlagswahrscheinlichkeit ein (nur bei Wert groesser 0). Im Stundenmodus steuert stattdessen der Schalter Niederschlag die %/mm-Zeile."},{"name":"Temperaturbalken (Verlauf)","beschreibung":"Nur erweiterter Stil: Stufenliste aus Temperatur und Farbe (Farbwaehler #hex — keine Skin-Namen); der Balken jeder Zeile wird von der Tiefst- zur Hoechsttemperatur verlaufend gefuellt. Stufen hinzufuegen/loeschen, werden nach Temperatur sortiert."},{"name":"Skala Min/Max","beschreibung":"Feste Ober- und Untergrenze der Temperaturskala. Leer = automatisch aus den Vorhersagewerten (tiefster Wert minus 1 Grad bis hoechster Wert plus 1 Grad)."},{"name":"Verhalten: Uebersetzung / Zahlen","beschreibung":"Englische Zustandstexte von OWM und Tempest werden ins Deutsche uebersetzt, deutsche Texte bleiben unveraendert. Temperaturen formatiert das Widget selbst (aktuell eine Nachkommastelle, Vorhersage/Feuchte/Wind ganzzahlig); die gemeinsame Eigenschaft Format wirkt hier nicht."}],"hinweis":"Braucht eine String-Variable mit vollstaendigem Wetter-JSON; eine einzelne Temperaturvariable genuegt nicht. Ist die Vorhersage leer, obwohl der Ist-Zustand steht, enthaelt das JSON keinen daily- bzw. hourly-Teil oder die Quelle wurde falsch erzwungen.","groesse":[280,150],"demo":{"varId":53186,"wfmt":"auto","wunit":"°","label":""}},
    "weatherpro": {"titel":"Wetter+","zweck":"Alt-Typ des Wetter-Widgets, der immer im erweiterten Stil laeuft: Ist-Zustand oben, darunter je Tag oder Stunde eine Zeile mit Symbol, Tief- und Hoechstwert, Temperaturbalken und Regenwahrscheinlichkeit. Bestehende Ansichten bleiben gueltig, in der Palette erscheint es nicht mehr.","funktionen":[{"name":"Variable","beschreibung":"String-Variable mit dem Wetter-JSON (OpenWeatherMap One Call, Tempest/WeatherFlow, Open-Meteo oder flaches JSON, auch PHP-serialisiert)."},{"name":"Format","beschreibung":"Automatische Erkennung der Quelle oder feste Vorgabe (OpenWeatherMap, Tempest/WeatherFlow, Open-Meteo)."},{"name":"Datenquelle anzeigen","beschreibung":"Blendet oben rechts einen kleinen Hinweis mit der erkannten Quelle ein (OpenWeatherMap, Tempest, Open-Meteo). Standardmaessig an, per Schalter abstellbar."},{"name":"Temp-Einheit","beschreibung":"Zeichen hinter allen Temperaturen, Vorgabe ist das Gradzeichen."},{"name":"Vorhersage (JSON)","beschreibung":"Variable 2 als getrennte Quelle nur fuer die Vorhersagezeilen; leer bedeutet dieselbe Variable wie oben."},{"name":"Temperatur / Zustand / Feuchte % / Wind km/h / Regen (bool)","beschreibung":"Optionale Einzelvariablen fuer die Ist-Werte; sie haben Vorrang vor dem JSON. Eine wahre Regen-Variable setzt die aktuelle Anzeige auf Regen."},{"name":"Aktuell-Block","beschreibung":"Ist-Zustand oben ein- oder ausblenden; ausgeblendet bekommen die Vorhersagezeilen die volle Hoehe."},{"name":"Vorhersage (Modus)","beschreibung":"Ganz oben: Taeglich (Zeilen mit Bereichsbalken) oder Stuendlich (horizontale Spalten je Stunde: Uhrzeit, Symbol, Temperatur, Zusatzwert), Stunden ab jetzt. Alle drei Quellen (OWM, Tempest, Open-Meteo)."},{"name":"Vorhersage-Tage / Anzahl Stunden","beschreibung":"Anzahl der Zeilen bzw. Spalten, 1 bis 12."},{"name":"Zusatzwerte je Stunde","beschreibung":"Einzeln zuschaltbar: Luftfeuchte, Wind, Luftdruck, Niederschlag (Wahrscheinlichkeit % und Menge mm nebeneinander, Regen % auch bei 0 %). Jeder Wert in eigener kleiner Zeile unter der Temperatur; das Wetter-Symbol bleibt gross. Fehlt ein Wert in der Quelle, bleibt die Zeile leer."},{"name":"Erster Tag","beschreibung":"Nur Tagesmodus: Liste beginnt bei Heute oder bei Morgen (Stunden starten immer bei jetzt)."},{"name":"Regenwahrsch.","beschreibung":"Nur Tagesmodus: Tropfen mit Prozentwert je Zeile (nur bei Wert groesser 0). Im Stundenmodus uebernimmt der Schalter Niederschlag die %/mm-Zeile."},{"name":"Temperatur zu Farbe (Verlauf)","beschreibung":"Stufen aus Temperatur und Farbe (Farbwaehler, #hex) fuer den Balkenverlauf; Vorgabe ist eine Skala von blau ueber tuerkis und gruen und gelb bis rot."},{"name":"Skala Min/Max","beschreibung":"Feste Grenzen des Temperaturbalkens; leer heisst automatisch aus den Vorhersagewerten mit einem Grad Reserve."},{"name":"Verhalten: Heute-Marke","beschreibung":"In der Heute-Zeile sitzt zusaetzlich ein kleiner Knopf an der Stelle der aktuellen Temperatur."},{"name":"Verhalten: Live","beschreibung":"Jede Aenderung einer beteiligten Variable baut Ist-Zustand und alle Zeilen neu auf."}],"hinweis":"Nicht mehr in der Palette - fuer neue Ansichten das Widget Wetter mit Stil Erweitert nehmen, es benutzt denselben Code. Der Stundenmodus funktioniert mit OWM (hourly), Tempest (forecast.hourly) und Open-Meteo (hourly); liefert die Quelle keine Stundenwerte, bleibt er leer.","groesse":[380,260],"demo":{"varId":53186,"wfmt":"auto","wunit":"°","days":5,"fcStart":0,"showPq":true,"label":""}},
    "meteogram": {"titel":"Meteogramm","zweck":"Meteogramm im meteoblue-Stil aus einer einzigen Wetter-JSON-Variable: mehrere uebereinanderliegende Panels mit gemeinsamer Zeitachse. Temperatur-Panel mit Farbverlauf-Flaeche nach Temperatur (blau bis rot) - taeglich als eingefaerbtes Min/Max-Band, stuendlich als gefuellte Kurve -, Wetter-Icon-Reihe oben, Tag/Nacht-Schattierung und Min/Max-Marken; darunter Niederschlag (Balken, Regen/Schnee eingefaerbt) mit Regenwahrscheinlichkeit und Luftfeuchte, ein Bewoelkungs-Streifen (Graustufe) sowie Wind mit Geschwindigkeit, Boeen und Richtungspfeilen. Stuendlich oder taeglich.","funktionen":[{"name":"Variable","beschreibung":"String-Variable mit dem Wetter-JSON (OpenWeatherMap One Call, Tempest/WeatherFlow better_forecast oder Open-Meteo; auch PHP-serialisiert)."},{"name":"Format","beschreibung":"Automatische Quellenerkennung oder feste Vorgabe (OpenWeatherMap, Tempest/WeatherFlow, Open-Meteo)."},{"name":"Vorhersage-Variable (optional)","beschreibung":"Optionale zweite JSON-Quelle nur fuer die Vorhersage; leer = dieselbe Variable wie oben."},{"name":"Temp-Einheit","beschreibung":"Zeichen hinter den Temperaturen (Vorgabe Gradzeichen)."},{"name":"Modus","beschreibung":"Taeglich oder Stuendlich. Stuendlich beginnt bei der aktuellen Stunde."},{"name":"Anzahl Stunden / Tage","beschreibung":"Anzahl der Zeitschritte, 3 bis 48 (Vorgabe stuendlich 24, taeglich 7)."},{"name":"Erster Tag","beschreibung":"Nur Tagesmodus: Beginn bei Heute oder Morgen."},{"name":"Panel: Niederschlag + Feuchte","beschreibung":"Zuschaltbar. Balken fuer Regen/Schnee (nach Temperatur eingefaerbt) plus Regenwahrscheinlichkeit- und Luftfeuchte-Linie auf einer rechten Prozent-Achse. Nur sichtbar, wenn Daten vorhanden."},{"name":"Panel: Wolken","beschreibung":"Zuschaltbar. Graustufen-Streifen, Deckkraft nach Bewoelkung in Prozent. Keine Hoehenaufloesung. Nur sichtbar bei vorhandenen Wolkendaten."},{"name":"Panel: Wind","beschreibung":"Zuschaltbar. Windgeschwindigkeit und - falls vorhanden - Boeen als eigene Linie/Flaeche."},{"name":"Panel: Windrichtung (Pfeile)","beschreibung":"Zuschaltbar. Richtungspfeile oben im Wind-Panel, gedreht nach Windrichtung."},{"name":"Zeitformat (stuendlich)","beschreibung":"Beschriftung der Stunden-Achse: 14:00 (Vorgabe), nur Stunde 14, oder Varianten, bei denen um Mitternacht der Wochentag statt der Uhrzeit steht."},{"name":"Tagesformat (taeglich)","beschreibung":"Beschriftung der Tages-Achse: 4.8 (Vorgabe), 4.8., 04.08, Mo 4., Mo 4.8. oder nur der Wochentag Mo."},{"name":"Nachkommastellen","beschreibung":"Nachkommastellen der Temperatur-Werte (Min/Max-Marken, Achse, Tooltip), 0 bis 3. Dezimaltrennzeichen ist das Komma."},{"name":"Datenquelle anzeigen","beschreibung":"Blendet oben in der Ecke einen kleinen Hinweis mit der erkannten Quelle ein (z. B. Tempest). Standardmaessig an, abstellbar."},{"name":"Typografie (zentral)","beschreibung":"Schriftart, -gewicht, -stil und -groesse kommen aus der zentralen Typografie oben und wirken auch auf Achsen, Marken und Tooltip."},{"name":"Verhalten: Live & Bedienung","beschreibung":"Jede Aenderung der beteiligten Variablen baut das Meteogramm neu auf; fehlen Daten, steht 'keine Wetterdaten'. Der Mauszeiger zeigt ein synchrones Fadenkreuz ueber alle Panels; der Tooltip fasst alle Werte des Zeitpunkts zusammen, jede Zeile mit farbigem Marker in Graphenfarbe und -form."}],"hinweis":"Nutzt dieselbe JSON-Quelle wie das Wetter-Widget. Je nach Anbieter und Modus sind nicht alle Panels befuellbar - fehlende werden automatisch weggelassen statt leer zu bleiben (z. B. hat Tempest keinen stuendlichen Wolkenwert). Das Temperatur-Panel ist immer dabei; einen Luftdruck-Panel gibt es nicht.","groesse":[420,300],"demo":{"varId":53186,"wfmt":"auto","wunit":"°","fcMode":"hours","mgSteps":12,"label":""}},
    "multiring": {"titel":"Ring-Gauge","zweck":"Mehrere konzentrische Ringe (ECharts Ring-Gauge) aus je einer Variable - als Multi-Donut. Jeder Ring zeigt seinen Wert im Bereich zwischen eigenem Min und Max. Zwei Modi: Gauge (offener Bogen mit runden Enden) oder Donut (geschlossener Ring). Ideal, um mehrere Prozentwerte oder Fuellstaende kompakt uebereinander zu zeigen.","funktionen":[{"name":"Modus","beschreibung":"Gauge = offener Bogen mit runden Enden (Fortschritt); Donut = geschlossener Ring mit flachen Enden."},{"name":"Startwinkel / Endwinkel (fuer alle Ringe)","beschreibung":"Start- und Endwinkel in Grad, gelten gemeinsam fuer ALLE Ringe. Leer = Vorgabe je Modus (Gauge 225 bis -45 = 270 Grad offen; Donut 90 bis -270 = Vollkreis). 3 Uhr = 0 Grad, gegen den Uhrzeigersinn positiv."},{"name":"Ringbreite %","beschreibung":"Anteil des Ringbands, den die Ringdicke einnimmt (10-100, Rest ist Abstand). Leer = automatisch."},{"name":"Mitte - Anzeige","beschreibung":"In der Mitte nichts (aus), den Wert des ersten Rings oder einen festen Text zeigen. Bei Text erscheint zusaetzlich das Feld Text (Platzhalter = Widget-Label)."},{"name":"Legende","beschreibung":"Optionale Liste unten (HTML-Overlay): Farbpunkt, Label und aktueller Wert je Ring."},{"name":"Ringe (aussen -> innen)","beschreibung":"Listen-Editor: je Ring eine Variable (vid), Label, Min, Max (einzeln pro Ring), Einheit und Skin-Farbe. Der erste Eintrag ist der aeusserste Ring."},{"name":"Live (kein Feld)","beschreibung":"Jede Wertaenderung einer Ring-Variable aktualisiert den betroffenen Ring sofort."}],"hinweis":"Werte ausserhalb Min/Max werden auf den Ring begrenzt; ist Max <= Min, wird Max = Min+1 gesetzt. Ohne konfigurierte Ringe steht Ringe konfigurieren. Fuer reine Anteils-Darstellung (Segmente, die zu 100 % summieren) ist der Kreis/Donut im Chart-Widget gedacht; der Ring-Gauge zeigt je Ring einen eigenen Wert.","groesse":[260,260],"demo":{"mrMode":"gauge","mrCenter":"value","mrLegend":true,"rings":[{"vid":13239,"label":"Luftfeuchte","min":0,"max":100,"unit":"%","color":"accent"},{"vid":41522,"label":"Akku","min":0,"max":100,"unit":"%","color":"ok"},{"vid":10825,"label":"Auslastung","min":0,"max":100,"unit":"%","color":"warm"}]}},
    "heatmap": {"titel":"Heatmap","zweck":"Variante des Chart-Widgets (Chart-Typ Heatmap): aggregiert die Archiv-Historie EINER Variable zu einem Raster Wochentag (Zeilen, Mo oben) × Tageszeit (Spalten). Die Zellfarbe zeigt den Wert — so werden typische Tages- und Wochenmuster sichtbar (Verbrauch, Temperatur, Präsenz).","funktionen":[{"name":"Datenquelle","beschreibung":"Die erste Serie im Serien-Editor (eine Variable mit Archiv/Logging)."},{"name":"Zeitraum (Tage)","beschreibung":"Wie weit zurück aggregiert wird (1 bis 120, Vorgabe 14)."},{"name":"Auflösung","beschreibung":"Spaltenbreite je Zeit: Stunde (24), 30 min (48), 15 min (96) oder 5 min (288). Bei feiner Auflösung werden die 5-Minuten-Archivwerte als Basis genommen, bei Stunde der Stundenwert."},{"name":"Aggregation","beschreibung":"Mittelwert oder Summe je Zelle."},{"name":"Farbschema","beschreibung":"Heat (blau→rot), Kühl→Warm oder Akzent; die Skala steht als Legende unten (verschiebbar)."},{"name":"Werte einblenden","beschreibung":"Zahlen in den Zellen (nur bis 48 Spalten sinnvoll)."},{"name":"Hinweis","beschreibung":"Braucht geloggte Werte; ohne Historie erscheint der Hinweis keine Verlaufsdaten. Live-Aktualisierung ist aus (rein historisch)."}],"hinweis":"Kein eigenes Palette-Widget: über das Chart-Widget anlegen und als Chart-Typ Heatmap wählen.","groesse":[420,240],"demo":{"type":"chart","ctype":"heatmap","label":"Netzbezug: Wochentag × Stunde","varId":33962,"series":[{"vid":33962,"name":"Netzbezug"}],"hmDays":14,"hmRes":60,"hmScheme":"heat","aggField":"avg","showTitle":true}},
    "chartbar": {"titel":"Chart: Balken","zweck":"Chart-Typ Balken (Saeulen) einer Zeitreihe.","funktionen":[],"hinweis":"Variante des Chart-Widgets — alle Optionen stehen beim Eintrag Chart. Anlegen: Chart-Widget, dann Chart-Typ waehlen.","groesse":[340,180],"demo":{"type":"chart","ctype":"bar","label":"Balken","varId":26109,"series":[{"vid":26109,"color":"accent"}],"range":{"n":12,"unit":"hour","aggF":"avg","rawUnit":"hour"},"showTitle":true,"barRadius":3}},
    "chartrace": {"titel":"Chart: Bar Race","zweck":"Animierter Balken-Wettlauf: jede Serie ist ein Laeufer. Zwei Modi: VERLAUF (Frames ueber den eingestellten Zeitraum, Einheit = Bucket, z. B. 12 x Monate, mit Zeit-Uhr) oder LIVE (aktuelle Live-Werte verschiedener Kategorien, Umsortierung in Echtzeit bei jedem Update). Die Balken sortieren sich per ECharts realtimeSort neu.","funktionen":[{"name":"Datenquelle","beschreibung":"Verlauf (Zeit-Animation) ODER Live-Werte (Echtzeit, kein Archiv noetig)."},{"name":"Serien = Laeufer","beschreibung":"Jede Serie unten ein Balken; Farbe je Serie."},{"name":"Zeitraum = Frames","beschreibung":"Nur im Verlaufs-Modus: Anzahl x Einheit oben ist der Bucket-Takt der Animation."},{"name":"Top N / Tempo","beschreibung":"Sichtbare Raenge und Frame-Dauer (ms) einstellbar."},{"name":"Kumuliert","beschreibung":"Running Total fuer den Wachstums-Effekt; sonst der Bucket-Wert je Frame."},{"name":"Endlos-Schleife","beschreibung":"Laeuft automatisch, optional in Schleife."}],"hinweis":"Variante des Chart-Widgets — Chart anlegen, Typ 'Bar Race' waehlen. Braucht >=2 Serien mit geloggtem Verlauf.","groesse":[380,280],"demo":{"type":"chart","ctype":"barrace","label":"Verbrauch","series":[{"vid":48744,"name":"EG/OG","color":"accent"},{"vid":41293,"name":"Dachgeschoss","color":"info"},{"vid":45552,"name":"PV","color":"warm"}],"range":{"n":12,"unit":"month","aggF":"sum"},"brCumul":true,"brTop":10,"brSpeed":700}},
    "chartbarstack": {"titel":"Chart: Balken gestapelt","zweck":"Chart-Typ Balken gestapelt — mehrere Serien aufeinander.","funktionen":[],"hinweis":"Variante des Chart-Widgets — alle Optionen stehen beim Eintrag Chart. Anlegen: Chart-Widget, dann Chart-Typ waehlen.","groesse":[340,180],"demo":{"type":"chart","ctype":"barstack","label":"Gestapelt","series":[{"vid":26109,"name":"A","color":"accent"},{"vid":33962,"name":"B","color":"warm"}],"range":{"n":12,"unit":"hour","aggF":"avg","rawUnit":"hour"},"legend":true,"legPos":"top"}},
    "chartscatter": {"titel":"Chart: Punkte","zweck":"Chart-Typ Punkte (Scatter) einer Zeitreihe.","funktionen":[],"hinweis":"Variante des Chart-Widgets — alle Optionen stehen beim Eintrag Chart. Anlegen: Chart-Widget, dann Chart-Typ waehlen.","groesse":[340,180],"demo":{"type":"chart","ctype":"scatter","label":"Punkte","varId":26109,"series":[{"vid":26109,"color":"accent"}],"range":{"n":24,"unit":"hour","aggF":"avg","rawUnit":"hour"},"showTitle":true,"symSize":6}},
    "chartspark": {"titel":"Chart: Sparkline","zweck":"Kompakte Mini-Kurve ohne Achsen.","funktionen":[],"hinweis":"Variante des Chart-Widgets — alle Optionen stehen beim Eintrag Chart. Anlegen: Chart-Widget, dann Chart-Typ waehlen.","groesse":[180,60],"demo":{"type":"chart","ctype":"spark","varId":26109,"series":[{"vid":26109}],"lineColor":"accent"}},
    "chartpie": {"titel":"Chart: Kreis","zweck":"Anteile ohne Zeit (Kreis).","funktionen":[],"hinweis":"Variante des Chart-Widgets — alle Optionen stehen beim Eintrag Chart. Anlegen: Chart-Widget, dann Chart-Typ waehlen.","groesse":[300,200],"demo":{"type":"chart","ctype":"pie","label":"Kreis","varId":13239,"varId2":41522,"varId3":10825,"legend":true,"legPos":"right","showTitle":true}},
    "chartdonut": {"titel":"Chart: Donut","zweck":"Anteile als Donut (Ring).","funktionen":[],"hinweis":"Variante des Chart-Widgets — alle Optionen stehen beim Eintrag Chart. Anlegen: Chart-Widget, dann Chart-Typ waehlen.","groesse":[300,200],"demo":{"type":"chart","ctype":"donut","label":"Donut","varId":13239,"varId2":41522,"varId3":10825,"legend":true,"legPos":"right","showTitle":true}},
    "chartrose": {"titel":"Chart: Rose","zweck":"Anteile als Rose (Nightingale).","funktionen":[],"hinweis":"Variante des Chart-Widgets — alle Optionen stehen beim Eintrag Chart. Anlegen: Chart-Widget, dann Chart-Typ waehlen.","groesse":[300,220],"demo":{"type":"chart","ctype":"rose","label":"Rose","varId":13239,"varId2":41522,"varId3":10825,"showTitle":true}},
    "chartwf": {"titel":"Chart: Wasserfall","zweck":"Auf-/Ab-Beitraege zu einem Saldo (Wasserfall).","funktionen":[],"hinweis":"Variante des Chart-Widgets — alle Optionen stehen beim Eintrag Chart. Anlegen: Chart-Widget, dann Chart-Typ waehlen.","groesse":[360,210],"demo":{"type":"chart","ctype":"waterfall","label":"Wasserfall","wfUnit":"kWh","wfConnect":true,"labels":true,"showTitle":true,"steps":[{"title":"Start","vid":13239,"type":"start"},{"title":"Zufluss","vid":41522,"type":"auf"},{"title":"Abzug","vid":10825,"type":"ab"},{"title":"Summe","type":"sum"}]}},
    "webview": {"titel":"WebView","zweck":"Bettet eine beliebige Webseite als Rahmen (iframe) in die Ansicht ein. Gedacht fuer fremde Oberflaechen, Karten oder Kamerabilder, fuer die es kein eigenes Widget gibt.","funktionen":[{"name":"URL","beschreibung":"Vollstaendige Adresse der einzubettenden Seite. Solange sie leer ist, steht nur ein Platzhaltertext im Rahmen."},{"name":"Verhalten: Sandbox","beschreibung":"Der Rahmen laeuft mit erlaubten Skripten, Formularen, gleicher Herkunft und Popups (allow-scripts/allow-same-origin/allow-forms/allow-popups), fuellt das Widget vollstaendig aus und hat weissen Hintergrund."},{"name":"Rahmen / Hintergrund / Beschriftung","beschreibung":"Gemeinsame Eigenschaften: Die Umrandung wirkt. Hintergrundfarbe und transparenter Hintergrund sieht man dagegen nicht, sobald eine URL gesetzt ist — der eingebettete Rahmen deckt die Flaeche weiss ab. Das Label wird von diesem Widget nicht ausgegeben."},{"name":"Interaktion","beschreibung":"Gemeinsame Eigenschaft: Seite oeffnen, Lang-Druck auf Seite/Popup, Popup schliessen, Skript-ID. Klicks INNERHALB der eingebetteten Seite erreichen diese Aktionen nicht — sie landen im Rahmen."},{"name":"Sichtbarkeit","beschreibung":"Gemeinsame Eigenschaft: zur Laufzeit anzeigen sowie Steuer-Variable mit Vergleich (wahr, gleich, ungleich, groesser gleich, kleiner gleich)."}],"hinweis":"Viele Seiten verbieten das Einbetten per X-Frame-Options oder CSP und bleiben dann weiss; laeuft die Ansicht ueber HTTPS, wird zusaetzlich jeder HTTP-Inhalt blockiert. Die Felder Variable und Label erscheinen zwar in den Eigenschaften, werden aber nicht ausgewertet.","groesse":[340,260],"demo":{"url":"https://www.openstreetmap.org/export/embed.html?bbox=14.05%2C47.98%2C14.22%2C48.12&layer=mapnik"}},
    "weekplan": {"titel":"Wochenplan","zweck":"Stellt ein Symcon-Wochenplan-Ereignis als Wochenraster dar: je Wochentag (Mo bis So) eine Zeile ueber 24 Stunden mit farbigen Balken fuer die geschalteten Abschnitte. Der heutige Tag wird hervorgehoben und mit einer Jetzt-Marke versehen.","funktionen":[{"name":"Variable","beschreibung":"Gemeinsames Feld, hier aber die ID des Wochenplan-EREIGNISSES (nicht einer Variable). Ohne gueltiges Ereignis bleibt das Raster leer."},{"name":"Schaltzeiten (heute)","beschreibung":"showTimes — blendet unter dem Raster eine Zeile mit den heutigen Ein-Zeitraeumen ein."},{"name":"Markierung jetzt","beschreibung":"nowColor — Farbe der senkrechten Jetzt-Linie in der heutigen Zeile: Warnung, Alert, Akzent, OK, Info oder Neutral (Vorgabe Warnung)."},{"name":"Farben je Zustand","beschreibung":"colors — Liste aus Zustandsname und Farbe. Der Name muss dem Aktionsnamen im Symcon-Wochenplan entsprechen; die Farbe ueberschreibt die im Ereignis hinterlegte. Gewaehlt wird aus den Skin-Farben (#hex oder accent/ok/warn/crit/info), alte #hex-Werte bleiben als 'Eigene' erhalten. Ohne Eintrag gilt die Farbe aus dem Ereignis, ersatzweise ein gedaempftes Grau."},{"name":"Verhalten: Aktualisierung","beschreibung":"Der Plan wird beim Aufbau der Seite und danach im Minutentakt vom Server geholt; es gibt keine Push-Aktualisierung, weil ein Ereignis keine Variable ist."},{"name":"Label / Farben / Rahmen / Typografie","beschreibung":"Gemeinsame Eigenschaften: Ueberschrift ueber dem Raster (leer = 'Wochenplan'), Vorder- und Hintergrundfarbe, Umrandung, transparenter Hintergrund, Schriftart, Gewicht, Stil und -groesse."}],"hinweis":"Das Widget liest nur Ereignisse vom Typ Wochenplan; eine normale Variablen-ID liefert nichts. Bei mehreren Gruppen pro Wochentag wird nur die erste passende Gruppe gezeichnet.","groesse":[360,200],"demo":{"varId":34861,"label":"Pumpen Plan","showTimes":true,"nowColor":"warn","colors":[{"name":"Ein","color":"ok"}]}},
    "windrose": {"titel":"Windrose","zweck":"Kompassrose mit Himmelsrichtungen, deren Nadel die aktuelle Windrichtung zeigt. In der Mitte stehen wahlweise die Windgeschwindigkeit und darunter das Kuerzel der Richtung.","funktionen":[{"name":"Richtung (Var)","beschreibung":"Variablen-ID der Windrichtung (w.varId). Akzeptiert Grad von 0 bis 360 (auch ausserhalb, es wird umgerechnet) oder eine Himmelsrichtung als Text — deutsch N, NNO, NO bis NNW ebenso wie englisch NE, E, SE."},{"name":"Geschw. (Var)","beschreibung":"Optionale Variablen-ID der Windgeschwindigkeit (w.varId2). Der Wert erscheint in der Mitte der Rose."},{"name":"Nachkommastellen","beschreibung":"dec — feste Anzahl Nachkommastellen fuer den Geschwindigkeitswert in der Mitte (0-4). Leer = Symcon-Profilformatierung."},{"name":"Einheit","beschreibung":"unit — eigene Einheit hinter dem Geschwindigkeitswert (z. B. km/h). Sobald Nachkommastellen ODER Einheit gesetzt sind, wird der Rohwert selbst formatiert statt der Profil-Formatierung."},{"name":"Verhalten: Nadel & Kuerzel","beschreibung":"Der Pfeil in der Akzentfarbe zeigt in die Richtung, der Gegenpfeil bleibt gedaempft. Laesst sich der Wert nicht deuten, wird die Nadel fast durchsichtig und in der Mitte steht ein Strich. Unter der Zahl steht die auf 45 Grad gerundete Himmelsrichtung als Kuerzel."},{"name":"Farben / Rahmen / Interaktion","beschreibung":"Gemeinsame Eigenschaften: Hintergrund, Umrandung und transparenter Hintergrund wirken auf die Kachel (Schrift/Farben der Rose kommen fest aus den Skin-Variablen). Interaktion (Seite/Popup oeffnen, Skript) und Sichtbarkeit wie ueblich. Das Feld Variable/Label fehlt bzw. wird nicht dargestellt."}],"hinweis":"Die Bindung erfolgt ueber die beiden eigenen Felder Richtung und Geschwindigkeit (nicht das gemeinsame Variable-Feld). Liefert die Quelle die Richtung als Klartext, muss nach dem Entfernen aller Zeichen ausser N/O/S/W/E genau ein gueltiges Kuerzel uebrig bleiben; ausgeschriebene Woerter wie 'Nordwest' erkennt das Widget nicht.","groesse":[170,170],"demo":{"varId":39204,"varId2":37159}},
    "wsmon": {"titel":"Live-Monitor","zweck":"Diagnose-Widget, das die eingehenden Live-Updates der Ansicht mitschreibt: Uhrzeit, Variablen-ID und Wert je Zeile, mit Punkt in Gruen fuer WebSocket-Push und in Neutralfarbe fuer den Abfrage-Takt. Zeigt auf einen Blick, ob die Verbindung steht.","funktionen":[{"name":"Darstellung","beschreibung":"Standard zeigt das scrollende Fenster mit allen Zeilen; Simple reduziert das Widget auf zwei Punkte (WebSocket und Poll), die bei Aktivitaet aufblitzen und nach 12 s Stille abblenden."},{"name":"Max Zeilen","beschreibung":"max — nur im Standardmodus: wie viele der letzten Updates angezeigt werden, 5 bis 200 (Vorgabe 40)."},{"name":"Quelle","beschreibung":"wsSrc — Filter im Standardmodus: WebSocket und Poll gemeinsam, nur WebSocket oder nur Poll."},{"name":"Nur IDs (optional)","beschreibung":"onlyId — kommagetrennte Liste von Variablen-IDs; dann werden im Standardmodus ausschliesslich deren Updates gezeigt — praktisch, um eine einzelne Variable zu beobachten."},{"name":"Label","beschreibung":"Gemeinsame Eigenschaft: Kopfzeile des Fensters samt Legende WS/Poll. Leeres Label blendet die Kopfzeile aus; im Simple-Modus dient das Label nur als Tooltip."},{"name":"Verhalten: Aktualisierung & Puffer","beschreibung":"Ein gemeinsamer Takt von 0,7 s zeichnet alle Live-Monitore neu, auch die in Leisten und Popups. Mitgeschrieben werden die letzten 500 Updates der Sitzung; die Liste scrollt automatisch mit, solange man am unteren Ende steht. Zu lange Werte werden nach 44 Zeichen abgeschnitten."},{"name":"Verhalten: Fehlergrund","beschreibung":"Kann die WebSocket-Verbindung nicht aufgebaut werden, steht der Grund in Warnfarbe ueber der Liste; ohne Daten erscheint 'warte auf Updates'."}],"hinweis":"Zeigt nur, was diese Ansicht tatsaechlich abonniert hat — Variablen, die auf keiner Seite gebunden sind, tauchen nie auf. Im Bearbeiten-Modus laufen die Updates weiter, aussagekraeftig ist das Widget aber erst im laufenden Betrieb. Das Feld Variable wird nicht ausgewertet.","groesse":[320,220],"demo":{"label":"Live-Updates","max":25,"wsSrc":"both"}},
    "audioroom": {"titel":"Audio · Räume","zweck":"Raum-/Zonen-Selektor der Audio-Familie: eine Leiste aller Audio-Raeume mit Status-Punkt (spielt/Gruppen-Mitglied/leer). Der Klick waehlt den aktiven Raum, den sich alle Audio-Teil-Widgets mit gleicher Session-ID teilen (Now-Playing, Transport, Lautstaerke, Quellen, Multiroom).","funktionen":[{"name":"Session-ID","beschreibung":"Bindeglied der Audio-Familie (Vorgabe „audio\"). Alle Audio-Widgets mit derselben Session-ID teilen sich Raumauswahl und Bedienzustand - so steuern getrennte Kacheln denselben Raum."},{"name":"Stil","beschreibung":"Optik der Raumleiste, gemeinsamer Selektor: Buttons, Pills oder Underline (Tabs)."},{"name":"Räume · Reihenfolge & Anzeige","beschreibung":"Je Widget: die Raeume per ▲▼ ordnen und einzeln per Haekchen ein-/ausblenden. Ausgeblendete verschwinden nur in diesem Selektor. Der Gewerke-Suffix „(Audio)\" wird in der Anzeige entfernt."},{"name":"Status-Punkt","beschreibung":"Farbpunkt je Raum: Akzent = spielt, Info = Gruppen-Mitglied, blass = leer/aus. Der aktive Raum ist hervorgehoben."}],"hinweis":"Teil der Audio-Familie - allein wenig sinnvoll: erst zusammen mit weiteren Audio-Widgets gleicher Session-ID (z. B. Now-Playing, Multiroom) ergibt sich die Bedienung. Ohne geladene Zonen zeigt die Leiste „Audio lädt …\".","groesse":[720,52]},
    "batscan": {"titel":"Jetzt scannen","zweck":"Kleiner Steuer-Button, der den Batterie-Scan des BatteryManager anstoesst (Hook ?api=batscan). Waehrend des Scans wird der Button gesperrt und zeigt „Scan läuft…\"; ein Fortschritt kommt aus einer Progress-Variable.","funktionen":[{"name":"Register-Variable (löst Scan aus)","beschreibung":"String-Register-Variable des BatteryManager (varId). Sie identifiziert die Instanz fuer den Hook; erst wenn sie gesetzt ist, ist der Button aktiv."},{"name":"Fortschritt-Variable (Progress)","beschreibung":"Integer-Variable (varId2): 0 = idle, 1..99 = Scan laeuft. Waehrend eines Werts zwischen 0 und 100 gilt der Scan als aktiv (Button busy)."},{"name":"Beschriftung","beschreibung":"Text auf dem Button im Ruhezustand (Vorgabe „Jetzt scannen\")."},{"name":"Auto-Reset","beschreibung":"Nach 30 s ohne Rueckmeldung oder sobald sich die Register-Variable aendert, faellt der Button in den Ruhezustand zurueck (Timeout-Schutz)."}],"hinweis":"Nur im Run-Modus wirksam (loest wirklich den Scan aus). Ohne Register-Variable bleibt der Button deaktiviert. Gehoert zum BatteryManager - sinnvoll neben einer Batterie-Übersicht (battlist). Kein Hover, standardmaessig ohne Rahmen.","groesse":[210,40]},
    "battlist": {"titel":"Batterie-Übersicht","zweck":"Batterie-Liste aus dem BatteryManager-Register (eine String-Variable mit JSON: counts + devices). Kopf mit drei Tipp-Filter-Chips (Ok / Bald / Leer) und Zaehlern, darunter die Geraeteliste - standardmaessig nur schwache Batterien, am schlimmsten zuerst.","funktionen":[{"name":"Batterie-Register (JSON)","beschreibung":"String-Variable des BatteryManager (varId) mit dem JSON-Register (counts und devices je Geraet: Name, Raum, System, Zustand, Wert, Einheit …). Ohne sie zeigt die Liste einen Hinweis."},{"name":"Titel","beschreibung":"Kopfzeile der Liste (Vorgabe „Batterien\")."},{"name":"Gute anzeigen","beschreibung":"Haengt die vollen/gesunden Batterien (grau) unten an; Vorgabe aus, dann werden nur schwache (warn + empty) gezeigt."},{"name":"Max. Einträge","beschreibung":"Begrenzt die Anzahl gezeigter Zeilen (1–500, Vorgabe 60)."},{"name":"Schrift (Titel / Zeilen)","beschreibung":"Optionale Schriftgroesse in px fuer Titel und Zeilen; leer = automatisch."},{"name":"Filter-Chips (Ok / Bald / Leer)","beschreibung":"Im Live-Modus per Tipp schaltbar; blenden Zustaende ein/aus und werden je Geraet im localStorage gemerkt. Unbekannte (unknown) haben keinen Chip und werden immer grau angehaengt."},{"name":"Sortierung / Toenung","beschreibung":"Am schlimmsten zuerst (leer > schwach > ok > unbekannt), innerhalb nach Wert aufsteigend. Der Kopf toent bei leeren Batterien crit, sonst bei schwachen warn."}],"hinweis":"Braucht das BatteryManager-Register als Quelle - ohne JSON bleibt die Liste leer. Der Chip-Filter ist geraetegebunden gespeichert; „Gute anzeigen\" umzuschalten loescht diese Merkung. Kein Hover.","groesse":[300,220]},
    "mediasources": {"titel":"Medienquellen","zweck":"Zeigt den Status der HomeSuite-Medienprovider (Spotify, Plex, Jellyfin, Audiobookshelf ...) als Liste - je Provider, ob er konfiguriert ist. Bewusst ohne Zugangsdaten-Eingabe: Passwoerter und Tokens werden in der Symcon-Konsole (Hub) gesetzt, nicht in der Visu.","funktionen":[{"name":"Provider-Liste (automatisch)","beschreibung":"Wird per Hub (?api=mod&op=hubmanage, op=mediaProviders) geladen. Je Zeile Name und eine Status-Pille: 'konfiguriert' (gruen) oder 'nicht eingerichtet' (grau)."},{"name":"Spotify verbinden","beschreibung":"Erscheint automatisch, sobald ein Spotify-Provider vorhanden ist. Der Knopf holt ueber den Hub (op=spotifyAuthUrl) den OAuth-Login-Link und oeffnet ihn in einem neuen Tab. Fehlt Client-ID/Secret in der Konsole, kommt ein Hinweis statt eines Links."},{"name":"Aktualisierung (automatisch)","beschreibung":"Der Status wird beim Einblenden geladen und danach etwa alle 60 s ueber den Hub neu abgefragt."},{"name":"Label, Farben, Rahmen, Hintergrund, Interaktion, Sichtbarkeit, Animation, Ebene, X/Y/B/H","beschreibung":"Gemeinsame Eigenschaften. Das Widget selbst hat keine eigenen Konfigurationsfelder, nur den Erklaerungstext."}],"hinweis":"Reines Status-Widget - es aendert nichts an der Einrichtung. Ist der Hub nicht erreichbar, steht 'Hub nicht erreichbar'. Alle Zugangsdaten werden in der Symcon-Konsole am Hub gesetzt, nicht hier.","groesse":[320,240]},
    "poolcfg": {"titel":"Konfig-Tabelle","zweck":"Rendert eine ganze Konfigurations-Seite als EIN Bauteil: eine kompakte Tabelle mit je einer Zeile pro Einstellung, den Editor direkt in der Zelle, gruppiert nach Sektion. Jedes Feld ist an eine eigene schreibbare Variable gebunden. Ersetzt hunderte Einzelkacheln durch eine scanbare, editierbare Tabelle (fuer die Pool-Controller-Konfig gedacht).","funktionen":[{"name":"Eyebrow / Ueberschrift","beschreibung":"Kleine Kopfzeile (eyebrow, Vorgabe POOL CFG - KONFIGURATION) und grosse Titelzeile (h1 bzw. Widget-Label) ueber der Tabelle."},{"name":"Felder (rows)","beschreibung":"Liste der Zeilen: je Feld {vid, label, kind, unit, step, options, section}. section gruppiert die Zeilen in Abschnitte mit eigenem Kopf; die vid-Variablen werden automatisch gepollt und live aktualisiert. Wird i. d. R. per Generator (poolcfg_build) erzeugt."},{"name":"Feldtyp num","beschreibung":"Zahlen-Stepper: Minus/Plus mit einstellbarer Schrittweite (step) plus Direkteingabe; optionale Einheit dahinter. Enter/Verlassen schreibt via setVar (Komma wird zu Punkt normalisiert)."},{"name":"Feldtyp bool","beschreibung":"Toggle-Schalter; Klick schaltet die gebundene Variable um (an/aus)."},{"name":"Feldtyp enum","beschreibung":"Segment-Buttons aus options[{v,t}]; Klick setzt den zugehoerigen Wert (numerisch oder Text)."},{"name":"Feldtyp str","beschreibung":"Freies Texteingabefeld; schreibt den Text bei Aenderung/Enter."},{"name":"Feldtyp ro (read-only)","beschreibung":"Nur Anzeige, nicht editierbar. Ein Abschnitt, dessen Felder alle ro sind, wird kompakt als Chip-Reihe (Wert + Beschriftung) statt als editierbare Zeilen dargestellt."},{"name":"Live-Zellen (kein Feld)","beschreibung":"Aktive Eingabefelder werden bei Live-Updates nicht ueberschrieben (nur wenn nicht fokussiert), damit man beim Tippen nicht unterbrochen wird."}],"hinweis":"Kein Palette-Widget (noPalette) und keine eigene Property-Maske - die Zeilen werden per Generator (poolcfg_build.php) aus den Geraete-Variablen erzeugt. Sehr breite/lange Tabellen scrollen innerhalb der Kachel. Schreiben laeuft ueber setVar (RequestAction) und unterliegt der Geraete-Gate-Logik.","groesse":[1450,600]},
    "scenebar": {"titel":"Szenen-Leiste","zweck":"Licht-Szenen als anklickbare Chips (HomeSuite-Hub, Haus-Ebene): Ein Klick wendet die Szene sofort an. „＋ Aufnehmen“ schnappt den aktuellen Licht-Zustand als neue Szene.","funktionen":[{"name":"Szenen-Chips","beschreibung":"Je Szene ein Chip mit Icon und Name. Klick wendet sie an (sceneapply) und pollt kurz die Ist-Werte nach. Im Schatten-Modus wird optimistisch als Vorschau geschrieben, real erst bei scharf."},{"name":"Scope (Aufnahme-Bereich)","beschreibung":"Ganzes Haus (Vorgabe), Geschoss oder Raum — legt fest, welche Lampen ein neu aufgenommener Snapshot umfasst."},{"name":"Geschoss","beschreibung":"Nur bei Scope Geschoss: Name des Geschosses (z. B. Obergeschoss)."},{"name":"Raum-ID","beschreibung":"Nur bei Scope Raum: Objekt-ID des Raums."},{"name":"Aufnehmen-Button","beschreibung":"Blendet den „＋ Aufnehmen“-Chip ein/aus. Beim Aufnehmen fragt ein Dialog den Szenennamen ab und speichert den aktuellen Zustand im gewählten Scope."},{"name":"Auto-Refresh","beschreibung":"Die Szenenliste wird alle 30 s neu geladen, damit im Editor angelegte Szenen erscheinen."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Position (X/Y/Breite/Höhe), Sichtbarkeit, Einblend-Animation, Ebene."}],"hinweis":"Bedient den HomeSuite-Hub über ?api=light (op=scenes/sceneapply/scenecapture); Schreiben ist token-geschützt. Zum Anlegen/Bearbeiten von Mitgliedern (An/Aus, Helligkeit, Farbe, Überblendzeit) dient der Szenen-Editor. Doku-Vorschau rein lokal.","groesse":[420,64]},
    "shadelog": {"titel":"Beschattung · Log","zweck":"Gesamtlog aller Rollos: zeigt die aggregierten Automatik-Entscheidungen UND manuellen Befehle sämtlicher ShadingDevice-Instanzen chronologisch in einer Tabelle. Nur echte Fahrten; der Schatten-Modus wird markiert.","funktionen":[{"name":"Tabelle","beschreibung":"Spalten Zeit · Raum · Modus · Ist→Ziel · Grund · Status. Zeit heute nur als Uhrzeit, sonst mit Datum; Position als Prozent (· = unbekannt)."},{"name":"Modus-Chip","beschreibung":"Je Eintrag ein Chip „Auto“ oder „Manuell“ — unterscheidet Automatik-Entscheidung von manuellem Befehl."},{"name":"Grund (farbcodiert)","beschreibung":"Sturm (kritisch), Sonne (warm), Zeitplan (info), Automatik (gedämpft), Manuell / Manuell (Stopp) (Akzent), Tür blockiert (Warnung) — jeweils als getönter Grund-Pill."},{"name":"Status","beschreibung":"„scharf“ (Fahrt real ausgeführt) oder „Schatten“ (nur simuliert, nicht am Gerät)."},{"name":"Raum-Filter","beschreibung":"Klappliste über der Tabelle: „Alle Räume (N)“ oder ein einzelner Raum. Optionen entstehen automatisch aus den Log-Daten, die Auswahl bleibt über Refreshes erhalten."},{"name":"Aktualisieren","beschreibung":"↻-Knopf lädt das Log sofort neu; zusätzlich läuft im Betrieb ein automatischer 30-s-Refresh (nicht im Bearbeiten-Modus)."},{"name":"Max. Einträge","beschreibung":"Ringpuffer-Größe 20 bis 1000 (Vorgabe 300) — begrenzt, wie viele Zeilen der Hub liefert."},{"name":"Gemeinsame Eigenschaften","beschreibung":"Position (X/Y/Breite/Höhe), Sichtbarkeit, Einblend-Animation, Ebene."}],"hinweis":"Aggregat über den Hub (?api=shading&op=log), der die getLog-Ringpuffer aller Rollos zusammenführt. Ist das Log nicht lesbar, erscheint „Log nicht lesbar“. Doku-Vorschau mit Beispieldaten.","groesse":[1040,720]},
    "suncompass": {"titel":"Sonnenstandsdiagramm","zweck":"Raeumliche 2,5D-Darstellung EINER Beschattungs-Zone: Polar-Himmelsscheibe (Winkel = Azimut mit Nord oben, Radius = Elevation), Tages-Sonnenbogen mit Auf-/Untergang, das in Fassaden-Richtung gedrehte Haus, die Einstrahlungs-Segmente (Fenster und konfiguriertes Sonnenprofil) und die Live-Sonne mit Glow. Man sieht sofort, ob die Sonne ins Fenster faellt und ob Soll (Profil) zur Ist-Lage passt.","funktionen":[{"name":"Bindung: Modus","beschreibung":"bind – „Session (folgt Auswahl)“ bindet an die shadex-Familie (der Raum-Selektor bestimmt die Zone) oder „Feste Zone“ fuer eine dauerhaft gewaehlte Instanz."},{"name":"Session-ID","beschreibung":"session (Vorgabe „shade“) – gemeinsame Kennung mit den uebrigen Beschattungs-Bausteinen; nur im Session-Modus sichtbar."},{"name":"Zone (Instanz-ID)","beschreibung":"entityId – feste ShadingDevice-Instanz; nur im Modus „Feste Zone“ sichtbar."},{"name":"Akzentfarbe","beschreibung":"accent – Skin-Farbe fuer Haus-Fassade und Betonung im Diagramm."},{"name":"Fenster-Halbwinkel","beschreibung":"sunAcc – halbe Oeffnungsbreite des Besonnungs-Segments in Grad; leer = automatisch aus dem konfigurierten Fenster (azimuthBgn/azimuthEnd des Sonnenprofils)."},{"name":"Standort (Breite / Länge)","beschreibung":"lat / lon – Koordinaten fuer die Sonnenbahn (Vorgabe Hauskoords 48.0657 / 14.1241); die NOAA-Position ist gegen die IPS-Location verifiziert."},{"name":"Badges","beschreibung":"Unter dem Diagramm: „Fenster besonnt“ (ja / außerhalb Fenster / unter Schwelle / Nacht), „Schließung Ist“ (aktuelle Rollo-Position in %) und „Azimut / Höhe“ des aktuellen Sonnenstands."},{"name":"Datenquelle","beschreibung":"Holt Sonnenstand, Sonnenprofil und Ist-Position read-only ueber ?api=mod reconcileProbe der gebundenen Zone; pollt alle 60 s."}],"hinweis":"Ohne gebundene Zone bzw. ohne gesetztes Sonnenstands-Profil erscheint statt des Diagramms ein Hinweis („Kein Sonnenstands-Profil gesetzt“). Die Zone braucht einen aktiven Treiber; sonst meldet das Widget „Zone ohne Treiber“. Der Fassaden-Azimut kommt aus dem Sonnenprofil, nicht aus dem rohen Shadowing-Azimut.","groesse":[360,470]}
};
